-- Lección: india
insert into public.lessons (topic_id, title, body, position, published)
select id, 'India: de los Mauryas a los mogoles', '[{"type":"section","title":"Los Mauryas y el experimento de Ashoka","text":"El imperio Maurya, fundado por Chandragupta hacia 322 a. C. en el vacío que dejó la retirada de Alejandro, fue el primer Estado que controló la mayor parte del subcontinente. Su capital, Pataliputra, impresionó al embajador seléucida Megástenes, cuyo relato conocemos por citas posteriores. La organización administrativa que describe el Arthashastra, tratado atribuido a Kautilya, es la de un Estado intervencionista con espías, monopolios, catastro y una teoría del poder desprovista de sentimentalismo que se ha comparado con Maquiavelo.\n\nAshoka, nieto de Chandragupta, es el gobernante mejor documentado de la Antigüedad india porque dejó su propia voz. Sus edictos, grabados en columnas y rocas por todo el imperio en prácrito y en otras lenguas, incluida una versión griega y aramea en el noroeste, proclaman un giro tras la conquista de Kalinga: arrepentimiento por la matanza, adopción del dharma como política de Estado, no violencia, respeto a todas las sectas religiosas, hospitales y pozos, y funcionarios encargados de vigilar el bienestar de los súbditos.\n\nQué significa exactamente ese dharma es una discusión abierta. Romila Thapar ha argumentado que no era simplemente budismo convertido en religión oficial, sino una ética cívica pensada para cohesionar un imperio de enorme diversidad lingüística y religiosa. Lo que sí está claro es que Ashoka patrocinó al budismo y financió misiones que lo llevaron a Sri Lanka y a Asia central, y que sin ese patrocinio la expansión posterior de la religión hacia China y el sudeste asiático habría sido muy distinta.\n\nEl imperio se desintegró poco después de su muerte, hacia 185 a. C. Le siguieron reinos regionales y una sucesión de dinastías de origen exterior en el noroeste, indogriegas, escitas, partas y kushanas, que acuñaron moneda, patrocinaron arte y conectaron el subcontinente con Asia central y con el comercio de la seda. El arte de Gandhara, con budas de pliegues helenísticos, es el testimonio más visible de ese cruce.\n\nDe esa época proceden también las grandes construcciones de la sociedad india. Los tratados jurídicos, entre ellos las leyes de Manu, codificaron un orden de varnas, las cuatro categorías rituales, que la práctica social articuló en miles de jatis o grupos de nacimiento con reglas de matrimonio y de oficio. Conviene no leer esos textos como descripción de la realidad: son prescripciones de letrados brahmánicos, y la historia social muestra mucha más movilidad y variación regional de la que admiten.","textEso":null,"textBachillerato":null,"callout":"Los edictos de Ashoka son la única voz directa de un gobernante de la Antigüedad india, y se descifraron en 1837. Hasta entonces el rey más citado de los textos budistas era, para la historiografía, un personaje sin pruebas materiales."},{"type":"section","title":"La era clásica: Guptas y creación intelectual","text":"El imperio Gupta, entre los siglos IV y VI, se ha llamado tradicionalmente edad de oro clásica, una etiqueta que la historiografía actual matiza porque procede en parte del nacionalismo del siglo XX. Lo que sí ocurrió fue una concentración extraordinaria de producción intelectual bajo patrocinio cortesano: el teatro y la poesía de Kalidasa, la fijación del sánscrito como lengua culta panindia, la codificación de los sistemas filosóficos y una escultura y pintura que definieron el canon posterior, con Ajanta como testimonio superviviente.\n\nLas matemáticas del período tuvieron consecuencias mundiales. Aryabhata, en el año 499, calculó una aproximación de pi, propuso la rotación de la Tierra y trabajó con un sistema posicional decimal; Brahmagupta, en el siglo VII, formuló reglas para operar con el cero y con números negativos. Ese sistema pasó al mundo islámico, donde al-Juarismi lo difundió, y de allí a Europa con el nombre de cifras arábigas. Es probablemente la transferencia técnica más consecuente de la historia premoderna.\n\nLa vida religiosa se transformó a la vez. El budismo, que había sido dominante, empezó un declive largo en su tierra de origen mientras se consolidaba en el resto de Asia; el jainismo mantuvo comunidades sólidas de comerciantes; y las tradiciones que hoy llamamos hinduismo se reorganizaron en torno al culto a Vishnu, a Shiva y a la Diosa, con templos, peregrinaciones y una relación devocional directa con la divinidad. Sheldon Pollock ha descrito la difusión del sánscrito por Asia como una cosmópolis cultural sin imperio detrás.\n\nLa devoción bhakti, surgida en el sur tamil entre los siglos VI y IX y extendida después a todo el subcontinente, fue un movimiento de enorme alcance social. Sus poetas escribían en lenguas vernáculas, no en sánscrito, ponían la entrega personal por encima del ritual y del linaje, y entre ellos hubo mujeres y personas de castas bajas cuya obra se sigue cantando. Es el mejor argumento contra la imagen de una sociedad india estática y jerárquica sin fisuras.\n\nEl otro gran motor fue el comercio. Los puertos del oeste comerciaban con el mundo romano, como documenta el Periplo del mar Eritreo y confirman los hallazgos de moneda romana en el sur; los del este conectaban con el sudeste asiático, donde las formas políticas, religiosas y artísticas indias se adoptaron sin conquista alguna, de Angkor a Borobudur. La india no exportó imperio: exportó modelos.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"El sur y el océano Índico","text":"La historia del sur del subcontinente sigue un ritmo propio y durante siglos fue más rica y más conectada que la del norte. Los Pallavas y después los Cholas construyeron Estados de base agraria e hidráulica en el país tamil, con templos que funcionaban como centros económicos, escuelas y bancos, y con asambleas de aldea cuyos reglamentos conocemos por inscripciones grabadas en piedra.\n\nEl imperio Chola, en su apogeo entre los siglos X y XII, hizo algo insólito en la historia india: proyectó poder naval. Envió expediciones a Sri Lanka, a las Maldivas y al Srivijaya de Sumatra, y mantuvo relaciones diplomáticas con la China Song. Sus templos, como el de Brihadisvara en Thanjavur, y sus bronces de Shiva danzante están entre las obras más notables del arte mundial.\n\nBurton Stein propuso interpretar esos Estados como reinos segmentarios, con una autoridad ritual central fuerte y un control administrativo real muy limitado en la periferia. Otros historiadores han objetado que las inscripciones muestran una capacidad fiscal considerable. La discusión importa porque afecta a cómo entendemos el Estado premoderno en general: si medimos el poder por el modelo del Estado europeo moderno, casi todo lo demás parece débil por definición.\n\nEl comercio del índico fue durante siglos el sistema económico más dinámico del mundo, y la India su centro geográfico y productivo. Exportaba textiles de algodón, pimienta, azúcar, acero y piedras preciosas hacia el golfo, África oriental, el sudeste asiático y China, e importaba caballos, metales y plata. Comunidades de comerciantes árabes, judíos, armenios y guyaratíes operaban en redes que funcionaban sin Estados detrás, y los documentos de la Geniza de El Cairo permiten reconstruir esos negocios con detalle.\n\nLa llegada de Vasco da Gama a Calicut en 1498 introdujo un elemento nuevo: unos comerciantes dispuestos a usar artillería naval para monopolizar rutas. Los portugueses no dominaron el comercio índico, cuyo volumen los superaba con mucho, pero sí impusieron un sistema de permisos y una violencia armada que no era la práctica del océano. Neerlandeses e ingleses aplicaron después el mismo principio con más capital y mejor organización.","textEso":null,"textBachillerato":null,"callout":"La influencia india en el sudeste asiático, de Angkor a Java, se difundió sin conquista militar. Es uno de los casos mejor documentados de expansión cultural sin imperio."},{"type":"section","title":"El islam y el Sultanato de Delhi","text":"El islam llegó al subcontinente por tres vías distintas y no simultáneas: comerciantes árabes en las costas del sur desde el siglo VII, la conquista de Sind en 711, y las incursiones y después conquistas desde Asia central a partir del siglo XI, con Mahmud de Ghazni y más tarde los ghuríes. La fundación del Sultanato de Delhi en 1206 estableció un poder musulmán estable en el norte que duró tres siglos.\n\nEl sultanato fue un Estado militar y fiscal que introdujo formas administrativas persas e islámicas, el sistema iqta de asignación de rentas a cambio de servicio, moneda de plata y una arquitectura nueva de arcos y cúpulas. Bajo Alauddin Khalji, a comienzos del siglo XIV, se ensayó un control de precios y una reforma fiscal notables, y el sultanato resistió las invasiones mongolas que arrasaron el resto del mundo islámico, lo que convirtió a Delhi en refugio de sabios y artistas.\n\nLa imagen de una conquista islámica que impuso la religión por la fuerza no se sostiene demográficamente. La conversión fue lenta, desigual y sobre todo periférica: las zonas de mayoría musulmana acabaron siendo Bengala oriental y el noroeste, es decir, las regiones de frontera agraria donde el islam llegó con la roturación de tierras y con las órdenes sufíes, no los centros del poder político. Richard Eaton ha documentado ese proceso frente a las explicaciones por la espada o por el patrocinio estatal.\n\nHubo destrucción de templos, está documentada y no debe minimizarse, pero su lógica era en buena parte política: los templos reales eran depósitos de riqueza y símbolos de soberanía, y su saqueo formaba parte de un repertorio que también practicaban los reyes hindúes contra los templos de sus rivales. Reducir siglos de historia a un conflicto religioso continuo es proyectar hacia atrás las categorías del siglo XX.\n\nLo que sí produjo el encuentro fue una síntesis cultural de primer orden. El urdu como lengua, la música indostánica, la arquitectura indoislámica, el sufismo de las órdenes chishti con santuarios visitados por hindúes y musulmanes, y movimientos como el de Kabir o el sijismo fundado por Guru Nanak, que rechazaban explícitamente la frontera entre ambas comunidades. Sur del Vindhya, mientras tanto, Vijayanagara y los sultanatos del Decán mantenían una rivalidad en la que las alianzas cruzaban con frecuencia las líneas religiosas.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"El imperio mogol","text":"Babur, descendiente de Timur y de Gengis Kan, venció en Panipat en 1526 con artillería y caballería móvil y fundó una dinastía que gobernaría la mayor parte del subcontinente durante casi dos siglos. Su nieto Akbar, entre 1556 y 1605, fue quien construyó el imperio como sistema, y lo hizo con tres instrumentos: un ejército y una administración organizados en rangos numéricos, el mansabdari; un sistema fiscal sobre la tierra, el zabt de Todar Mal, basado en medición, clasificación de suelos y promedios de precios; y una política de integración de las élites rajputas y de otras comunidades en el gobierno.\n\nAkbar suprimió el impuesto sobre los no musulmanes, patrocinó traducciones del sánscrito al persa, organizó debates entre teólogos de todas las religiones en su casa de culto y formuló el principio de sulh-i kull, paz o entendimiento universal, que no era tolerancia moderna sino una doctrina de soberanía por encima de las comunidades religiosas. El Ain-i-Akbari de su ministro Abul Fazl es a la vez un manual administrativo y una exposición de esa ideología imperial.\n\nLa economía mogola fue enorme. Bengala y Guyarat producían textiles de algodón que se vendían de Japón a México, y el imperio absorbía plata americana y japonesa en cantidades enormes para pagar por ellos. Las estimaciones sitúan al subcontinente en torno a la cuarta parte del producto mundial en el siglo XVII, con un Estado que recaudaba una proporción alta del excedente agrario y lo gastaba en ejército, corte y construcción.\n\nAurangzeb, que reinó de 1658 a 1707, es el emperador más discutido. Restableció el impuesto a los no musulmanes, ordenó la destrucción de algunos templos, ejecutó al noveno gurú sij y llevó el imperio a su máxima extensión con una guerra interminable en el Decán. La historiografía nacionalista y la comunalista lo han convertido en símbolo, cada una en un sentido. Audrey Truschke y John Richards han insistido en leer sus decisiones en su contexto político: patrocinó también templos hindúes, empleó a más nobles hindúes que ningún predecesor y actuó por cálculo de legitimidad tanto como por convicción.\n\nEl desgaste del Decán, el coste militar y las tensiones entre facciones nobiliarias debilitaron el centro tras su muerte. Durante mucho tiempo se contó como una decadencia que dejó un vacío que los británicos llenaron. La historiografía desde los años ochenta lo ve distinto: lo que hubo fue una regionalización, con Estados sucesores dinámicos, como los marathas, Awadh, Bengala o Haidarabad, con economías activas y capacidad militar. La Compañía Británica no ocupó un vacío: intervino en un sistema competitivo y ganó, empezando por Plassey en 1757.","textEso":null,"textBachillerato":null,"callout":"En el siglo XVII el subcontinente producía en torno a la cuarta parte del producto mundial y sus textiles se vendían de Japón a México. La imagen de una India premoderna pobre es un efecto del siglo XIX, no una constante histórica."},{"type":"section","title":"Herencias historiográficas","text":"La forma en que se estudia la historia india está condicionada por dos herencias que conviene identificar. La primera es la periodización que James Mill propuso en 1817 al dividir el pasado en épocas hindú, musulmana y británica. Esa división convirtió la religión en el criterio organizador de mil años de historia, dio a entender que el gobierno musulmán fue una ocupación extranjera permanente y sirvió de base a las lecturas comunalistas de los siglos XIX y XX. Ninguna de las tres etiquetas describe bien lo que ocurría en el territorio.\n\nLa segunda es la casta. Los administradores coloniales censaron, clasificaron y fijaron por escrito categorías que en la práctica eran fluidas, negociadas y variables por región y por oficio. Nicholas Dirks ha sostenido que la casta tal como se conoce hoy es en buena medida un producto de ese proceso de gobierno; otros historiadores replican que las jerarquías existían con claridad mucho antes y que el argumento puede llegar a exculpar. La posición mayoritaria reconoce raíces antiguas y una rigidez y una centralidad muy aumentadas por la administración colonial.\n\nUna tercera discusión ha resultado especialmente productiva: la del siglo XVIII. Frente al relato de una decadencia general que justificaba la intervención británica, Christopher Bayly, Muzaffar Alam y Sanjay Subrahmanyam mostraron dinamismo comercial, formación de Estados regionales eficaces y grupos financieros indios que fueron, de hecho, socios necesarios de la expansión de la Compañía. El colonialismo se construyó sobre esas estructuras, no sobre su ausencia.\n\nLa consecuencia metodológica vale para cualquier historia no europea. Las fuentes escritas dominantes son de élite, en sánscrito o en persa, y hay que completarlas con inscripciones, arqueología, numismática, documentos comerciales y tradiciones orales para acceder a la vida de la mayoría. Y las categorías con las que se pregunta, Estado, religión, nación, imperio, tienen una historia europea que hay que examinar antes de aplicarlas.\n\nNada de esto convierte la historia india en un caso especial que solo puede compararse consigo mismo. Al contrario: las cuestiones que plantea, sobre las formas de Estado premoderno, sobre la convivencia religiosa y sus límites, sobre el comercio a larga distancia sin imperio y sobre las causas de la divergencia económica, son las mismas que organizan hoy la historia global.","textEso":null,"textBachillerato":null,"callout":null},{"type":"concepts","items":[{"term":"Arthashastra","definition":"Tratado de gobierno atribuido a Kautilya: Estado intervencionista con espías, monopolios y catastro, y una teoría del poder sin apelaciones morales."},{"term":"Edictos de Ashoka","definition":"Inscripciones en roca y columna, en varias lenguas, con la política de dharma del emperador. Única voz directa de un gobernante de la Antigüedad india."},{"term":"Varna y jati","definition":"Cuatro categorías rituales de los textos brahmánicos y los miles de grupos de nacimiento reales, con reglas de matrimonio y oficio, variables por región."},{"term":"Sistema decimal posicional","definition":"Notación con cero desarrollada en la India clásica, transmitida al mundo islámico y de ahí a Europa como cifras arábigas."},{"term":"Bhakti","definition":"Devoción personal a la divinidad expresada en lenguas vernáculas, con poetas mujeres y de castas bajas. Movimiento social además de religioso."},{"term":"Reino segmentario","definition":"Modelo propuesto por Stein para los Estados del sur: autoridad ritual central fuerte y control administrativo limitado en la periferia."},{"term":"Iqta","definition":"Asignación de las rentas de un territorio a un oficial a cambio de servicio militar. Instrumento fiscal del Sultanato de Delhi."},{"term":"Sultanato de Delhi","definition":"Poder musulmán en el norte entre 1206 y 1526. Introdujo administración persa, resistió a los mongoles y transformó la arquitectura."},{"term":"Mansabdari","definition":"Sistema mogol de rangos numéricos que fijaba el estatus, el sueldo y el contingente militar de cada oficial, integrando élites de distintas comunidades."},{"term":"Zabt","definition":"Sistema fiscal de Akbar diseñado por Todar Mal: medición de la tierra, clasificación de suelos y cálculo del impuesto sobre promedios de precios."},{"term":"Sulh-i kull","definition":"Principio de entendimiento universal de Akbar. No es tolerancia moderna, sino una doctrina de soberanía situada por encima de las comunidades religiosas."},{"term":"Sijismo","definition":"Tradición fundada por Guru Nanak a comienzos del siglo XVI que rechaza la frontera entre hinduismo e islam y la jerarquía ritual de casta."},{"term":"Estados sucesores","definition":"Poderes regionales que sustituyeron al centro mogol en el siglo XVIII, como marathas, Awadh o Bengala. Eran dinámicos, no un vacío de poder."},{"term":"Periodización de Mill","definition":"División colonial del pasado indio en épocas hindú, musulmana y británica. Convirtió la religión en criterio organizador de mil años de historia."}]},{"type":"debates","items":[{"question":"¿Es la casta una institución inmemorial o una construcción colonial?","positions":[{"school":"Construcción colonial (Dirks, 2001)","argument":"Los censos y la clasificación administrativa británica fijaron por escrito categorías fluidas y negociadas, y convirtieron la casta en el principio organizador de la sociedad india tal como hoy se percibe."},{"school":"Raíces antiguas","argument":"Los textos jurídicos, las inscripciones y las prácticas de endogamia documentan jerarquías rituales y ocupacionales muy anteriores a cualquier presencia europea, y el argumento colonial puede acabar exculpando."}],"state":"La posición mayoritaria reconoce raíces antiguas y a la vez una rigidez, una uniformidad y una centralidad política considerablemente aumentadas por la administración colonial."},{"question":"¿Cómo debe interpretarse el gobierno mogol en materia religiosa?","positions":[{"school":"Lectura comunalista","argument":"La destrucción de templos, el impuesto a los no musulmanes y las ejecuciones de líderes religiosos muestran un dominio extranjero de carácter confesional sobre una población mayoritariamente hindú."},{"school":"Contexto político (Richards; Truschke; Eaton)","argument":"Los templos reales eran depósitos de riqueza y símbolos de soberanía, y su saqueo era un repertorio que también practicaban reyes hindúes. Aurangzeb patrocinó templos y empleó a más nobles hindúes que ningún predecesor."}],"state":"La historiografía académica rechaza el marco confesional continuo, sin negar episodios de violencia religiosa documentados. La discusión tiene hoy una carga política intensa en la India."},{"question":"¿Fue el siglo XVIII indio una decadencia o una regionalización?","positions":[{"school":"Decadencia del centro (Athar Ali)","argument":"La crisis del sistema mansabdari, la escasez de asignaciones y el desgaste militar del Decán descompusieron el imperio y dejaron un vacío de poder que la Compañía ocupó."},{"school":"Estados sucesores dinámicos (Bayly; Alam; Subrahmanyam)","argument":"Marathas, Awadh, Bengala y Haidarabad tenían economías activas, capacidad fiscal y militar y grupos financieros potentes. La Compañía intervino en un sistema competitivo y ganó, no llenó un vacío."}],"state":"La segunda lectura predomina desde los años ochenta y ha cambiado la explicación de la conquista británica: se construyó sobre estructuras indias existentes, no sobre su ausencia."}]},{"type":"timeline","items":[{"date":"c. 322 a. C.","event":"Chandragupta Maurya funda el primer imperio que domina la mayor parte del subcontinente."},{"date":"c. 268–232 a. C.","event":"Reinado de Ashoka: edictos grabados en roca y difusión del budismo tras la conquista de Kalinga."},{"date":"320–550","event":"Imperio Gupta. Época clásica del sánscrito, la astronomía y la matemática con Aryabhata."},{"date":"siglos VI–IX","event":"Auge de la devoción bhakti en el sur y expansión de los templos dravídicos."},{"date":"985–1044","event":"Apogeo del imperio Chola: expediciones navales al sudeste asiático y comercio en el índico."},{"date":"1206","event":"Fundación del Sultanato de Delhi. El islam se convierte en poder político en el norte."},{"date":"1336–1565","event":"Imperio de Vijayanagara en el sur, contemporáneo y rival de los sultanatos del Decán."},{"date":"1498","event":"Vasco da Gama llega a Calicut. Comienza la presencia europea en el comercio índico."},{"date":"1526","event":"Babur vence en Panipat y funda la dinastía mogola."},{"date":"1556–1605","event":"Reinado de Akbar: sistema fiscal zabt, mansabdari y política de sulh-i kull o paz universal."},{"date":"1632–1653","event":"Construcción del Taj Mahal bajo Shah Jahan, cumbre de la síntesis arquitectónica indoislámica."},{"date":"1658–1707","event":"Reinado de Aurangzeb: máxima extensión mogola y desgaste militar en el Decán."},{"date":"1757","event":"Batalla de Plassey: la Compañía Británica de las Indias Orientales toma el control de Bengala."}]},{"type":"sources","items":[{"author":"Kautilya","title":"Arthashastra","year":"siglos IV a. C.–II d. C.","kind":"primaria","note":"Manual de gobierno y estrategia. Su datación es discutida y su contenido, un retrato del Estado ideal más que del real."},{"author":"Ashoka","title":"Edictos mayores en roca y columna","year":"siglo III a. C.","kind":"primaria","note":"Descifrados en 1837 por James Prinsep. Fuente directa de la política de dharma imperial."},{"author":"Anónimo","title":"Periplo del mar Eritreo","year":"siglo I","kind":"primaria","note":"Guía comercial griega de los puertos del índico. Documenta el comercio entre Roma y la India."},{"author":"Autores brahmánicos","title":"Manusmriti o leyes de Manu","year":"siglos II a. C.–III d. C.","kind":"primaria","note":"Texto prescriptivo sobre el orden social. No describe la práctica: propone un ideal de letrados."},{"author":"Faxian y Xuanzang","title":"Relatos de peregrinos chinos","year":"399–414 y 629–645","kind":"primaria","note":"Descripción externa de la India Gupta y posgupta por monjes budistas que buscaban textos."},{"author":"Al-Biruni","title":"Tarij al-Hind","year":"c. 1030","kind":"primaria","note":"Estudio de la ciencia, la religión y la sociedad indias por un sabio jorasmio. Etnografía notablemente rigurosa para su época."},{"author":"Ibn Battuta","title":"Rihla","year":"c. 1355","kind":"primaria","note":"Relato de su servicio como juez en el Sultanato de Delhi bajo Muhammad bin Tughluq."},{"author":"Babur","title":"Baburnama","year":"c. 1530","kind":"primaria","note":"Memorias del fundador de la dinastía mogola. Autobiografía excepcional por su franqueza y su detalle."},{"author":"Abul Fazl","title":"Ain-i-Akbari","year":"c. 1590","kind":"primaria","note":"Manual administrativo y estadístico del imperio de Akbar y exposición de su ideología de soberanía."},{"author":"Guru Arjan y otros","title":"Guru Granth Sahib","year":"1604","kind":"primaria","note":"Escritura sij que recoge himnos de autores sijs, hindúes y musulmanes de distintas castas."},{"author":"François Bernier","title":"Viajes por el imperio mogol","year":"1670","kind":"primaria","note":"Relato de un médico francés en la corte. Fuente valiosa y origen de tópicos europeos sobre el despotismo oriental."},{"author":"Documentos de la Geniza de El Cairo","title":"Cartas de comerciantes del índico","year":"siglos XI–XIII","kind":"primaria","note":"Correspondencia mercantil que permite reconstruir el comercio entre Egipto, Arabia y la costa de Malabar."},{"author":"James Mill","title":"Historia de la India británica","year":"1817","kind":"estudio","note":"Origen de la periodización en épocas hindú, musulmana y británica que condicionó dos siglos de historiografía."},{"author":"Romila Thapar","title":"La India antigua","year":"2002","kind":"estudio","note":"Síntesis de referencia sobre el período antiguo y crítica sistemática de las lecturas nacionalistas."},{"author":"Burton Stein","title":"Peasant State and Society in Medieval South India","year":"1980","kind":"estudio","note":"Propone el modelo del reino segmentario para los Estados del sur."},{"author":"Irfan Habib","title":"The Agrarian System of Mughal India","year":"1963","kind":"estudio","note":"Estudio clásico de la economía agraria y fiscal del imperio mogol."},{"author":"Christopher Bayly","title":"Rulers, Townsmen and Bazaars","year":"1983","kind":"estudio","note":"Muestra el dinamismo comercial indio del siglo XVIII y el papel de los financieros locales en la expansión británica."},{"author":"Richard Eaton","title":"The Rise of Islam and the Bengal Frontier","year":"1993","kind":"estudio","note":"Explica la conversión al islam por la roturación agraria de frontera, frente a las tesis de la espada o del patrocinio."},{"author":"John F. Richards","title":"The Mughal Empire","year":"1993","kind":"estudio","note":"Síntesis de referencia sobre las instituciones y la economía del imperio mogol."},{"author":"Nicholas Dirks","title":"Castes of Mind","year":"2001","kind":"estudio","note":"Sostiene que la casta tal como se conoce hoy es en gran medida producto del gobierno colonial."},{"author":"Sheldon Pollock","title":"The Language of the Gods in the World of Men","year":"2006","kind":"estudio","note":"Analiza la difusión del sánscrito por Asia como una cosmópolis cultural sin imperio detrás."},{"author":"Audrey Truschke","title":"Aurangzeb","year":"2017","kind":"estudio","note":"Relectura del emperador más discutido a partir de fuentes persas, contra sus dos usos políticos actuales."},{"author":"Upinder Singh","title":"A History of Ancient and Early Medieval India","year":"2008","kind":"estudio","note":"Manual universitario que integra arqueología, epigrafía y textos con criterio explícito de método."}]},{"type":"images","items":[{"src":"/img/india/portada.jpg","alt":"El Taj Mahal de mármol blanco con su cúpula bulbosa y los cuatro minaretes, reflejado en el estanque del jardín","width":1200,"height":989,"role":"portada","caption":"El Taj Mahal, mausoleo mogol construido entre 1632 y 1653.","author":"Dhirad , picture edited by J. A. Knudsen","title":"Taj Mahal in March 2004","year":"2004","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Taj_Mahal_in_March_2004.jpg"},{"src":"/img/india/sarnath.jpg","alt":"Capitel de piedra pulida con cuatro leones sentados espalda contra espalda sobre un ábaco con ruedas y animales","width":1200,"height":2168,"role":"figura","section":0,"caption":"Capitel de Sarnath, del pilar de Ashoka, siglo III a. C. Es hoy el emblema del Estado indio: la rueda del ábaco está en su bandera.","author":"Public.Resource.Org, photographed in Sept. 1951 in India (Indian Governement ASI)","title":"Sarnath lion Ashoka 3rd century BCE India","year":"1951","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Sarnath_lion_Ashoka_3rd_century_BCE_India.jpg"},{"src":"/img/india/sanchi.jpg","alt":"Cúpula maciza de ladrillo y piedra rodeada por una barandilla circular, con una puerta tallada de varios dinteles","width":1200,"height":800,"role":"figura","section":1,"caption":"La gran estupa de Sanchi. Empezada bajo Ashoka y ampliada después: el budismo se difundió con apoyo real y con las rutas comerciales.","author":"Bernard Gagnon","title":"Stupa 1, Sanchi 02","year":"2013","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Stupa_1%2C_Sanchi_02.jpg"},{"src":"/img/india/akbar.jpg","alt":"Miniatura mogola de un jinete dominando a un elefante desbocado que cruza un puente de barcas mientras la gente huye","width":1200,"height":1763,"role":"figura","section":4,"caption":"Akbar domando al elefante Hawai, del Akbarnama, hacia 1590. La pintura de corte mogola mezcla técnica persa, tema indio y perspectiva aprendida de grabados europeos.","author":"Miniatur der Moghulschule, Indien, datiert 1609-10","title":"Kaiser Akbar bändigt einen Elefanten","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Kaiser_Akbar_b%C3%A4ndigt_einen_Elefanten.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'india'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: industrializacion
insert into public.lessons (topic_id, title, body, position, published)
select id, 'La revolución industrial', '[{"type":"section","title":"¿Por qué allí y por qué entonces?","text":"La pregunta tiene sentido porque en 1700 la ventaja europea no era evidente. Kenneth Pomeranz mostró en 2000 que las regiones más avanzadas de China, como el delta del Yangtsé, tenían niveles de vida, esperanza de vida, mercados de tierra y trabajo y sofisticación comercial comparables a los de Inglaterra. Su explicación de la gran divergencia es doble y contingente: el carbón británico estaba cerca de la superficie y de los centros de consumo, y las colonias americanas aportaron lo que él llama acres fantasma, tierras que suministraban algodón, azúcar y madera sin consumir suelo europeo.\n\nRobert Allen ofreció en 2009 una explicación económica más precisa. Gran Bretaña era una economía de salarios altos y energía barata: pagar a un obrero costaba mucho y quemar carbón costaba poco, de modo que las máquinas que sustituían trabajo por energía resultaban rentables allí y no en Francia, la India o China, donde la mano de obra era barata. La spinning jenny se difundió en Lancashire y no en Bengala porque el cálculo económico era distinto, no porque faltara ingenio.\n\nJoel Mokyr subraya un tercer factor: la Ilustración industrial. Existía en Gran Bretaña una cultura de conocimiento útil que conectaba filósofos naturales, ingenieros y artesanos mediante sociedades como la Lunar Society, publicaciones baratas, patentes y una actitud favorable a la mejora práctica. Sin esa circulación no se explica que las máquinas se perfeccionasen de forma acumulativa durante un siglo.\n\nA esto se añade el argumento institucional de Douglass North y Barry Weingast: tras 1688 el compromiso creíble del Parlamento sobre impuestos y deuda, junto con la seguridad de la propiedad, redujo el riesgo de invertir a largo plazo. Se le objeta que muchas instituciones citadas existían antes o también en otros lugares.\n\nLa historiografía actual combina los cuatro factores en vez de elegir uno: recursos y geografía, precios relativos, cultura técnica e instituciones. Y añade un quinto, más incómodo, del que se hablará al final: la economía atlántica del azúcar, el algodón y la esclavitud.","textEso":null,"textBachillerato":null,"callout":"Allen: la mecanización se adoptó donde el trabajo era caro y la energía barata. La spinning jenny era rentable en Lancashire y ruinosa en Bengala."},{"type":"section","title":"Las máquinas y sus ritmos","text":"El algodón fue el sector piloto porque partía casi de cero, no tenía gremios que lo protegieran y su materia prima llegaba del Atlántico. La lanzadera volante aceleró el tejido y creó un cuello de botella en el hilado; lo resolvieron la jenny de Hargreaves, adecuada al trabajo doméstico, la water frame de Arkwright, que exigía energía hidráulica y por tanto edificio, horario y vigilancia, y la mule de Crompton, que combinaba finura y resistencia. La fábrica nace de la máquina que no cabe en una casa.\n\nLa energía siguió un camino propio. La máquina atmosférica de Newcomen, de 1712, era ineficiente pero servía para achicar agua en bocamina, donde el carbón no costaba nada. El condensador separado de Watt, patentado en 1769 y comercializado desde 1776, redujo el consumo lo bastante para sacar el vapor de la mina y llevarlo a la fábrica; el movimiento rotativo hizo el resto. La alta presión, ya en el siglo XIX, permitió el transporte.\n\nLa siderurgia se liberó del bosque con el coque de Darby y multiplicó su producto con el pudelado y el laminado de Cort, que hacían hierro dulce en cantidad. Con hierro barato y vapor de alta presión llegó el ferrocarril: Stockton-Darlington en 1825, Liverpool-Manchester en 1830, y a partir de ahí una fiebre inversora que reorganizó mercados, husos horarios y finanzas.\n\nConviene medir la velocidad real. Nicholas Crafts y Knick Harley recalcularon las series y encontraron un crecimiento del producto por habitante de en torno al uno por ciento anual entre 1780 y 1830. Es transformador a escala de siglo y modesto a escala de década. En 1830 la mayoría de los trabajadores británicos no estaban en fábricas mecanizadas, sino en la agricultura, el servicio doméstico y talleres artesanales.\n\nDe ahí el consenso actual: revolución en la estructura, gradualismo en los agregados. Cambió qué se producía, dónde, con qué energía y bajo qué disciplina, mucho antes de que cambiaran de forma llamativa las cifras del producto nacional.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"La fábrica, el reloj y la resistencia","text":"Edward P. Thompson describió en 1967 la transformación más profunda y menos visible: el paso de una orientación por tareas, propia del trabajo agrario y artesanal, a una disciplina del tiempo medido. En la fábrica se paga por horas, se multa el retraso, se prohíbe el San Lunes y se sincroniza a cientos de personas con un reloj que a menudo controla el patrón. La escuela, el sermón y el manual de conducta enseñaron esa nueva relación con el tiempo.\n\nEl trabajo infantil no lo inventó la fábrica; lo hizo visible, lo concentró y lo sometió a horario. La Comisión Sadler de 1832 recogió testimonios de jornadas de doce a dieciséis horas, castigos físicos y deformaciones óseas. La Factory Act de 1833 prohibió emplear a menores de nueve años en la industria textil, limitó las jornadas por tramos de edad y creó algo decisivo: un cuerpo de inspectores. La Mines Act de 1842 prohibió el trabajo subterráneo de mujeres y de niños menores de diez años, y la ley de las diez horas llegó en 1847.\n\nEl ludismo se malinterpreta como odio irracional a la técnica. Los luditas de 1811-1816 eran trabajadores cualificados que destruían selectivamente las máquinas empleadas para abaratar el producto degradando la calidad y saltándose las costumbres del oficio, en un contexto en que las coaliciones obreras estaban prohibidas por las Combination Acts y no existía cauce legal de negociación. Romper máquinas era, como escribió Eric Hobsbawm, negociación colectiva por otros medios. El Parlamento respondió con pena capital.\n\nThompson sostuvo en 1963 que la clase obrera no fue un producto automático de las máquinas sino una identidad construida en esa experiencia: sociedades de socorro mutuo, prensa radical, capillas disidentes, cartismo. Es la formulación que desplazó el determinismo económico en la historia social británica.","textEso":null,"textBachillerato":null,"callout":"Los luditas no atacaban a las máquinas en general: destruían las que degradaban el producto y rompían las costumbres del oficio. Con las coaliciones prohibidas, era la única negociación disponible."},{"type":"section","title":"La ciudad industrial","text":"Manchester pasó de unos veinticinco mil habitantes a mediados del siglo XVIII a más de trescientos mil un siglo después. Ese crecimiento se produjo sin alcantarillado, sin agua corriente y sin regulación de la vivienda, con casas espalda contra espalda, sótanos habitados y letrinas compartidas por decenas de familias.\n\nEl resultado fue lo que los demógrafos llaman penalización urbana: en las grandes ciudades industriales de los años treinta y cuarenta la esperanza de vida al nacer podía quedar en torno a los treinta años, muy por debajo de la del campo, y la mortalidad infantil superaba con holgura la rural. El tifus, la tuberculosis y sobre todo el cólera, llegado en 1831 y de nuevo en 1848, golpearon a esas poblaciones.\n\nLa respuesta llegó por vía estadística. Edwin Chadwick publicó en 1842 un informe que correlacionaba mortalidad, hacinamiento y saneamiento y defendía, con argumentos utilitaristas de coste público, la intervención estatal en agua y alcantarillado; de ahí salió la Public Health Act de 1848. John Snow demostró en 1854, cartografiando los casos alrededor de la bomba de Broad Street, que el cólera se transmitía por el agua y no por miasmas, aunque su tesis tardó años en aceptarse.\n\nLa contaminación fue el otro coste. El carbón que movía las fábricas llenó las ciudades de humo y hollín, y las nieblas letales continuaron hasta bien entrado el siglo XX. La industrialización británica es también el inicio documentado de la emisión masiva de dióxido de carbono, un dato que la historiografía ambiental ha incorporado al balance.\n\nCon el tiempo la ciudad industrial produjo sus propias soluciones: parques públicos, traídas de agua, hospitales, transporte urbano, escuelas y una legislación municipal que a finales de siglo había reducido de forma drástica la mortalidad. Pero ese resultado llegó dos generaciones después de quienes pagaron el coste inicial.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"Difusión desigual","text":"Bélgica industrializó pronto por su carbón y su siderurgia; Francia siguió un camino distinto, con más peso de la pequeña propiedad agraria, de los productos de calidad y de una transición demográfica temprana. Patrick OBrien y Çağlar Keyder argumentaron que ese camino no fue un fracaso frente al modelo británico sino una vía alternativa con rentas per cápita comparables a largo plazo.\n\nAlemania despegó después de 1850 y lo hizo con rasgos propios: bancos universales que financiaban a largo plazo, cárteles, escuelas técnicas y politécnicas, e industrias basadas en la ciencia como la química de tintes y la electrotecnia. Estados Unidos desarrolló el llamado sistema americano de manufacturas, con piezas intercambiables y maquinaria especializada, favorecido por la escasez de mano de obra y la abundancia de recursos.\n\nFuera de Occidente, Japón es el caso de industrialización dirigida desde el Estado tras la Restauración Meiji de 1868: envío de estudiantes, contratación de ingenieros extranjeros, empresas públicas vendidas después a grupos privados y un esfuerzo educativo masivo.\n\nLa otra cara es la desindustrialización colonial. La India producía en el siglo XVIII una parte muy alta de los textiles del mundo; entre 1810 y 1860 esa industria se hundió frente al hilado mecánico británico, en un contexto de aranceles asimétricos y de dominio político. Se discute cuánto pesó la tecnología y cuánto la política comercial, pero el hecho está establecido: la industrialización de unos coincidió con la desindustrialización de otros.\n\nA partir de 1870 llega la segunda revolución industrial: acero Bessemer y Siemens-Martin, química orgánica, electricidad, motor de combustión interna, taylorismo y producción en cadena. El liderazgo tecnológico se desplaza de Gran Bretaña a Alemania y Estados Unidos, y la investigación se institucionaliza en laboratorios de empresa y universidades técnicas.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"Los grandes debates","text":"El primero es el nivel de vida. Los optimistas, con Peter Lindert y Jeffrey Williamson, calcularon que los salarios reales casi se duplicaron entre 1820 y 1850. Los pesimistas, siguiendo a Charles Feinstein, obtienen mejoras mucho más modestas hasta mediados de siglo. La antropometría añadió un dato difícil de rebatir: la estatura media de los varones británicos disminuyó en las cohortes nacidas entre 1820 y 1850, señal de peor nutrición neta y de más enfermedad en la infancia.\n\nRobert Allen sintetizó la discusión con la expresión pausa de Engels: entre 1790 y 1840 la producción por trabajador creció y los salarios reales apenas, de modo que el excedente fue a beneficios y a inversión. La mejora general llega a partir de 1850. Es decir, tenían razón los pesimistas para la primera generación y los optimistas para la segunda.\n\nEl segundo debate es el de la gran divergencia. Frente a Pomeranz, Robert Allen y Stephen Broadberry sostienen que Europa noroccidental ya llevaba ventaja antes de 1750, con salarios y productividad agraria superiores desde la crisis del siglo XIV. La discusión se dirime hoy con series de salarios, precios y producto reconstruidas para China, la India, Japón y Europa, y el punto de divergencia tiende a situarse antes de lo que proponía Pomeranz, sin volver a las explicaciones culturales del siglo XIX.\n\nEl tercero es el papel de la esclavitud y del imperio. Eric Williams sostuvo en 1944 que los beneficios de la trata y del azúcar financiaron la industrialización británica y que la abolición respondió a intereses económicos, no solo a la moral. Décadas de crítica redujeron el peso cuantitativo directo de esos beneficios; investigaciones recientes, como las de Sven Beckert sobre el capitalismo del algodón, han recuperado la conexión por otra vía: el algodón esclavista del sur de Estados Unidos alimentó Lancashire, y el imperio proporcionó mercados protegidos y materias primas.\n\nEl cuarto es el de la palabra misma. Desde Toynbee y Ashton se habló de revolución; el gradualismo cuantitativo de Crafts y Harley pareció desmentirla. La salida generalmente aceptada distingue niveles: en tasas agregadas de crecimiento el proceso fue lento; en estructura productiva, en fuentes de energía, en organización del trabajo y en efectos sobre el planeta fue una ruptura sin precedentes desde el Neolítico.","textEso":null,"textBachillerato":null,"callout":"La pausa de Engels: entre 1790 y 1840 la producción por trabajador sube y los salarios reales no. Los pesimistas tienen razón sobre la primera generación; los optimistas, sobre la segunda."},{"type":"concepts","items":[{"term":"Sistema doméstico","definition":"Organización previa a la fábrica: el comerciante reparte materia prima a familias que trabajan en casa a destajo."},{"term":"Water frame","definition":"Hiladora de Arkwright movida por agua. Al no caber en una casa, obliga a construir la fábrica con horario y vigilancia."},{"term":"Condensador separado","definition":"Mejora de Watt que reduce el consumo de carbón lo bastante para sacar el vapor de la bocamina y llevarlo a la fábrica."},{"term":"Pudelado","definition":"Proceso de Cort para obtener hierro dulce en grandes cantidades sin carbón vegetal. Base del ferrocarril y la construcción metálica."},{"term":"Acres fantasma","definition":"Concepto de Pomeranz: tierras coloniales que suministran algodón, azúcar y madera sin consumir suelo europeo."},{"term":"Economía de salarios altos","definition":"Tesis de Allen: trabajo caro y energía barata hacen rentable mecanizar en Gran Bretaña y no en Asia."},{"term":"Ilustración industrial","definition":"Concepto de Mokyr: cultura de conocimiento útil que conecta filósofos naturales, ingenieros y artesanos."},{"term":"Disciplina del tiempo","definition":"Paso de la orientación por tareas al tiempo medido y remunerado por horas. Analizado por E. P. Thompson en 1967."},{"term":"Ludismo","definition":"Destrucción selectiva de máquinas por trabajadores cualificados entre 1811 y 1816, con las coaliciones obreras prohibidas por ley."},{"term":"Factory Acts","definition":"Leyes fabriles británicas desde 1833. La novedad decisiva no fue el límite de edad sino el cuerpo de inspectores."},{"term":"Penalización urbana","definition":"Exceso de mortalidad de las ciudades industriales frente al campo antes del saneamiento de la segunda mitad del siglo."},{"term":"Pausa de Engels","definition":"Periodo de 1790-1840 en que crece la producción por trabajador y no los salarios reales. Formulación de Allen."},{"term":"Gran divergencia","definition":"Separación de los niveles de renta entre Europa noroccidental y Asia. Su fecha y sus causas son el gran debate abierto."},{"term":"Segunda revolución industrial","definition":"Ciclo de 1870-1914: acero, química, electricidad y motor de explosión, con investigación institucionalizada en laboratorios."}]},{"type":"debates","items":[{"question":"¿Por qué en Gran Bretaña y no en China o la India?","positions":[{"school":"Contingencia ecológica (Pomeranz, 2000)","argument":"El delta del Yangtsé era comparable a Inglaterra en 1750. La diferencia la marcaron el carbón accesible y los acres fantasma del Atlántico, no una superioridad europea previa."},{"school":"Precios relativos (Allen, 2009)","argument":"Solo donde el trabajo era caro y la energía barata resultaba rentable inventar y adoptar máquinas ahorradoras de mano de obra."},{"school":"Cultura del conocimiento útil (Mokyr) e instituciones (North y Weingast)","argument":"La circulación entre ciencia y taller, las patentes y el compromiso creíble del Parlamento tras 1688 sostuvieron una mejora técnica acumulativa durante un siglo."}],"state":"Se combinan los factores en lugar de elegir uno. La cronología de la divergencia tiende a adelantarse respecto a Pomeranz, sin recuperar las explicaciones culturales decimonónicas sobre la supuesta inmovilidad asiática."},{"question":"¿Mejoró el nivel de vida de los trabajadores?","positions":[{"school":"Optimistas (Lindert y Williamson)","argument":"Los salarios reales casi se duplicaron entre 1820 y 1850; el consumo de bienes básicos y la oferta de empleo aumentaron."},{"school":"Pesimistas (Feinstein y la antropometría)","argument":"Las mejoras salariales fueron modestas hasta mediados de siglo y la estatura media descendió en las cohortes nacidas entre 1820 y 1850: peor nutrición neta y más enfermedad infantil."}],"state":"La pausa de Engels concilia ambos datos: crecimiento sin reparto entre 1790 y 1840 y mejora general a partir de 1850. La discusión se ha desplazado a la salud, la mortalidad y el tiempo de trabajo, no solo al salario."},{"question":"¿Cuánto pesaron la esclavitud y el imperio?","positions":[{"school":"Tesis de Williams (1944)","argument":"Los beneficios de la trata y del azúcar financiaron la industrialización, y la abolición respondió al declive económico del sistema esclavista, no solo a la conciencia moral."},{"school":"Crítica cuantitativa","argument":"Los beneficios directos de la trata fueron una fracción pequeña de la inversión británica total; el ahorro interno y la agricultura explican la mayor parte del capital."},{"school":"Nueva historia del capitalismo (Beckert, 2014)","argument":"La conexión es estructural más que contable: el algodón esclavista del sur de Estados Unidos abasteció a Lancashire y el imperio aportó mercados protegidos y materias primas."}],"state":"Se rechaza la versión fuerte de Williams sobre la financiación directa y se acepta la interdependencia estructural entre economía atlántica esclavista e industria textil británica."}]},{"type":"timeline","items":[{"date":"1709","event":"Abraham Darby funde hierro con coque en Coalbrookdale y libera a la siderurgia del carbón vegetal."},{"date":"1712","event":"La máquina atmosférica de Newcomen achica agua en las minas de carbón."},{"date":"1764–1779","event":"Spinning jenny, water frame y mule multiplican la productividad del hilado de algodón."},{"date":"1776","event":"Watt comercializa la máquina de condensador separado; Smith publica *La riqueza de las naciones*."},{"date":"1784","event":"Cort patenta el pudelado y el laminado: hierro dulce en cantidad industrial."},{"date":"1811–1816","event":"Movimiento ludita en el norte de Inglaterra; el Parlamento castiga con pena capital romper máquinas."},{"date":"1825–1830","event":"Stockton-Darlington y Liverpool-Manchester inauguran el ferrocarril de vapor."},{"date":"1832–1833","event":"Comisión Sadler y primera Factory Act con inspectores para hacerla cumplir."},{"date":"1842","event":"Informe Chadwick sobre las condiciones sanitarias y Mines Act contra el trabajo subterráneo de mujeres y niños."},{"date":"1845","event":"Engels publica *La situación de la clase obrera en Inglaterra*."},{"date":"1851","event":"Gran Exposición de Londres: el Reino Unido produce en torno a la mitad del hierro del mundo."},{"date":"1870–1914","event":"Segunda revolución industrial: acero, química, electricidad y motor de explosión, con liderazgo alemán y estadounidense."}]},{"type":"sources","items":[{"author":"Adam Smith","title":"La riqueza de las naciones","year":"1776","kind":"primaria","note":"La fábrica de alfileres como análisis pionero de la división del trabajo y su efecto sobre la productividad."},{"author":"Comisión Sadler","title":"Informe sobre el trabajo infantil en las fábricas","year":"1832","kind":"primaria","note":"Testimonios de jornadas de doce a dieciséis horas, castigos físicos y deformaciones óseas."},{"author":"Parlamento británico","title":"Factory Act","year":"1833","kind":"primaria","note":"Límites de edad y jornada en la industria textil y, sobre todo, creación de inspectores."},{"author":"Andrew Ure","title":"The Philosophy of Manufactures","year":"1835","kind":"primaria","note":"Defensa entusiasta del sistema fabril y de la disciplina que impone. Contrapunto imprescindible a Engels."},{"author":"Edwin Chadwick","title":"Informe sobre las condiciones sanitarias de la población trabajadora","year":"1842","kind":"primaria","note":"Correlaciona mortalidad, hacinamiento y saneamiento con argumentos de coste público."},{"author":"Friedrich Engels","title":"La situación de la clase obrera en Inglaterra","year":"1845","kind":"primaria","note":"Observación directa de Manchester. Fuente y a la vez alegato: debe leerse como ambas cosas."},{"author":"Charles Dickens","title":"Tiempos difíciles","year":"1854","kind":"primaria","note":"Coketown como retrato literario del utilitarismo industrial y de la ciudad del humo."},{"author":"John Snow","title":"Sobre el modo de transmisión del cólera","year":"1855","kind":"primaria","note":"La cartografía de los casos de Broad Street frente a la teoría miasmática dominante."},{"author":"Karl Marx","title":"El capital, libro I","year":"1867","kind":"primaria","note":"Jornada laboral, maquinaria y gran industria a partir de los informes de los inspectores de fábricas."},{"author":"Arnold Toynbee","title":"Lectures on the Industrial Revolution","year":"1884","kind":"primaria","note":"Difunde el término y fija la imagen de ruptura catastrófica que discutirá el siglo XX."},{"author":"T. S. Ashton","title":"La revolución industrial","year":"1948","kind":"estudio","note":"Síntesis optimista clásica: sin industrialización, la población creciente habría vivido peor."},{"author":"Eric Williams","title":"Capitalismo y esclavitud","year":"1944","kind":"estudio","note":"Relaciona trata, azúcar, acumulación británica y abolición. Muy discutido y nunca irrelevante."},{"author":"E. P. Thompson","title":"La formación de la clase obrera en Inglaterra","year":"1963","kind":"estudio","note":"La clase como experiencia y construcción cultural, no como efecto automático de las máquinas."},{"author":"E. P. Thompson","title":"Tiempo, disciplina de trabajo y capitalismo industrial","year":"1967","kind":"estudio","note":"Del trabajo orientado por tareas al tiempo medido y remunerado por horas."},{"author":"Eric Hobsbawm","title":"Industria e imperio","year":"1968","kind":"estudio","note":"Interpreta el ludismo como negociación colectiva por otros medios en ausencia de derechos sindicales."},{"author":"David Landes","title":"Prometeo desencadenado","year":"1969","kind":"estudio","note":"Historia técnica comparada del cambio industrial en Europa occidental."},{"author":"Peter Lindert y Jeffrey Williamson","title":"English Workers Living Standards during the Industrial Revolution","year":"1983","kind":"estudio","note":"Revisión optimista de los salarios reales entre 1820 y 1850."},{"author":"Nicholas Crafts","title":"British Economic Growth during the Industrial Revolution","year":"1985","kind":"estudio","note":"Recalcula las series y obtiene un crecimiento agregado mucho más lento del supuesto."},{"author":"Charles Feinstein","title":"Pessimism Perpetuated","year":"1998","kind":"estudio","note":"Réplica pesimista: mejoras salariales modestas hasta mediados del siglo XIX."},{"author":"Kenneth Pomeranz","title":"La gran divergencia","year":"2000","kind":"estudio","note":"Compara el delta del Yangtsé con Inglaterra y explica la separación por carbón y colonias."},{"author":"Robert C. Allen","title":"The British Industrial Revolution in Global Perspective","year":"2009","kind":"estudio","note":"Salarios altos, energía barata y la pausa de Engels como claves del proceso."},{"author":"Joel Mokyr","title":"The Enlightened Economy","year":"2009","kind":"estudio","note":"La Ilustración industrial y la circulación del conocimiento útil como motor de la mejora acumulativa."},{"author":"Sven Beckert","title":"El imperio del algodón","year":"2014","kind":"estudio","note":"Cadena global del algodón: esclavitud, imperio y fábrica como un mismo sistema."}]},{"type":"images","items":[{"src":"/img/industrializacion/portada.jpg","alt":"Paisaje nocturno con las llamas y el humo rojizo de unos altos hornos iluminando el valle","width":1200,"height":767,"role":"portada","caption":"Coalbrookdale de noche, de Philip James de Loutherbourg (1801).","author":"Philip James de Loutherbourg","title":"Coalbrookdale by Night","year":"1801","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Philipp_Jakob_Loutherbourg_d._J._002.jpg"},{"src":"/img/industrializacion/jenny.jpg","alt":"Grabado de una máquina de madera con un bastidor de husos verticales y una rueda lateral accionada a mano","width":1200,"height":991,"role":"figura","section":1,"caption":"La spinning jenny de Hargreaves, hacia 1764. Multiplicaba por ocho lo que hilaba una persona y aún funcionaba dentro de una casa.","author":"Markus Schweiß","title":"Spinning jenny","year":"2004","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Spinning_jenny.jpg"},{"src":"/img/industrializacion/telares.jpg","alt":"Grabado del interior de una fábrica con hileras de telares mecánicos, mujeres atendiéndolos y ejes de transmisión en el techo","width":1200,"height":775,"role":"figura","section":2,"caption":"Sala de telares mecánicos, 1835. El eje del techo impone el ritmo a todos a la vez: la fábrica vende disciplina horaria antes que máquinas.","author":"Illustrator T. Allom, Engraver J. Tingle","title":"Powerloom weaving in 1835","year":"1835","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Powerloom_weaving_in_1835.jpg"},{"src":"/img/industrializacion/dore-londres.jpg","alt":"Grabado de patios traseros de viviendas obreras apiñadas junto a un viaducto de ferrocarril, con ropa tendida y chimeneas","width":1200,"height":982,"role":"figura","section":3,"caption":"Londres visto por Gustave Doré en London: a Pilgrimage (1872). La ciudad industrial creció más deprisa que su alcantarillado.","author":"Gustave Doré","title":"YCBA London a Pilgrimage 06","year":"1872","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:YCBA_London_a_Pilgrimage_06.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'industrializacion'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: islam
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Nacimiento y expansión del islam', '[{"type":"section","title":"Arabia antes del islam: no un vacío","text":"La tradición islámica llama yahiliyya —«ignorancia»— al periodo preislámico, y esa etiqueta ha alimentado la idea de una Arabia aislada y primitiva. La investigación reciente ofrece otra imagen: una península integrada en los circuitos comerciales y políticos de su época, con reinos organizados en el sur (Yemen), federaciones tribales clientes de Bizancio y Persia en el norte, y una presencia significativa de comunidades judías y cristianas.\n\nLa Meca era un centro de peregrinación en torno a la Kaaba y un nudo comercial de importancia discutida. Patricia Crone cuestionó en *Meccan Trade and the Rise of Islam* (1987) la imagen de una gran ciudad mercantil intermediaria del comercio de especias, señalando que las fuentes contemporáneas apenas la mencionan.\n\nEl contexto geopolítico es decisivo. La guerra entre Bizancio y la Persia sasánida de 602-628 dejó a ambos imperios exhaustos, endeudados y con sus sistemas defensivos y clientelares en el norte de Arabia desarticulados. Cuando llegaron los ejércitos árabes, se enfrentaron a dos potencias en su peor momento del siglo.\n\nLa sociedad árabe era tribal y sin Estado. La lealtad se organizaba por linajes, la justicia se aplicaba por venganza de sangre y la protección dependía del grupo. La aportación política del islam fue precisamente sustituir ese vínculo por otro: la umma, comunidad de creyentes que trasciende el parentesco.","textEso":"La Arabia anterior al islam no era un desierto vacío. Por la península pasaban las rutas del incienso y de las especias, había ciudades comerciales como La Meca, reinos agrícolas en el sur, en el actual Yemen, y tribus que combinaban ganadería y comercio. Convivían cultos politeístas con comunidades judías y cristianas bien establecidas, así que la idea de un dios único no era nueva allí. La Kaaba de La Meca ya era un santuario de peregrinación antes del islam.","textBachillerato":"La imagen de una Arabia preislámica aislada y bárbara procede en buena parte de la propia tradición islámica, que llama a ese periodo yahiliyya, tiempo de ignorancia. La documentación arqueológica y epigráfica desmiente ese cuadro.\n\nLa península estaba integrada en las redes comerciales que unían el océano Índico con el Mediterráneo, tenía reinos agrícolas desarrollados en el sur, con sistemas de regadío notables, y ciudades caravaneras en el norte. Había comunidades judías y cristianas asentadas desde hacía siglos, y entre los propios árabes existía una corriente monoteísta, los hanif. Bizancio y Persia intervenían mediante Estados clientes en las fronteras. El islam, por tanto, no surge en un vacío religioso ni cultural: reorganiza materiales que ya estaban ahí, empezando por un santuario de peregrinación preexistente.","callout":"La hégira de 622 no conmemora la revelación, sino la fundación de una comunidad política en Medina. Que el calendario islámico empiece ahí, y no en 610, dice mucho sobre lo que se consideró el acontecimiento fundacional."},{"type":"section","title":"Mahoma, el Corán y el problema de las fuentes","text":"Según la tradición, Mahoma comenzó a recibir revelaciones hacia 610 y predicó en La Meca un mensaje de monoteísmo estricto, juicio final y justicia social que le enfrentó a la élite de la ciudad. En 622 emigró a Yathrib, que pasó a llamarse Medina, donde actuó como árbitro entre clanes enfrentados y organizó una comunidad con dimensión política, militar y jurídica.\n\nEl Corán se considera en el islam palabra divina literal e increada, transmitida en árabe. Se organiza en 114 azoras ordenadas aproximadamente por longitud, no cronológicamente, lo que dificulta su lectura histórica. La tradición sitúa su fijación escrita bajo el califa Utmán, hacia 650.\n\nEl problema metodológico central es que las fuentes narrativas sobre la vida de Mahoma —la sira de Ibn Ishaq, transmitida por Ibn Hisham, y las grandes colecciones de hadices— se compilaron entre siglo y medio y dos siglos después de los hechos. La propia tradición islámica desarrolló una ciencia crítica para evaluarlas, el estudio del isnad o cadena de transmisores, con criterios estrictos de fiabilidad.\n\nLa crítica occidental ha ido más lejos. La escuela revisionista de los años setenta —John Wansbrough, Patricia Crone y Michael Cook en *Hagarism* (1977)— propuso que el corpus islámico se habría formado más tarde y fuera de Arabia. Sus tesis más radicales no se han sostenido: los manuscritos de Saná, hallados en 1972, y las dataciones por radiocarbono de folios coránicos muy tempranos, como el de Birmingham, apuntan a una fijación textual temprana y estable.\n\nLa posición mayoritaria hoy es intermedia: el Corán como texto es muy antiguo y coherente, mientras que los relatos biográficos posteriores deben tratarse con la misma cautela crítica que se aplica a cualquier hagiografía tardía.","textEso":"Mahoma nació en La Meca hacia 570 y era comerciante. Según la tradición islámica, hacia los cuarenta años empezó a recibir revelaciones que después se recogieron en el Corán. Su predicación de un dios único chocó con las élites de La Meca y en 622 emigró a Medina: esa emigración, la hégira, marca el año uno del calendario musulmán. En Medina no fue solo un profeta, sino el jefe de una comunidad con leyes y ejército. Cuando murió en 632, casi toda Arabia estaba bajo su autoridad.","textBachillerato":"La biografía tradicional de Mahoma —nacimiento hacia 570, revelaciones desde 610, hégira a Medina en 622, comunidad política y militar, muerte en 632— procede de fuentes islámicas escritas al menos un siglo después de los hechos: la sira de Ibn Ishaq se conserva solo en una edición posterior, y los hadices se recopilaron y criticaron en los siglos IX y X.\n\nEsa distancia ha generado un debate historiográfico intenso. Una corriente revisionista ha cuestionado la cronología y la localización tradicionales; otra sostiene que el método crítico islámico de transmisión es más fiable de lo que se le concede. Los hallazgos materiales han pesado: el manuscrito coránico de Birmingham, datado por radiocarbono en la primera mitad del siglo VII, avala una fijación temprana del texto. La conclusión razonable es que el marco general se sostiene, mientras que los detalles biográficos deben tratarse con la misma prudencia que se aplica a cualquier fuente hagiográfica.","callout":null},{"type":"section","title":"La expansión: cómo explicarla","text":"Entre 634 y 711, los ejércitos árabes tomaron Siria, Mesopotamia, Egipto, Persia entera, el norte de África y la península ibérica. Es una de las expansiones más rápidas de la historia y ha recibido explicaciones muy distintas.\n\nLa explicación religiosa por sí sola es insuficiente: no explica por qué antes no ocurrió, ni por qué las conquistas se detuvieron donde lo hicieron. La explicación del fanatismo, habitual en la historiografía europea del siglo XIX, es sobre todo un prejuicio: las conquistas siguieron patrones militares y políticos convencionales, con tratados, pactos de capitulación y negociación con élites locales.\n\nLos factores que la investigación actual pondera son varios. El agotamiento mutuo de Bizancio y Persia tras veintiséis años de guerra dejó a ambos sin reservas ni fronteras defendidas. Las poblaciones de Siria y Egipto, mayoritariamente cristianas monofisitas perseguidas por la ortodoxia imperial, no tenían motivos fuertes para defender a Constantinopla. Y la nueva estructura tributaria fue, al menos inicialmente, más ligera que la bizantina o la sasánida.\n\nA ello se suma un factor interno: la unificación de las tribus árabes bajo la umma canalizó hacia el exterior una energía militar que antes se consumía en conflictos internos, y el reparto del botín proporcionó un incentivo material continuado.\n\nLas conversiones fueron lentas. Richard Bulliet estimó, a partir de la evolución de la onomástica, que las poblaciones conquistadas no alcanzaron mayoría musulmana hasta los siglos IX o X, doscientos o trescientos años después de la conquista. El estatuto de dhimmi —protegido— reconocía a judíos y cristianos libertad de culto y autonomía jurídica a cambio del impuesto de capitación (yizia), en un régimen de subordinación legal pero de tolerancia práctica muy superior a la contemporánea en Europa. De hecho, la conversión masiva reducía los ingresos fiscales, lo que durante décadas hizo que los gobernantes omeyas no la fomentaran.","textEso":"En un siglo, los ejércitos árabes conquistaron desde la península ibérica hasta la India. Es una de las expansiones más rápidas de la historia y no se explica solo por la fe. Persia y Bizancio acababan de agotarse en una guerra larguísima entre ellos. En muchas provincias la población estaba descontenta con sus gobernantes y los impuestos nuevos no eran peores. Y los conquistadores no obligaron a convertirse: judíos y cristianos podían mantener su religión pagando un impuesto especial.","textBachillerato":"En poco más de un siglo, entre 632 y 750, el dominio islámico se extendió desde el Atlántico hasta el Indo. La explicación puramente religiosa es insuficiente y la puramente militar también: los ejércitos árabes no eran especialmente numerosos ni tecnológicamente superiores.\n\nPesan varios factores. El vacío de poder dejado por el agotamiento mutuo de Bizancio y la Persia sasánida tras décadas de guerra. El descontento de poblaciones provinciales —monofisitas en Siria y Egipto, perseguidas por Constantinopla— que en muchos casos no defendieron activamente el orden anterior. Una fiscalidad que al principio no fue más gravosa. Y, decisivo, una política de tolerancia jurídicamente regulada: judíos, cristianos y zoroastrianos conservaban su culto como dimmíes a cambio de la yizia. La conversión de la mayoría de la población fue un proceso lento, de siglos, no un efecto inmediato de la conquista.","callout":"La batalla de Poitiers (732) fue magnificada por la historiografía francesa del siglo XIX como salvación de Europa. Se trató probablemente de la derrota de una expedición de saqueo; el repliegue musulmán del sur de Francia respondió más a problemas internos que a esa derrota."},{"type":"section","title":"La primera fitna y la división suní-chií","text":"Mahoma murió en 632 sin designar sucesor de forma inequívoca ni dejar un procedimiento establecido. La cuestión de quién debía dirigir la comunidad produjo la escisión más duradera del islam.\n\nLos cuatro primeros califas —Abu Bakr, Umar, Utmán y Alí— reciben en la tradición suní el nombre de Rashidun, «bien guiados». Pero tres de los cuatro murieron asesinados, y el conflicto entre Alí, primo y yerno del Profeta, y Muawiya, gobernador de Siria, desembocó en la primera guerra civil (656-661).\n\nDe ese conflicto surgieron tres posiciones. Los partidarios de Alí (shiat Alí, de donde «chiíes») sostenían que el liderazgo correspondía a los descendientes del Profeta por línea de Alí y Fátima, y atribuían al imán una autoridad espiritual. Los que después se llamarían suníes aceptaron la legitimidad de los califas efectivos y la primacía de la sunna, la práctica del Profeta. Los jariyíes, tercera posición, sostenían que el liderazgo correspondía al más piadoso con independencia de su linaje, y llegaron a considerar apóstata a quien no compartiera su rigorismo.\n\nLa muerte de Husayn, hijo de Alí, en Kerbala en 680 a manos de tropas omeyas convirtió la disputa política en identidad religiosa. Su conmemoración anual, la Ashura, sigue siendo el centro emocional del chiismo.\n\nEs importante evitar dos errores frecuentes. El primero, presentar la división como una guerra teológica permanente: durante largos periodos suníes y chiíes convivieron sin conflicto abierto, y las diferencias doctrinales son menores que las que separan a las confesiones cristianas. El segundo, proyectar sobre el pasado los alineamientos sectarios contemporáneos, que responden en buena medida a la política del siglo XX.","textEso":"Al morir Mahoma surgió la pregunta de quién debía sucederle, y de ahí nace la división que aún separa al mundo musulmán. Para los que serían suníes, el sucesor debía ser el más capaz elegido por la comunidad. Para los que serían chiíes, tenía que ser de la familia del Profeta, empezando por su primo y yerno Alí. El conflicto derivó en guerra civil y en el asesinato de Husein, hijo de Alí, en Kerbala en 680, un episodio central en la memoria chií.","textBachillerato":"La muerte de Mahoma sin dejar norma sucesoria abrió el problema central de la historia política islámica: quién puede dirigir la comunidad y con qué legitimidad. La respuesta que acabaría llamándose suní situaba la elección en la comunidad y su consenso; la que llamamos chií exigía el linaje del Profeta a través de Alí, su primo y yerno.\n\nEl conflicto se hizo armado en la primera fitna, con el asesinato de Uzmán, el enfrentamiento entre Alí y Muawiya y el arbitraje que dio origen también a una tercera corriente, los jariyíes. El asesinato de Husein en Kerbala en 680 se convirtió en el acontecimiento fundacional de la memoria chií, conmemorado cada año en la Ashura. Conviene evitar la lectura anacrónica: durante siglos las diferencias fueron sobre todo de autoridad legítima, y su conversión en línea de fractura geopolítica es un fenómeno moderno.","callout":null},{"type":"section","title":"El califato abasí y la edad de oro científica","text":"La revolución abasí de 750 desplazó a los omeyas y trasladó el centro de gravedad de Damasco a Irak, con la fundación de Bagdad en 762. El cambio fue también social: el nuevo régimen integró a los mawali —musulmanes no árabes, sobre todo persas—, cuya marginación había sido una de las causas de la revuelta. La administración adoptó modelos persas y el Estado se burocratizó.\n\nEntre los siglos IX y XI se produjo el llamado movimiento de traducción, sin equivalente en la historia hasta entonces. Bajo patrocinio califal y de élites privadas, se vertieron al árabe las obras científicas y filosóficas griegas, persas e indias: Aristóteles, Galeno, Ptolomeo, Euclides, Dioscórides. Dimitri Gutas ha subrayado que no fue un fenómeno espontáneo ni una simple curiosidad erudita, sino una política de Estado sostenida durante dos siglos y respaldada por una demanda social real.\n\nLa aportación no fue de mera conservación. Al-Juarismi sistematizó el álgebra —la palabra procede de su tratado— e introdujo la numeración posicional india, incluido el cero, que llegaría a Europa como «números arábigos». Ibn al-Haytham (Alhacén) refutó la teoría de la visión por emisión y estableció un método experimental riguroso en óptica. Ibn Sina (Avicena) escribió el *Canon de medicina*, manual universitario europeo hasta el siglo XVII. Al-Razi describió clínicamente la viruela y el sarampión. Ibn Jaldún, ya en el siglo XIV, propuso en su *Muqaddima* una explicación de la formación y decadencia de los Estados basada en la asabiyya o cohesión de grupo, que muchos consideran el primer tratado de sociología histórica.\n\nLa expresión «edad de oro» requiere matices. La producción científica no fue homogénea en el tiempo ni en el espacio, y no toda ella fue obra de musulmanes: cristianos nestorianos, judíos y zoroastrianos participaron de forma central, empezando por los traductores. Tampoco existió una «ciencia islámica» unitaria: hubo tensiones recurrentes entre la filosofía de inspiración griega (falsafa) y la teología, expresadas por ejemplo en la crítica de al-Ghazali a los filósofos y en la respuesta de Averroes.\n\nLa tesis de un declive causado por al-Ghazali y por el cierre de la interpretación religiosa se repite mucho y está desacreditada: la producción científica continuó siglos después, con la escuela astronómica de Maragha en el siglo XIII, cuyos modelos matemáticos aparecen después en Copérnico, y con la observación otomana y mogola en la Edad Moderna.","textEso":"Con la dinastía abasí y la fundación de Bagdad en 762, el mundo islámico vivió siglos de esplendor científico. En la Casa de la Sabiduría se tradujeron al árabe las obras griegas, persas e indias, y sobre ellas se construyó: al-Juarismi dio nombre al algoritmo y desarrolló el álgebra, Ibn Sina escribió un tratado de medicina que se usó en Europa durante siglos, y de la India llegó el sistema de numeración con el cero que hoy llamamos, precisamente, números árabes.","textBachillerato":"El califato abasí, con capital en Bagdad desde 762, desplazó el centro de gravedad hacia Persia e inauguró la etapa de mayor productividad científica del mundo islámico. La Casa de la Sabiduría organizó un programa sistemático de traducción del griego, el persa y el sánscrito al árabe, financiado por el califato y por mecenas privados.\n\nLo relevante es que no fue mera conservación. Al-Juarismi sistematizó el álgebra como disciplina y su nombre latinizado dio la palabra algoritmo; Ibn al-Haytham desarrolló una óptica basada en la experimentación que influyó directamente en la ciencia europea posterior; Ibn Sina escribió el Canon de medicina, manual universitario en Europa hasta el siglo XVII; se adoptó y difundió la numeración posicional india con el cero. Se ha discutido si hubo un declive posterior por rechazo teológico a la filosofía; la investigación reciente muestra actividad científica de alto nivel bastante después de esa supuesta ruptura.","callout":"La transmisión no fue solo de textos griegos. El papel llegó de China tras la batalla de Talas (751), y su difusión abarató drásticamente la producción de libros en el mundo islámico siglos antes que en Europa."},{"type":"section","title":"Fragmentación política y transmisión a Europa","text":"La unidad política del califato duró poco. Ya en 756 un omeya superviviente fundó un emirato independiente en Córdoba, que sería califato en 929. Los fatimíes chiíes establecieron un califato rival en Egipto en 909 y fundaron El Cairo. Desde el siglo X, el poder efectivo en Bagdad pasó a manos de dinastías militares —buyíes, después selyúcidas turcos—, mientras el califa conservaba una autoridad simbólica.\n\nEl golpe final llegó con los mongoles: en 1258 Hulagu tomó Bagdad, ejecutó al último califa abasí y destruyó la ciudad, incluidas sus bibliotecas y buena parte de su sistema de irrigación. La cifra de víctimas que dan las fuentes es probablemente exagerada, pero el fin del califato como institución universal es un hecho.\n\nLa transmisión del saber árabe a Europa fue masiva y está bien documentada. Los centros fueron sobre todo Toledo, tras 1085, y Sicilia. En Toledo, traductores como Gerardo de Cremona vertieron al latín, con frecuencia a través de intermediarios judíos y mozárabes, cientos de obras: el *Almagesto* de Ptolomeo, el corpus aristotélico con los comentarios de Averroes, la medicina de Avicena, el álgebra y la óptica.\n\nEl impacto fue estructural. La recuperación de Aristóteles reorganizó la filosofía escolástica y obligó a Tomás de Aquino a una síntesis entre razón y fe; la medicina árabe fundó los currículos de Montpellier, Bolonia y Salerno; la numeración posicional transformó la contabilidad y el comercio. El vocabulario castellano conserva el rastro: álgebra, algoritmo, cifra, azúcar, alcohol, alquimia, almanaque, cenit, azimut.\n\nEl relato habitual de una Europa que «redescubre» la Antigüedad clásica en el Renacimiento omite este eslabón. Los textos griegos no reaparecieron por generación espontánea: llegaron traducidos, comentados y ampliados por una tradición intelectual que había trabajado sobre ellos durante cinco siglos.","textEso":"A partir del siglo X el califato se rompió en poderes distintos: Córdoba, El Cairo, Bagdad. Pero justo en esa fragmentación las cortes competían por atraer sabios y el nivel cultural siguió altísimo. Y ahí está una de las herencias mayores: buena parte de Aristóteles, Galeno o Ptolomeo llegó a Europa traducida del árabe, en Toledo y en Sicilia. Sin ese paso, la ciencia y la filosofía europeas medievales habrían sido muy distintas.","textBachillerato":"Desde el siglo X el califato unificado se disgrega: califato omeya de Córdoba, fatimí en El Cairo, abasí reducido a autoridad nominal, y luego dinastías turcas y bereberes. La fragmentación política no supuso decadencia cultural inmediata, sino todo lo contrario: la competencia entre cortes por atraer sabios multiplicó los centros de producción intelectual.\n\nLa transmisión hacia Europa fue una consecuencia mayor. En Toledo tras 1085 y en la Sicilia normanda, equipos de traductores vertieron al latín obras científicas y filosóficas griegas conservadas y comentadas en árabe, junto con la producción original islámica. Aristóteles llega a las universidades europeas del siglo XIII en buena medida por esa vía y con los comentarios de Averroes. Presentar al mundo islámico solo como conservador de un legado ajeno es inexacto: lo que se transmitió incluía matemáticas, óptica, medicina y astronomía originales.","callout":null},{"type":"concepts","items":[{"term":"Umma","definition":"Comunidad de creyentes que sustituye al parentesco tribal como vínculo político primario."},{"term":"Hégira","definition":"Emigración a Medina en 622. Marca el año 1 del calendario islámico, lunar y de 354 días."},{"term":"Califa","definition":"«Sucesor»: jefe político de la comunidad. No es profeta ni tiene autoridad para revelar."},{"term":"Sunna","definition":"Práctica y dichos del Profeta, transmitidos en los hadices. Segunda fuente del derecho tras el Corán."},{"term":"Isnad","definition":"Cadena de transmisores de un hadiz. Su análisis es la ciencia crítica desarrollada por la tradición islámica."},{"term":"Fitna","definition":"Guerra civil o discordia dentro de la comunidad musulmana."},{"term":"Dhimmi","definition":"Protegido: judío o cristiano con libertad de culto y autonomía jurídica a cambio del impuesto de capitación."},{"term":"Yizia","definition":"Impuesto personal pagado por los no musulmanes. Su cuantía desincentivó durante décadas las conversiones."},{"term":"Mawali","definition":"Musulmanes no árabes, sobre todo persas. Su marginación bajo los omeyas alimentó la revolución abasí."},{"term":"Falsafa","definition":"Filosofía de inspiración griega en el mundo islámico, en tensión recurrente con la teología."},{"term":"Asabiyya","definition":"Cohesión de grupo. Concepto central de Ibn Jaldún para explicar el auge y la caída de los Estados."}]},{"type":"debates","items":[{"question":"¿Qué explica la rapidez de la expansión islámica?","positions":[{"school":"Explicación religiosa o del «fanatismo» (historiografía europea del siglo XIX)","argument":"El impulso de una fe nueva y militante habría lanzado a los árabes a una guerra santa continua contra el mundo circundante, sin más cálculo que la conversión o el sometimiento."},{"school":"Explicación coyuntural y estructural (Donner, Kennedy)","argument":"Bizancio y Persia estaban exhaustos tras veintiséis años de guerra; las poblaciones monofisitas de Siria y Egipto no tenían motivos para defender a Constantinopla; la fiscalidad inicial fue más ligera; y la unificación tribal canalizó hacia fuera una energía militar antes consumida internamente."}],"state":"Se rechaza la explicación por el fanatismo: las conquistas siguieron patrones militares convencionales, con tratados y pactos de capitulación. Se discute cuánto pesó la motivación religiosa frente al botín y a la lógica de Estado, y se subraya que las conversiones fueron lentas: no hubo mayoría musulmana hasta los siglos IX-X."},{"question":"¿Cuándo se fijó el texto coránico?","positions":[{"school":"Revisionismo radical (Wansbrough; Crone y Cook, 1977)","argument":"El corpus islámico se habría formado entre uno y dos siglos después, fuera de Arabia, como construcción retrospectiva. La escasez de fuentes contemporáneas externas justificaría la sospecha."},{"school":"Fijación temprana (paleografía y radiocarbono)","argument":"Los manuscritos de Saná (1972) y las dataciones de folios como el de Birmingham apuntan a un texto estable muy temprano, coherente con la tradición que lo sitúa bajo Utmán hacia 650."}],"state":"Las tesis revisionistas radicales no se han sostenido frente a la evidencia manuscrita. La posición mayoritaria distingue entre el Corán, texto antiguo y estable, y los relatos biográficos posteriores, que exigen la misma cautela crítica que cualquier hagiografía tardía."},{"question":"¿Hubo un «declive» de la ciencia islámica y a qué se debió?","positions":[{"school":"Tesis del cierre religioso","argument":"La crítica de al-Ghazali a los filósofos y el llamado «cierre de las puertas del iytihad» habrían sofocado la investigación racional, provocando un estancamiento a partir del siglo XII."},{"school":"Crítica a la tesis (Saliba, Gutas)","argument":"La producción científica continuó siglos: la escuela astronómica de Maragha en el siglo XIII desarrolló modelos matemáticos que reaparecen en Copérnico, y hubo actividad relevante en el mundo otomano y mogol. El «declive» sería más bien un desplazamiento relativo tras la revolución científica europea."}],"state":"La tesis del cierre religioso está desacreditada entre especialistas, aunque sigue muy difundida. Se investiga hoy por qué la ciencia islámica no dio el paso institucional que sí dio Europa en el siglo XVII, con explicaciones centradas en la financiación, las universidades y la imprenta más que en la teología."}]},{"type":"timeline","items":[{"date":"c. 570","event":"Nacimiento de Mahoma en La Meca."},{"date":"610","event":"Inicio de la revelación coránica según la tradición islámica."},{"date":"622","event":"Hégira: emigración a Yathrib (Medina). Año 1 del calendario islámico."},{"date":"630","event":"Toma de La Meca."},{"date":"632","event":"Muerte de Mahoma; comienza el califato de los Rashidun."},{"date":"636–642","event":"Conquista de Siria, Mesopotamia, Egipto y del Imperio sasánida."},{"date":"656–661","event":"Primera fitna: guerra civil y origen de la división entre suníes y chiíes."},{"date":"661–750","event":"Califato omeya, con capital en Damasco."},{"date":"711","event":"Desembarco en la península ibérica; inicio de al-Ándalus."},{"date":"732","event":"Batalla de Poitiers frente a Carlos Martel."},{"date":"750","event":"Revolución abasí; traslado del poder hacia Irak."},{"date":"762","event":"Fundación de Bagdad."},{"date":"c. 820–1000","event":"Movimiento de traducción y esplendor científico abasí."},{"date":"929","event":"Abd al-Rahman III proclama el califato de Córdoba."},{"date":"1258","event":"Los mongoles destruyen Bagdad; fin del califato abasí."}]},{"type":"sources","items":[{"author":"Anónimo (tradición)","title":"Corán","year":"fijado c. 650","kind":"primaria","note":"114 azoras ordenadas por longitud, no cronológicamente. Fuente primera del derecho y la doctrina."},{"author":"Ibn Ishaq / Ibn Hisham","title":"Sirat Rasul Allah","year":"c. 760 / c. 830","kind":"primaria","note":"Biografía canónica del Profeta, conservada en la recensión posterior de Ibn Hisham."},{"author":"Al-Tabari","title":"Historia de los profetas y los reyes","year":"c. 915","kind":"primaria","note":"Gran compilación histórica que conserva versiones divergentes con sus cadenas de transmisión."},{"author":"Ibn Jaldún","title":"Muqaddima","year":"1377","kind":"primaria","note":"Teoría de la asabiyya y del ciclo de los Estados. Considerado precursor de la sociología histórica."},{"author":"Averroes (Ibn Rushd)","title":"Tahafut al-Tahafut","year":"c. 1180","kind":"primaria","note":"Respuesta a al-Ghazali en defensa de la filosofía. Sus comentarios a Aristóteles marcaron la escolástica latina."},{"author":"Patricia Crone y Michael Cook","title":"Hagarism: The Making of the Islamic World","year":"1977","kind":"estudio","note":"Manifiesto revisionista. Sus tesis fuertes no se sostienen, pero renovó el debate metodológico."},{"author":"Richard W. Bulliet","title":"Conversion to Islam in the Medieval Period","year":"1979","kind":"estudio","note":"Reconstruye el ritmo lento de las conversiones a partir de la onomástica."},{"author":"Fred M. Donner","title":"The Early Islamic Conquests","year":"1981","kind":"estudio","note":"Análisis de los factores militares, tribales y estatales de la expansión."},{"author":"Dimitri Gutas","title":"Greek Thought, Arabic Culture","year":"1998","kind":"estudio","note":"Demuestra que el movimiento de traducción fue una política de Estado sostenida y no un accidente erudito."},{"author":"George Saliba","title":"Islamic Science and the Making of the European Renaissance","year":"2007","kind":"estudio","note":"Refuta la tesis del declive por causas religiosas y documenta la continuidad científica."},{"author":"Hugh Kennedy","title":"The Great Arab Conquests","year":"2007","kind":"estudio","note":"Síntesis narrativa y crítica de la expansión, atenta a los problemas de fuentes."}]},{"type":"images","items":[{"src":"/img/islam/portada.jpg","alt":"Bosque de columnas y arcos de dovelas rojas y blancas en el interior de la mezquita de Córdoba","width":1200,"height":743,"role":"portada","caption":"Los arcos bicolores de la mezquita de Córdoba, iniciada en 786.","author":"James (Jim) Gordon","title":"Mosque of Cordoba","year":"2007","source":"Wikimedia Commons","license":"CC BY 2.0","url":"https://commons.wikimedia.org/wiki/File:Mosque_of_Cordoba.jpg"},{"src":"/img/islam/kaaba.jpg","alt":"Edificio cúbico cubierto con un paño negro bordado en oro, rodeado por una multitud que gira a su alrededor","width":1200,"height":800,"role":"figura","section":0,"caption":"La Kaaba de La Meca. Era ya santuario y centro de peregrinación en la Arabia preislámica: el islam reorienta un culto existente, no llega a un vacío.","author":"معتز توفيق اغبارية","title":"Kaaba, Makkah","year":"2016","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Kaaba%2C_Makkah.jpg"},{"src":"/img/islam/coran-azul.jpg","alt":"Página de pergamino teñido de azul intenso con líneas de escritura árabe cúfica en oro","width":1200,"height":900,"role":"figura","section":1,"caption":"Folio del Corán azul, atribuido a Kairuán o a al-Ándalus, siglos IX-X. El pergamino teñido y la tinta de oro lo convierten en un objeto de Estado.","author":"Unknown artist Unknown artist","title":"Blue Qur''an (Raqqada, Rutbi 196)","year":"950","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Der_blaue_Koran%2CKairouan.JPG"},{"src":"/img/islam/astrolabio.jpg","alt":"Disco de latón con anillos graduados, una red calada con puntas que señalan estrellas y una alidada giratoria","width":1200,"height":1600,"role":"figura","section":4,"caption":"Astrolabio planisférico persa fechado en 984. Servía para la hora, la latitud y la dirección de la oración: instrumento científico y religioso a la vez.","author":"Ciphers","title":"MIA - Planispheric Astrolabe, Iran, 984 AD","year":"2011","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:MIA_-_Planispheric_Astrolabe%2C_Iran%2C_984_AD.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'islam'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: japon
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Japón: de Heian a Meiji', '[{"type":"section","title":"Heian: una corte y un Estado que se deshace","text":"El Estado japonés del siglo VIII se construyó copiando el modelo chino Tang: códigos legales llamados ritsuryō, una burocracia de rangos, un catastro que asignaba tierra a los campesinos y un budismo patrocinado por la corte. La copia fue deliberada y selectiva. Dos elementos centrales del modelo chino no se importaron: los exámenes como vía de acceso al cargo, que en Japón quedaron subordinados al linaje, y el mandato del Cielo, que habría permitido derribar a la dinastía. El emperador japonés no gobierna por virtud sino por descendencia divina, y por eso ninguna dinastía lo ha sustituido.\n\nEl traslado de la capital a Heian en 794 abrió cuatro siglos de dominio aristocrático. En la práctica, el Estado ritsuryō se desmontó desde dentro: las tierras públicas se convirtieron en shōen, dominios privados exentos de impuestos vinculados a templos y familias nobles, y el poder efectivo pasó a la familia Fujiwara, que gobernó mediante regencias y casando a sus hijas con emperadores sucesivos. El emperador siguió siendo la fuente de legitimidad mientras otros ejercían el poder: la fórmula se repetiría durante mil años con actores distintos.\n\nLa cultura de esa corte es uno de los momentos más singulares de la historia literaria. Las mujeres de la aristocracia, excluidas de la escritura china que usaban los hombres para los asuntos serios, escribieron en la silábica kana y produjeron la obra mayor del período: el Genji monogatari de Murasaki Shikibu, una novela de más de mil páginas sobre la psicología, el deseo y el paso del tiempo, y el Libro de la almohada de Sei Shōnagon.\n\nMientras la corte refinaba su estética, en las provincias crecía otra cosa. Los propietarios de shōen necesitaban hombres armados para proteger sus tierras y cobrar sus rentas, y de ahí salieron los grupos guerreros que las fuentes llaman bushi. No eran una casta cerrada ni un producto de la corte, sino una élite provincial armada que fue acumulando poder militar mientras la capital dejaba de tener ejército propio.\n\nEl desenlace llegó a finales del siglo XII con la guerra Genpei entre los clanes Taira y Minamoto, narrada en el Heike monogatari con un tono de melancolía budista sobre la caída de los poderosos. La victoria de Minamoto no Yoritomo en 1185 y su nombramiento como shōgun en 1192 crearon un poder militar con sede en Kamakura, lejos de Kioto, que gobernaba en nombre de un emperador que conservaba el trono. Ese doble sistema es la clave institucional de la historia japonesa.","textEso":null,"textBachillerato":null,"callout":"Japón importó de China la escritura, el budismo y el modelo de Estado, y dejó fuera precisamente las dos piezas que habrían permitido cambiar de dinastía: los exámenes y el mandato del Cielo."},{"type":"section","title":"Seis siglos de poder guerrero","text":"El shogunato de Kamakura gobernó mediante vasallos, recompensas en tierra y un derecho propio, el código Jōei de 1232, que aplicaba criterios prácticos en vez de los códigos cortesanos. Su prueba mayor fueron las dos invasiones mongolas de 1274 y 1281, repelidas con enormes fortificaciones costeras y con la ayuda de dos tifones que la tradición posterior llamó vientos divinos. La victoria arruinó al régimen: no hubo tierras conquistadas con las que pagar a los vasallos movilizados.\n\nEl shogunato Ashikaga, desde 1336 y con sede en el barrio de Muromachi de Kioto, fue mucho más débil pero culturalmente decisivo. En su época se formaron el teatro nō, la ceremonia del té, el jardín seco, la pintura a tinta y el budismo zen como estética de élite, en gran medida por contacto con la China Ming. También fue el período en que el poder real se desplazó a los gobernadores provinciales.\n\nLa guerra Onin, entre 1467 y 1477, destruyó Kioto y abrió el sengoku, el siglo de los Estados en guerra. El país se fragmentó en dominios gobernados por daimyō que legislaban, recaudaban, construían castillos y competían militarmente. Fue una época de destrucción y a la vez de crecimiento: los daimyō promovían roturaciones, minas, mercados y rutas para financiar sus ejércitos, y aparecieron ciudades libres de comerciantes como Sakai.\n\nLa llegada de portugueses en 1543 introdujo el arcabuz, que los talleres japoneses copiaron y produjeron en masa con extraordinaria rapidez, y en 1549 la misión jesuita de Francisco Javier. El cristianismo llegó a tener varios cientos de miles de fieles y el apoyo de algunos daimyō del sur, interesados también en el comercio. Su prohibición posterior no fue un rechazo cultural abstracto: los unificadores vieron una lealtad exterior incompatible con el orden que estaban construyendo.\n\nLa unificación la ejecutaron tres hombres en medio siglo. Oda Nobunaga rompió el poder de los monasterios armados y usó la infantería con armas de fuego a gran escala; Toyotomi Hideyoshi, de origen campesino, completó la conquista, separó por decreto a guerreros y campesinos mediante la requisa de armas y ordenó un catastro nacional; Tokugawa Ieyasu venció en Sekigahara en 1600 y recibió el título de shōgun en 1603. Las dos invasiones de Corea lanzadas por Hideyoshi en la década de 1590 fueron un desastre y la última aventura exterior japonesa en dos siglos y medio.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"El orden Tokugawa","text":"El régimen Tokugawa organizó el país en unos doscientos sesenta dominios o han, con daimyō que gobernaban internamente y un shogunato que controlaba las ciudades clave, la moneda, la política exterior y las relaciones entre dominios. La pieza de control más eficaz fue el sankin-kōtai: la obligación de que cada daimyō residiera en años alternos en Edo y dejara allí a su familia. El sistema funcionaba como rehén institucionalizado y, de paso, creó una red de carreteras, posadas y consumo urbano que integró la economía nacional.\n\nLa sociedad se ordenó teóricamente en cuatro estamentos, guerreros, campesinos, artesanos y comerciantes, con el neoconfucianismo como marco justificativo. La práctica se apartó pronto del esquema. Los samuráis, sin guerras que librar, se convirtieron en funcionarios asalariados y con frecuencia endeudados; los comerciantes de Osaka, situados en el escalón más bajo, acumularon una riqueza que financiaba a los dominios; y en las ciudades floreció una cultura urbana propia, con teatro kabuki, novela popular y estampa ukiyo-e.\n\nEdo llegó a superar el millón de habitantes hacia 1720 y era probablemente la ciudad más grande del mundo. La alfabetización creció con una red de escuelas de templo, y a comienzos del siglo XIX una proporción alta de varones y una parte considerable de mujeres sabían leer, con una industria editorial de préstamo de libros que no tenía equivalente fuera de Europa occidental. La agricultura se intensificó con abonos comerciales y cultivos de mercado, y la población se estabilizó en torno a los treinta millones mediante mecanismos de control demográfico dentro de la familia.\n\nLa política de sakoku, el país cerrado, se estableció entre 1633 y 1639 tras la rebelión de Shimabara: prohibición del cristianismo, expulsión de los portugueses, prohibición a los japoneses de salir del país bajo pena de muerte. Ronald Toby demostró que la etiqueta induce a error: el archipiélago mantuvo cuatro puertas abiertas y reguladas, con los neerlandeses en Deshima, los chinos en Nagasaki, Corea a través de Tsushima y los ainu y Ryukyu por otros dominios. No fue aislamiento, sino monopolio estatal de las relaciones exteriores.\n\nPor la rendija de Deshima entraron los estudios holandeses o rangaku. Médicos japoneses tradujeron manuales de anatomía europeos y comprobaron su exactitud con disecciones; se estudió astronomía, cartografía, botánica y balística. Cuando llegaron los barcos estadounidenses, había en Japón un grupo pequeño pero real de personas que sabían lo que estaba ocurriendo en el mundo, y esa preparación previa forma parte de la explicación de lo que vino después.","textEso":null,"textBachillerato":null,"callout":"La palabra sakoku no aparece hasta 1801, en la traducción de un texto europeo. El régimen no se veía a sí mismo como cerrado, sino como titular exclusivo de unas relaciones exteriores estrictamente reguladas."},{"type":"section","title":"La crisis del bakumatsu y la Restauración","text":"La escuadra del comodoro Perry llegó en 1853 con buques de vapor y la exigencia de abrir puertos. El shogunato, sin capacidad militar para negarse, firmó el Tratado de Kanagawa en 1854 y después acuerdos comerciales que incluían aranceles fijados desde fuera y extraterritorialidad para los extranjeros, es decir, el mismo esquema impuesto a China. La diferencia estuvo en la reacción interna.\n\nLa crisis desató quince años de conflicto conocidos como bakumatsu. Contra la humillación se formó un movimiento con la consigna de venerar al emperador y expulsar a los bárbaros, alimentado por la escuela de estudios nacionales kokugaku, que llevaba décadas reivindicando una tradición japonesa anterior a la influencia china. Los dominios de Satsuma y Chōshū, en el suroeste, tras comprobar en combate directo la superioridad naval occidental, cambiaron de estrategia: dejaron de querer expulsar a los extranjeros y decidieron adquirir su tecnología para poder resistirlos.\n\nEn 1868, una coalición de esos dominios derribó al shogunato en una guerra civil breve y proclamó la restauración del gobierno directo del emperador Meiji, un adolescente. La palabra restauración es exacta en su forma y engañosa en su fondo: se presentó como retorno a un orden antiguo y fue una revolución dirigida desde arriba por samuráis de rango medio que desmontaron su propia clase.\n\nEl programa se anunció en la Carta del Juramento de los Cinco Artículos y se ejecutó con una velocidad asombrosa. En 1871 los dominios fueron abolidos y sustituidos por prefecturas; los estipendios de los samuráis se convirtieron en bonos y después se liquidaron; se estableció el servicio militar obligatorio, que acabó con el monopolio guerrero; se implantó un impuesto sobre la tierra pagadero en dinero, la educación primaria universal en 1872 y un sistema bancario y postal. La rebelión de Satsuma de 1877, aplastada por un ejército de reclutas campesinos, cerró la resistencia samurái.\n\nLa consigna era enriquecer el país y fortalecer el ejército. El Estado creó industrias piloto y después las vendió a grupos privados que se convertirían en los zaibatsu; envió misiones al extranjero, como la misión Iwakura, para estudiar sistemas educativos, jurídicos y militares; contrató expertos extranjeros con la instrucción explícita de formar sustitutos japoneses. La Constitución de 1889, inspirada en el modelo prusiano, estableció una dieta electa con poderes limitados y un emperador sagrado e inviolable, y el Rescripto sobre la Educación de 1890 formuló una ideología de lealtad que se enseñó en todas las escuelas.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"Qué explica el caso japonés","text":"Los resultados llegaron pronto y fueron ambivalentes. Japón derrotó a China en 1895 y se anexionó Taiwán, venció a Rusia en 1905 en la primera derrota de una potencia europea por un Estado asiático en la era moderna, anexionó Corea en 1910 y consiguió el fin de los tratados desiguales en 1911. Se convirtió en modelo para nacionalistas de toda Asia y, a la vez, en potencia colonial con las mismas prácticas que había sufrido.\n\nLa pregunta de por qué Japón lo consiguió y otros no admite varias respuestas complementarias. Una es institucional: el país tenía ya un Estado centralizado con capacidad fiscal, una red de comunicaciones, una élite letrada y una experiencia de gobierno en dominios que se reconvirtió en administración nacional. Otra es económica: la agricultura comercial, la alfabetización y los mercados internos de la época Tokugawa proporcionaron una base que no había que crear desde cero. Thomas Smith documentó esa continuidad frente a la idea de que Meiji partió de la nada.\n\nUna tercera es geopolítica y de calendario: Japón se abrió cuando las potencias estaban ocupadas en China y en otros escenarios, carecía de recursos que justificaran una conquista costosa y dispuso de dos décadas de margen. Y una cuarta es de decisión política: la élite que tomó el poder en 1868 optó por transformar el país en lugar de defender su posición dentro del viejo orden, lo que exigía disolver el estamento del que ella misma procedía.\n\nLa historiografía discute cómo calificar 1868. La tradición marxista japonesa lo trató como una revolución burguesa incompleta que dejó intactos elementos feudales; otros lo han descrito como una revolución desde arriba comparable a la unificación alemana; y hay quien subraya la continuidad con las tendencias tardías del período Tokugawa y niega el corte. La discusión importa porque de ella depende cómo se explica el militarismo posterior.\n\nTambién se discute el propio vocabulario. Llamar feudal a Japón fue durante mucho tiempo una comparación con Europa que Marc Bloch admitió y que después se ha matizado: la relación de vasallaje, el beneficio en tierra y la fragmentación del poder existieron, pero el papel del emperador, la ausencia de Iglesia autónoma y la fuerza de la burocracia guerrera hacen del caso japonés algo distinto. Y el bushidō como código coherente de honor guerrero es en gran medida una construcción de época Tokugawa y sobre todo Meiji, cuando ya no había guerra que librar.","textEso":null,"textBachillerato":null,"callout":"El bushidō que se cita como esencia inmemorial del samurái se codificó cuando los samuráis llevaban siglos sin combatir, y se popularizó fuera de Japón con un libro escrito en inglés en 1900 para un público occidental."},{"type":"concepts","items":[{"term":"Ritsuryō","definition":"Sistema de códigos legales y administrativos del siglo VIII copiado del modelo Tang. Se desmontó desde dentro con la privatización de las tierras."},{"term":"Shōen","definition":"Dominio privado exento de impuestos vinculado a templos o familias nobles. Su expansión vació de recursos al Estado central de Heian."},{"term":"Bushi","definition":"Guerreros de origen provincial surgidos de la necesidad de proteger y cobrar los shōen. No fueron una creación de la corte."},{"term":"Shogunato","definition":"Gobierno militar que ejerce el poder efectivo en nombre de un emperador que conserva la legitimidad. Fórmula institucional característica de Japón."},{"term":"Sengoku","definition":"Siglo de los Estados en guerra, entre 1467 y 1600: fragmentación en dominios, castillos y competencia militar, con crecimiento económico simultáneo."},{"term":"Daimyō","definition":"Señor de un dominio con capacidad de legislar, recaudar y mantener ejército propio, bajo la autoridad general del shogunato."},{"term":"Separación de estamentos","definition":"Medida de Hideyoshi que requisó las armas de los campesinos y fijó la frontera entre guerreros y productores, base del orden social Tokugawa."},{"term":"Sankin-kōtai","definition":"Obligación de residencia alterna de los daimyō en Edo dejando allí a su familia. Control político que además integró la economía nacional."},{"term":"Sakoku","definition":"Política de restricción de contactos exteriores desde 1639. Más que aislamiento fue un monopolio estatal de unas relaciones exteriores reguladas."},{"term":"Rangaku","definition":"Estudios holandeses: medicina, astronomía, cartografía y balística europeas aprendidas por la rendija comercial de Deshima."},{"term":"Kokugaku","definition":"Escuela de estudios nacionales que reivindicaba una tradición japonesa anterior a la influencia china. Base intelectual del movimiento imperial de 1868."},{"term":"Bakumatsu","definition":"Últimos quince años del shogunato, entre 1853 y 1868: tratados desiguales, conflicto interno y reorientación estratégica de los dominios del suroeste."},{"term":"Fukoku kyōhei","definition":"Consigna Meiji de enriquecer el país y fortalecer el ejército. Resume el programa de transformación dirigida desde el Estado."},{"term":"Zaibatsu","definition":"Grandes grupos empresariales familiares formados al comprar al Estado las industrias piloto creadas en los primeros años Meiji."}]},{"type":"debates","items":[{"question":"¿Tiene sentido llamar feudal al Japón medieval?","positions":[{"school":"Comparación válida (Bloch; Hall)","argument":"Existieron vasallaje personal, concesión de tierra a cambio de servicio militar y fragmentación de la autoridad pública, que son los rasgos definitorios del modelo europeo."},{"school":"Categoría engañosa (Friday y otros)","argument":"El emperador nunca fue desplazado, no hubo una Iglesia con poder autónomo y la administración guerrera fue mucho más burocrática de lo que sugiere la analogía. El término importa un marco europeo que oculta lo específico."}],"state":"Se usa hoy con cautela y entrecomillado. La discusión ha resultado útil sobre todo para revisar el propio concepto de feudalismo en Europa."},{"question":"¿Estuvo Japón realmente aislado entre 1639 y 1853?","positions":[{"school":"Aislamiento (lectura tradicional)","argument":"La prohibición del cristianismo, la expulsión de los europeos y la pena de muerte para quien saliera del país cortaron el contacto exterior durante dos siglos y explican el atraso técnico frente a Occidente."},{"school":"Cuatro puertas reguladas (Toby, 1984)","argument":"Neerlandeses en Deshima, chinos en Nagasaki, Corea vía Tsushima y los ainu y Ryukyu por otros dominios mantuvieron comercio, información y diplomacia. Fue monopolio estatal de las relaciones exteriores, no ausencia de ellas."}],"state":"La revisión de Toby es hoy la posición estándar. La palabra sakoku ni siquiera se usaba en la época: aparece en 1801 traduciendo un texto europeo."},{"question":"¿Fue 1868 una restauración, una revolución o una continuidad?","positions":[{"school":"Revolución desde arriba","argument":"Una élite de samuráis de rango medio abolió los dominios, liquidó los estipendios de su propia clase, implantó el servicio militar obligatorio y reorganizó el Estado en menos de una década."},{"school":"Revolución burguesa incompleta (historiografía marxista japonesa)","argument":"El cambio no eliminó las estructuras agrarias ni el poder de las viejas élites, y la Constitución de 1889 consagró un autoritarismo que explica la deriva militarista posterior."},{"school":"Continuidad Tokugawa (Smith; Totman)","argument":"La alfabetización, la agricultura comercial, los mercados internos y la capacidad administrativa ya existían. Meiji no partió de cero: aceleró y reorientó tendencias en marcha."}],"state":"Predomina una lectura que combina la continuidad de las bases materiales con el carácter deliberadamente revolucionario de las decisiones políticas de 1868 a 1877."}]},{"type":"timeline","items":[{"date":"794","event":"La corte se traslada a Heian, la actual Kioto. Comienza el período clásico aristocrático."},{"date":"siglos X–XI","event":"Dominio de la familia Fujiwara sobre la corte mediante regencias y alianzas matrimoniales."},{"date":"c. 1008","event":"Murasaki Shikibu escribe el Genji monogatari, una de las primeras novelas psicológicas del mundo."},{"date":"1185–1192","event":"Victoria de los Minamoto y creación del shogunato de Kamakura. El poder efectivo pasa a los guerreros."},{"date":"1274 y 1281","event":"Dos invasiones mongolas fracasan, en parte por tifones que la tradición llamará vientos divinos."},{"date":"1467–1477","event":"Guerra Onin. Kioto es destruida y comienza el siglo de los Estados en guerra."},{"date":"1543 y 1549","event":"Llegada de armas de fuego portuguesas y de la misión jesuita de Francisco Javier."},{"date":"1582–1600","event":"Unificación por Oda Nobunaga, Toyotomi Hideyoshi y Tokugawa Ieyasu, que vence en Sekigahara."},{"date":"1603–1639","event":"Shogunato Tokugawa, prohibición del cristianismo y edictos que restringen los contactos exteriores."},{"date":"1720–1850","event":"Estudios holandeses, expansión editorial y alfabetización amplia bajo una paz de dos siglos y medio."},{"date":"1853–1854","event":"Llegada de la escuadra de Perry y Tratado de Kanagawa. Comienza el bakumatsu."},{"date":"1868","event":"Restauración Meiji: caída del shogunato y Carta del Juramento de los Cinco Artículos."},{"date":"1889–1905","event":"Constitución Meiji, victoria sobre China en 1895 y sobre Rusia en 1905."}]},{"type":"sources","items":[{"author":"Murasaki Shikibu","title":"La historia de Genji","year":"c. 1008","kind":"primaria","note":"Novela de la corte de Heian escrita en kana por una dama al servicio de la emperatriz. Retrato interior de una élite."},{"author":"Sei Shōnagon","title":"El libro de la almohada","year":"c. 1002","kind":"primaria","note":"Anotaciones, listas y juicios de una dama de corte. Fuente insustituible sobre sensibilidad y vida cotidiana aristocrática."},{"author":"Anónimo","title":"Heike monogatari","year":"siglo XIII","kind":"primaria","note":"Épica recitada sobre la guerra Genpei, con la caída de los poderosos como tema budista central."},{"author":"Shogunato de Kamakura","title":"Código Jōei","year":"1232","kind":"primaria","note":"Derecho propio de los guerreros, con criterios prácticos frente a los códigos cortesanos."},{"author":"Toyotomi Hideyoshi","title":"Edicto de requisa de espadas","year":"1588","kind":"primaria","note":"Separación jurídica de guerreros y campesinos, base del orden social de los dos siglos siguientes."},{"author":"Shogunato Tokugawa","title":"Buke shohatto","year":"1615","kind":"primaria","note":"Leyes para las casas guerreras: control de castillos, matrimonios y conducta de los daimyō."},{"author":"Sugita Genpaku","title":"Kaitai shinsho y memorias del rangaku","year":"1774 y 1815","kind":"primaria","note":"Traducción de un manual de anatomía holandés y relato del proceso. Documento del contacto científico durante el sakoku."},{"author":"Yamamoto Tsunetomo","title":"Hagakure","year":"c. 1716","kind":"primaria","note":"Reflexiones de un samurái sin guerra sobre la muerte y el servicio. Fuente sobre la codificación tardía del ideal guerrero."},{"author":"Japón y Estados Unidos","title":"Tratado de Kanagawa","year":"1854","kind":"primaria","note":"Primer acuerdo impuesto tras la llegada de Perry. Inicio de la serie de tratados desiguales."},{"author":"Gobierno Meiji","title":"Carta del Juramento de los Cinco Artículos","year":"1868","kind":"primaria","note":"Programa inicial del nuevo régimen: asambleas deliberantes y búsqueda del conocimiento en todo el mundo."},{"author":"Fukuzawa Yukichi","title":"Autobiografía y Estímulo al aprendizaje","year":"1872–1899","kind":"primaria","note":"Voz del principal divulgador del pensamiento occidental en Japón y fundador de una universidad."},{"author":"Imperio del Japón","title":"Constitución Meiji","year":"1889","kind":"primaria","note":"Modelo prusiano: dieta electa con poderes limitados y emperador sagrado e inviolable como fuente de soberanía."},{"author":"Gobierno Meiji","title":"Rescripto Imperial sobre la Educación","year":"1890","kind":"primaria","note":"Texto de lealtad y piedad filial leído en todas las escuelas. Núcleo de la ideología oficial hasta 1945."},{"author":"Nitobe Inazō","title":"Bushido, el alma de Japón","year":"1900","kind":"primaria","note":"Escrito en inglés para lectores occidentales. Fuente de la imagen internacional del samurái y no descripción histórica."},{"author":"John Whitney Hall","title":"El imperio japonés","year":"1968","kind":"estudio","note":"Síntesis clásica que estableció el marco de la historiografía occidental sobre Japón."},{"author":"Thomas C. Smith","title":"The Agrarian Origins of Modern Japan","year":"1959","kind":"estudio","note":"Documenta la agricultura comercial y la base económica Tokugawa sobre la que se construyó Meiji."},{"author":"Ronald Toby","title":"State and Diplomacy in Early Modern Japan","year":"1984","kind":"estudio","note":"Desmonta la idea del aislamiento total y describe las cuatro vías reguladas de contacto exterior."},{"author":"Conrad Totman","title":"A History of Japan","year":"2000","kind":"estudio","note":"Historia general con atención al medio ambiente, los recursos y la demografía."},{"author":"Eiko Ikegami","title":"The Taming of the Samurai","year":"1995","kind":"estudio","note":"Sociología histórica de la transformación del guerrero en funcionario y de la construcción del honor."},{"author":"Marius Jansen","title":"The Making of Modern Japan","year":"2000","kind":"estudio","note":"Síntesis de referencia sobre el período que va de los Tokugawa al siglo XX."},{"author":"Andrew Gordon","title":"A Modern History of Japan","year":"2003","kind":"estudio","note":"Manual actual desde el bakumatsu, con atención a trabajo, género y vida cotidiana."},{"author":"Carol Gluck","title":"Japans Modern Myths","year":"1985","kind":"estudio","note":"Analiza la construcción deliberada de la ideología nacional en el último período Meiji."}]},{"type":"images","items":[{"src":"/img/japon/portada.jpg","alt":"Estampa japonesa con una ola enorme de cresta espumosa a punto de romper sobre tres barcas, y el Fuji al fondo","width":1200,"height":828,"role":"portada","caption":"La gran ola de Kanagawa, de Katsushika Hokusai, hacia 1831.","author":"After Katsushika Hokusai","title":"The Great Wave off Kanagawa","year":"1930","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:The_Great_Wave_off_Kanagawa.jpg"},{"src":"/img/japon/genji.jpg","alt":"Pintura horizontal de un interior palaciego visto desde arriba sin techo, con figuras de rostro esquemático entre biombos","width":1200,"height":530,"role":"figura","section":0,"caption":"Rollo ilustrado del Genji monogatari, siglo XII. La novela la escribió Murasaki Shikibu, dama de la corte de Heian, hacia el año 1000.","author":"Imperial court in Kyoto. The handscroll had been said to be painted by Fujiwara, Takayoshi, though it is now presumed to","title":"Genji emaki Yadorigi","year":"sin fecha","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Genji_emaki_Yadorigi.JPG"},{"src":"/img/japon/armadura.jpg","alt":"Armadura japonesa completa expuesta sobre un soporte, con casco de cuernos, máscara facial y placas laceadas atadas con cordón","width":1200,"height":1600,"role":"figura","section":1,"caption":"Armadura de samurái del período Edo. Las placas van cosidas con cordón de seda: protegen y a la vez muestran el color del clan.","author":"Ykmyks","title":"Samurai Armor, Guimet Museum (Paris)","year":"2011","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Samurai_Armor%2C_Guimet_Museum_(Paris).jpg"},{"src":"/img/japon/meiji.jpg","alt":"Retrato fotográfico de un hombre joven con uniforme militar occidental, charreteras y espada","width":1200,"height":1642,"role":"figura","section":4,"caption":"El emperador Meiji en uniforme europeo. La Restauración se presentó como vuelta al poder imperial y funcionó como la modernización más rápida del siglo XIX.","author":"Artist: Eduardo Chiossone (1833–98); Photographer: Maruki Riyō (also misspelt as Maruki Toshiaki) [ 3 ]","title":"Meiji tenno1","year":"1888","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Meiji_tenno1.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'japon'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: mesopotamia
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Mesopotamia y el nacimiento del Estado', '[{"type":"section","title":"Un medio difícil: agua, sal y trabajo","text":"La llanura aluvial del sur de Irak carece de piedra, de madera de construcción y de metales. Tiene, en cambio, suelos fértiles y dos ríos. Pero su régimen es problemático: el Tigris y el Éufrates crecen en primavera, cuando el cereal ya está en el campo, no antes de la siembra como el Nilo, y lo hacen de manera brusca e impredecible. Cultivar allí exige control activo del agua: canales de derivación, diques, compuertas y drenaje.\n\nEse esfuerzo tuvo un coste ecológico documentado. La irrigación con evaporación intensa deposita sales en el suelo. Los archivos administrativos permiten seguir el proceso: entre 2400 y 1700 a. C., la proporción de cebada —más tolerante a la sal— frente al trigo pasó de un reparto equilibrado a un predominio casi absoluto, mientras los rendimientos registrados descendían. Thorkild Jacobsen y Robert Adams describieron esta salinización progresiva en un influyente artículo de 1958 y la vincularon al desplazamiento del centro político hacia el norte.\n\nLa escasez de materias primas explica otra característica estructural: Mesopotamia dependió siempre del intercambio de larga distancia. La madera venía del Líbano y de los Zagros, el cobre de Omán y Anatolia, el lapislázuli de Afganistán, la cornalina del valle del Indo. Esa dependencia hizo del comercio y del control de rutas un asunto de Estado, y explica buena parte de su política exterior y militar.","textEso":"Mesopotamia significa «entre ríos»: la llanura del Tigris y el Éufrates, en el actual Irak. Llueve muy poco, así que sin regadío no hay cosecha. Pero los ríos se desbordan de forma irregular, no como el Nilo, y el agua de riego deja sal en la tierra si no se drena bien. Cultivar allí exigía canales, diques y mantenimiento constante, y eso solo se consigue organizando el trabajo de mucha gente.","textBachillerato":"La llanura aluvial del Tigris y el Éufrates es un medio hostil disfrazado de fértil. Las precipitaciones no bastan para el cereal, así que toda la agricultura depende del regadío; pero las crecidas llegan en primavera, tarde para la siembra, y son violentas e imprevisibles, muy distintas de la crecida regular del Nilo.\n\nEl regadío trae además un problema propio: el agua evaporada deja sales en el suelo y la tierra pierde productividad si no se drena y se deja en barbecho. Los archivos documentan cómo el trigo fue sustituido por cebada, más tolerante a la sal, en zonas donde el rendimiento caía. Todo esto obliga a coordinar trabajo colectivo de forma permanente, y esa coordinación es la raíz del Estado mesopotámico.","callout":"La cebada no solo era alimento: funcionaba como unidad de cuenta y medio de pago de salarios. Los archivos expresan sueldos en litros de cebada y en pesos de plata mucho antes de que existiera la moneda acuñada."},{"type":"section","title":"La revolución urbana de Uruk","text":"Hacia 3500 a. C., Uruk alcanzó una extensión y una población sin precedentes —las estimaciones oscilan entre 20.000 y 50.000 habitantes— y desarrolló una arquitectura monumental de templos sobre terrazas. Gordon Childe llamó a este proceso «revolución urbana» y lo caracterizó por diez rasgos: concentración demográfica, especialización artesanal, tributo, monumentalidad, clases sociales, escritura, ciencia predictiva, arte representativo, comercio exterior y un Estado con territorio.\n\nLa contabilidad precedió a la escritura. Denise Schmandt-Besserat mostró que fichas de arcilla con formas convencionales (tokens) se usaban desde el VIII milenio para registrar cantidades de bienes. Esas fichas se guardaban en bullae —esferas de arcilla selladas— y, para saber qué contenían sin romperlas, se imprimían las formas en la superficie. El paso siguiente fue prescindir del contenido y conservar solo las marcas: la tablilla.\n\nLas primeras tablillas de Uruk IV, hacia 3300 a. C., son documentos económicos: cantidades de grano, cabezas de ganado, raciones, listas de profesiones. No hay poesía ni narración. La escritura nace como tecnología de gestión, no de literatura; los textos literarios llegan siglos después.\n\nEl modelo político dominante durante el Dinástico Arcaico fue la ciudad-Estado: un núcleo urbano con su territorio agrícola, su dios tutelar, su templo y su gobernante —ensi o lugal—. Estas ciudades competían por agua y tierra de forma endémica. La disputa entre Lagash y Umma por la frontera de Guedena está documentada durante más de un siglo y produjo, en la Estela de los Buitres, uno de los primeros relatos de guerra conservados.","textEso":"Hacia 3500 a. C., Uruk llegó a tener decenas de miles de habitantes: la primera ciudad grande del mundo. Con tanta gente junta aparecen cosas nuevas: oficios especializados, templos enormes, almacenes y personas que no producen comida sino que administran la que producen otros. La ciudad no nace del comercio ni del azar, sino de la necesidad de gestionar el agua y el grano.","textBachillerato":"Hacia 3500 a. C. Uruk alcanza una escala sin precedentes: decenas de miles de habitantes, murallas, templos monumentales y un territorio de aldeas dependientes. Se la suele llamar revolución urbana, aunque no fue un episodio breve sino un proceso de siglos.\n\nLo decisivo no es el tamaño sino la especialización. Aparecen alfareros a tiempo completo, tejedores, metalúrgicos y, sobre todo, administradores: gente que no produce alimentos y que vive del excedente que otros generan. Para que ese sistema funcione hay que registrar quién entrega qué y quién recibe qué, y ahí es donde la contabilidad se vuelve inevitable. La ciudad y la burocracia nacen juntas, no una después de la otra.","callout":null},{"type":"section","title":"Escritura cuneiforme y cultura del archivo","text":"El cuneiforme se escribía imprimiendo un cálamo de caña de sección triangular sobre arcilla fresca. Es un sistema mixto: signos logográficos que valen por una palabra, signos silábicos que valen por un sonido y determinativos que clasifican semánticamente. Se usó durante más de tres milenios y sirvió para lenguas muy distintas —sumerio, acadio, elamita, hitita, urartio—, del mismo modo que el alfabeto latino sirve hoy a lenguas sin parentesco.\n\nLa arcilla es un soporte afortunado para el historiador: cuando un edificio ardía, las tablillas se cocían y se conservaban mejor. Por eso disponemos de archivos enteros. Los de la Tercera Dinastía de Ur suman más de cien mil documentos administrativos y permiten reconstruir la economía de un Estado antiguo con un detalle inalcanzable en otras civilizaciones: rendimientos por parcela, raciones por trabajador, censos de ganado, cuentas de talleres textiles con centenares de operarias.\n\nLa formación de escribas se hacía en la edubba, la «casa de las tablillas». Sus ejercicios —listas léxicas, copias de proverbios, problemas matemáticos, textos de disputa entre estudiantes— revelan un currículo estable. Las matemáticas mesopotámicas usaban un sistema sexagesimal cuyo legado seguimos empleando: sesenta minutos, sesenta segundos, trescientos sesenta grados. La tablilla Plimpton 322 recoge ternas pitagóricas más de mil años antes de Pitágoras.\n\nEl desciframiento moderno se debe sobre todo a Henry Rawlinson, que copió con riesgo considerable la inscripción trilingüe de Behistún, mandada grabar por Darío I en un acantilado. La versión en persa antiguo, más simple, sirvió de puerta de entrada al elamita y al acadio, del mismo modo que el griego lo fue para los jeroglíficos.","textEso":"La escritura nace hacia 3300 a. C. en Uruk, y no para contar historias: para llevar cuentas. Las primeras tablillas anotan sacos de cebada y cabezas de ganado. Se escribía con una caña sobre arcilla blanda, dejando marcas en forma de cuña, de ahí el nombre de cuneiforme. Con el tiempo sirvió también para leyes, cartas y literatura, como el Poema de Gilgamesh.","textBachillerato":"La escritura cuneiforme aparece hacia 3300 a. C. como herramienta contable. Sus antecedentes son fichas de arcilla que representaban mercancías; el paso decisivo fue dibujar la ficha sobre la tablilla en lugar de guardarla. Los primeros textos son listas de raciones y entregas, no relatos.\n\nLa evolución del sistema es lo interesante: de pictogramas a signos que representan sonidos, lo que permite escribir nombres propios, verbos y, con el tiempo, cualquier idea. Eso convirtió el cuneiforme en el sistema de escritura de varias lenguas distintas durante tres milenios y permitió leyes, tratados, tratados de matemáticas y literatura como el Poema de Gilgamesh. Como la arcilla cocida sobrevive al fuego, se conservan cientos de miles de tablillas: paradójicamente, conocemos mejor la economía de Ur que la de muchas ciudades medievales.","callout":"La *Epopeya de Gilgamesh* se conoce sobre todo por la versión estándar de la biblioteca de Asurbanipal. Su relato del diluvio, con un superviviente advertido por un dios, presenta paralelos evidentes con el bíblico y desató una polémica considerable cuando George Smith lo publicó en 1872."},{"type":"section","title":"Templo, palacio y economía: el debate sobre quién manda","text":"La organización económica mesopotámica se ha interpretado de formas muy distintas. A comienzos del siglo XX, Anton Deimel propuso a partir de los archivos de Lagash el modelo de la «ciudad-templo»: el santuario poseería prácticamente toda la tierra y organizaría toda la producción, en una economía redistributiva sin propiedad privada relevante.\n\nLa revisión posterior desmontó esa imagen. Igor Diakonoff mostró que los archivos de Lagash pertenecían a un solo templo y no representaban la totalidad de la ciudad, y documentó la existencia de tierra comunal de familias extensas y de propiedad privada transferible. Hoy se acepta un modelo pluralista: coexistían el sector del templo, el del palacio y un sector privado, con proporciones variables según épocas y ciudades.\n\nEse debate se cruza con otro más amplio, el de la naturaleza de la economía antigua. Karl Polanyi sostuvo que las economías precapitalistas funcionaban por reciprocidad y redistribución, con «puertos de comercio» administrados, y no por mercados formadores de precios. Los asiriólogos que estudiaron el archivo de los mercaderes asirios de Kanesh —cartas privadas de negocios del siglo XIX a. C., con sociedades, créditos, intereses y arbitraje de precios entre Assur y Anatolia— han argumentado en sentido contrario.\n\nLa cuestión no es meramente técnica: determina si cabe hablar de «capital», «mercado» o «beneficio» en el mundo antiguo, o si esos conceptos importan categorías modernas a sociedades que funcionaban con otra lógica. La postura mayoritaria actual es intermedia y empírica: hubo mercados y precios fluctuantes, pero insertos en instituciones —templo, palacio, familia— que los modelaban de forma decisiva.","textEso":null,"textBachillerato":"Durante décadas se defendió que la economía mesopotámica estaba controlada casi por completo por el templo, que sería propietario de la tierra y organizador del trabajo. Esa lectura se apoyaba en los archivos de un puñado de templos, que son precisamente los que se excavaron primero y los que más escribían.\n\nInvestigaciones posteriores han matizado mucho el cuadro: existía propiedad privada de la tierra, préstamos entre particulares, contratos de arrendamiento y mercaderes que operaban por su cuenta aunque a veces trabajaran para el palacio. Hoy se habla de una economía mixta en la que templo, palacio y particulares coexisten, con un equilibrio que cambia según la época y la ciudad. La lección de método es útil: lo que se conserva no es una muestra neutral de lo que hubo.","callout":null},{"type":"section","title":"Derecho, justicia y el problema del Código de Hammurabi","text":"La estela de diorita de Hammurabi, hallada en Susa en 1901, contiene un prólogo, unas 282 disposiciones y un epílogo. Es el texto jurídico antiguo más conocido, aunque no el más antiguo: le preceden las reformas de Urukagina, el código de Ur-Nammu y el de Lipit-Ishtar.\n\nSus disposiciones tienen forma casuística —«si un hombre hace X, entonces Y»— y aplican penas diferenciadas según el estatus del implicado. La sociedad distingue tres categorías: awilum (hombre libre de pleno derecho), mushkenum (dependiente) y wardum (esclavo). Golpear a un awilum y golpear a un esclavo tienen consecuencias distintas; matar a la hija de un hombre puede castigarse ejecutando a la hija del culpable. La ley del talión convive con la compensación económica según quién sea la víctima.\n\nEl debate historiográfico central es qué era realmente este texto. La lectura tradicional lo entendía como un código vigente, aplicable por los tribunales. La objeción decisiva es que los miles de documentos judiciales conservados de la época prácticamente nunca lo citan, y que en ocasiones resuelven en sentido distinto al que la estela prescribe. Jean Bottéro y F. R. Kraus propusieron por ello leerlo como un monumento ideológico: la exhibición de un rey justo ante los dioses y la posteridad, quizá también como colección de precedentes ejemplares para la formación de jueces.\n\nCon todo, el texto documenta bien la estructura social: precios máximos, salarios, responsabilidad profesional del constructor y del médico, régimen del matrimonio y del divorcio, deudas y esclavitud por deudas. Y muestra una preocupación recurrente en la ideología real mesopotámica: la proclamación periódica de misharum, cancelaciones generales de deudas destinadas a impedir que el endeudamiento privara al Estado de contribuyentes y soldados.","textEso":"El Código de Hammurabi, de hacia 1750 a. C., se grabó en una estela de piedra de más de dos metros. Recoge casi trescientas sentencias con la fórmula «si alguien hace esto, entonces le ocurre esto otro». Es famoso por el «ojo por ojo», pero el castigo dependía de la clase social: no era lo mismo dañar a un hombre libre que a un esclavo. No era un código como los actuales, sino una recopilación de casos que mostraba al rey como garante de la justicia.","textBachillerato":"El Código de Hammurabi, hacia 1750 a. C., se conserva en una estela de diorita con un relieve en el que el rey recibe las insignias del dios Shamash y casi trescientas sentencias debajo. Su estructura es casuística: «si ocurre A, entonces B». Aplica la ley del talión, pero graduada por estatus, de modo que la misma lesión se castiga distinto según sea la víctima un hombre libre, un dependiente o un esclavo.\n\nEl problema es qué era realmente. No hay constancia de que ningún tribunal lo citase: los contratos y las sentencias conservados no lo mencionan. Por eso se discute si era derecho vigente, una recopilación de casos ejemplares o sobre todo un monumento de propaganda que presentaba al rey como pastor justo de su pueblo. Probablemente las tres cosas a la vez, y esa ambigüedad es lo que lo hace interesante.","callout":"El prólogo de la estela afirma que la ley existe «para que el fuerte no oprima al débil». Es la formulación más antigua conservada de la justicia como límite del poder, aunque su aplicación real fuese muy desigual."},{"type":"section","title":"De la ciudad-Estado al imperio","text":"Sargón de Acad, hacia 2334 a. C., sometió las ciudades sumerias y construyó la primera estructura política que puede llamarse imperio territorial: gobernadores designados, guarniciones, una lengua administrativa común y una hija instalada como sacerdotisa en Ur —Enheduanna, autora de himnos y primera figura literaria de la historia cuyo nombre conocemos—.\n\nLa Tercera Dinastía de Ur llevó la centralización al extremo. Su documentación permite ver un Estado que controla talleres, redistribuye raciones, mide el trabajo en jornadas-hombre y penaliza los déficits de producción. Ese aparato resultó frágil: se derrumbó en pocas décadas por la combinación de presión amorrea, crisis agrarias y rigidez fiscal.\n\nEl imperio neoasirio (siglos IX-VII a. C.) fue la construcción más duradera y también la más brutal de las documentadas. Se apoyó en un ejército permanente, en el uso sistemático del terror como instrumento de disuasión —relieves palaciales que exhiben empalamientos y desollamientos— y en la deportación masiva de poblaciones enteras, calculada en varios millones de personas a lo largo de tres siglos. La política tenía una lógica administrativa: desarraigar élites locales, romper solidaridades y reasentar mano de obra donde se necesitaba.\n\nSu caída fue rápida. La coalición de medos y babilonios tomó Assur en 614 y Nínive en 612 a. C. El imperio neobabilónico de Nabopolasar y Nabucodonosor II heredó el espacio, reconstruyó Babilonia con la puerta de Ishtar y la gran ziggurat, y deportó a las élites de Judá, episodio que la Biblia hebrea convirtió en experiencia fundacional. En 539 a. C., Ciro II de Persia entró en Babilonia; el Cilindro de Ciro presenta la conquista como restauración del culto de Marduk frente a un rey impío, en un ejercicio de propaganda dirigido a la élite sacerdotal local.\n\nMesopotamia dejó de ser un centro político independiente, pero su cultura escrita continuó siglos: hay tablillas astronómicas cuneiformes fechadas ya en época romana. La astronomía babilónica, con sus registros sistemáticos de posiciones planetarias, alimentó directamente a la griega y, a través de ella, a la moderna.","textEso":"Durante siglos Mesopotamia fue un mosaico de ciudades independientes que competían y guerreaban entre sí. Hacia 2334 a. C., Sargón de Acad las sometió y creó el primer imperio conocido, con un ejército permanente y gobernadores nombrados desde arriba. Después vinieron otros: Babilonia, Asiria, de nuevo Babilonia. El modelo quedó fijado para milenios: un rey, una capital, tributos y un ejército que los cobra.","textBachillerato":"El paisaje político mesopotámico fue durante siglos un conjunto de ciudades-Estado independientes —Uruk, Ur, Lagash, Kish— que competían por el agua, la tierra de frontera y el prestigio. La guerra entre ellas era endémica y ninguna lograba imponerse de forma duradera.\n\nHacia 2334 a. C. Sargón de Acad rompe ese equilibrio: somete a las ciudades del sur, coloca gobernadores de confianza, impone una lengua administrativa y mantiene un ejército permanente. Es el primer imperio territorial documentado. Su modelo —capital, tributo, ejército y una ideología que justifica el dominio— se repite después en Ur III, Babilonia y Asiria, y llega hasta los persas. Mesopotamia no inventa solo la ciudad y la escritura: inventa también la forma imperial de gobernar.","callout":null},{"type":"concepts","items":[{"term":"Cuneiforme","definition":"Escritura de signos en forma de cuña impresos sobre arcilla. Sistema mixto usado para varias lenguas durante tres milenios."},{"term":"Ziggurat","definition":"Templo escalonado sobre terrazas superpuestas, centro simbólico y económico de la ciudad mesopotámica."},{"term":"Ensi / lugal","definition":"Títulos del gobernante sumerio: «gobernador» del dios de la ciudad y «hombre grande» o rey."},{"term":"Ciudad-Estado","definition":"Núcleo urbano con territorio agrícola, dios tutelar y gobierno propio. Modelo político del Dinástico Arcaico."},{"term":"Awilum / mushkenum / wardum","definition":"Las tres categorías jurídicas del Código de Hammurabi: libre pleno, dependiente y esclavo."},{"term":"Misharum","definition":"Cancelación general de deudas proclamada por el rey para evitar la ruina de los contribuyentes."},{"term":"Edubba","definition":"«Casa de las tablillas»: escuela de escribas con un currículo estable de listas, copias y matemáticas."},{"term":"Bulla y tokens","definition":"Fichas de arcilla contables y su envoltura sellada. Precedente directo de la tablilla escrita."},{"term":"Sexagesimal","definition":"Sistema numérico de base 60 mesopotámico, origen de nuestros minutos, segundos y grados."},{"term":"Salinización","definition":"Acumulación de sales en suelos irrigados con fuerte evaporación. Documentada en el paso del trigo a la cebada."}]},{"type":"debates","items":[{"question":"¿Era la economía mesopotámica una economía de templo redistributiva o existían mercados?","positions":[{"school":"Ciudad-templo (Deimel, años 1920-30)","argument":"Los archivos de Lagash mostrarían que el templo poseía la tierra y organizaba la producción y el reparto. No habría propiedad privada significativa ni mercado formador de precios."},{"school":"Revisión pluralista (Diakonoff, Gelb)","argument":"Los archivos de Lagash corresponden a un solo templo, no a la ciudad entera. Existían tierra comunal de familias extensas y propiedad privada transferible junto a los sectores del templo y del palacio."},{"school":"Sustantivismo (Polanyi) frente a formalismo","argument":"Polanyi negaba mercados formadores de precios en el mundo antiguo. Los archivos de los mercaderes asirios de Kanesh, con sociedades, créditos, intereses y arbitraje entre plazas, se han esgrimido en contra."}],"state":"Domina hoy una posición intermedia: hubo precios fluctuantes, crédito y comercio privado, pero insertos en instituciones (templo, palacio, familia) que condicionaban de forma decisiva su funcionamiento. La discusión sigue viva sobre cuánto pesaba cada sector y cómo varía por época y región."},{"question":"¿Fue el Código de Hammurabi derecho aplicado o propaganda real?","positions":[{"school":"Lectura legalista tradicional","argument":"Se trataría de una codificación vigente, destinada a unificar el derecho del reino y a ser aplicada por los tribunales, como sugiere su forma articulada y su exposición pública."},{"school":"Lectura ideológica (Kraus, Bottéro)","argument":"Los miles de documentos judiciales conservados casi nunca lo citan y a veces resuelven en sentido contrario. Sería un monumento de autolegitimación —el rey justo ante Shamash— y, quizá, una colección de precedentes ejemplares para la enseñanza."}],"state":"La lectura ideológica es hoy mayoritaria, pero se reconoce que el texto refleja normas y prácticas reales. Se prefiere hablar de «colección de sentencias» antes que de «código» en sentido moderno."},{"question":"¿Por qué se desplazó el centro de poder del sur hacia el norte de Mesopotamia?","positions":[{"school":"Degradación ecológica (Jacobsen y Adams, 1958)","argument":"La salinización progresiva de los suelos irrigados del sur redujo los rendimientos, forzó la sustitución del trigo por la cebada y minó la base agraria del poder sumerio."},{"school":"Factores políticos y militares","argument":"El desplazamiento se explicaría mejor por la presión de poblaciones amorreas y arameas, por la fragilidad fiscal de Estados hipercentralizados como Ur III y por el control de rutas comerciales del norte."}],"state":"Se admite la salinización como proceso real y bien documentado, pero se rechaza como causa única. La explicación dominante es multifactorial y subraya la interacción entre estrés ecológico, rigidez institucional y presión externa."}]},{"type":"timeline","items":[{"date":"c. 5500 a. C.","event":"Cultura de Ubaid: primeros templos y agricultura irrigada en el sur."},{"date":"c. 3500–3100 a. C.","event":"Periodo Uruk: primera gran ciudad, contabilidad y escritura protocuneiforme."},{"date":"c. 2900–2350 a. C.","event":"Dinástico Arcaico: ciudades-Estado sumerias rivales (Ur, Lagash, Umma, Kish)."},{"date":"c. 2334 a. C.","event":"Sargón de Acad funda el primer imperio territorial conocido."},{"date":"c. 2112–2004 a. C.","event":"Tercera dinastía de Ur: burocracia hiperdocumentada y códigos legales."},{"date":"c. 1792–1750 a. C.","event":"Reinado de Hammurabi de Babilonia; estela de leyes."},{"date":"c. 1595 a. C.","event":"Saqueo hitita de Babilonia; después, dominio casita."},{"date":"c. 1350–1050 a. C.","event":"Imperio asirio medio; expansión desde Assur."},{"date":"883–627 a. C.","event":"Imperio neoasirio: deportaciones sistemáticas y ejército permanente."},{"date":"668–627 a. C.","event":"Asurbanipal reúne en Nínive la gran biblioteca."},{"date":"612 a. C.","event":"Caída de Nínive ante medos y babilonios."},{"date":"605–562 a. C.","event":"Nabucodonosor II: imperio neobabilónico y deportación de Judá."},{"date":"539 a. C.","event":"Ciro II de Persia toma Babilonia; fin de la independencia mesopotámica."}]},{"type":"sources","items":[{"author":"Anónimo","title":"Epopeya de Gilgamesh (versión estándar)","year":"c. s. XII a. C.","kind":"primaria","note":"Conservada sobre todo en la biblioteca de Asurbanipal. Contiene el relato del diluvio."},{"author":"Hammurabi","title":"Estela de leyes","year":"c. 1750 a. C.","kind":"primaria","note":"Prólogo, 282 disposiciones casuísticas y epílogo. Hallada en Susa en 1901."},{"author":"Enheduanna","title":"Himnos a Inanna","year":"c. 2280 a. C.","kind":"primaria","note":"Primera autoría literaria conocida por su nombre. Hija de Sargón y sacerdotisa en Ur."},{"author":"Darío I","title":"Inscripción de Behistún","year":"c. 520 a. C.","kind":"primaria","note":"Texto trilingüe cuya copia por Rawlinson permitió descifrar el cuneiforme."},{"author":"Anónimo","title":"Cilindro de Ciro","year":"539 a. C.","kind":"primaria","note":"Presenta la conquista persa como restauración del culto de Marduk. Documento de propaganda."},{"author":"Thorkild Jacobsen y Robert Adams","title":"«Salt and Silt in Ancient Mesopotamian Agriculture», Science","year":"1958","kind":"estudio","note":"Formula la tesis de la salinización como factor de declive del sur."},{"author":"Igor M. Diakonoff","title":"Structure of Society and State in Early Dynastic Sumer","year":"1959","kind":"estudio","note":"Refuta el modelo de la ciudad-templo de Deimel."},{"author":"Denise Schmandt-Besserat","title":"Before Writing","year":"1992","kind":"estudio","note":"Traza el origen contable de la escritura a partir de las fichas de arcilla."},{"author":"Jean Bottéro","title":"Mésopotamie. L''écriture, la raison et les dieux","year":"1987","kind":"estudio","note":"Reinterpreta el Código de Hammurabi y la racionalidad mesopotámica."},{"author":"Marc Van De Mieroop","title":"A History of the Ancient Near East","year":"2004 (3.ª ed. 2015)","kind":"estudio","note":"Manual de referencia actualizado sobre el conjunto del Próximo Oriente antiguo."},{"author":"Amélie Kuhrt","title":"The Ancient Near East, c. 3000–330 BC","year":"1995","kind":"estudio","note":"Síntesis crítica de amplio alcance, atenta a los problemas de fuentes."}]},{"type":"images","items":[{"src":"/img/mesopotamia/portada.jpg","alt":"Panel de mosaico con incrustaciones de concha y lapislázuli en tres registros con carros, soldados y prisioneros","width":1200,"height":525,"role":"portada","caption":"Cara de la guerra del Estandarte de Ur, hacia 2600 a. C.","author":"Unknown author Unknown author","title":"Standard of Ur - War","year":"2600","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Standard_of_Ur_-_War.jpg"},{"src":"/img/mesopotamia/vaso-uruk.jpg","alt":"Vaso alto de alabastro con relieves en franjas superpuestas: plantas, animales, hombres desnudos con ofrendas y una figura ante un templo","width":1200,"height":2818,"role":"figura","section":1,"caption":"El vaso de Warka, de Uruk, hacia 3200 a. C. Las franjas ordenan el mundo de abajo arriba: agua, plantas, ganado, hombres y templo.","author":"Osama Shukir Muhammed Amin FRCP(Glasg)","title":"Warka vase (background retouched)","year":"2019","source":"Wikimedia Commons","license":"CC BY-SA 4.0","url":"https://commons.wikimedia.org/wiki/File:Warka_vase_(background_retouched).jpg"},{"src":"/img/mesopotamia/tablilla.jpg","alt":"Tablilla de arcilla cubierta de signos cuneiformes en casillas, con la impresión de un sello cilíndrico","width":1200,"height":1093,"role":"figura","section":2,"caption":"Cuenta administrativa de reparto de cebada, hacia 3100-2900 a. C. La escritura nace de la contabilidad, no de la literatura.","author":"Autor desconocido","title":"Cuneiform tablet: administrative account of barley distribution with cylinder seal impression of a male figure, hunting","year":"3100","source":"Wikimedia Commons","license":"CC0","url":"https://commons.wikimedia.org/wiki/File:Cuneiform_tablet-_administrative_account_of_barley_distribution_with_cylinder_seal_impression_of_a_male_figure%2C_hunting_dogs%2C_and_boars_MET_011.alt.jpg"},{"src":"/img/mesopotamia/hammurabi.jpg","alt":"Estela de basalto negro con un relieve en la parte alta y el resto cubierto de escritura cuneiforme","width":1200,"height":1975,"role":"figura","section":4,"caption":"La estela del Código de Hammurabi, hacia 1750 a. C. Arriba, el rey recibe las insignias del dios Shamash; debajo, casi trescientas sentencias.","author":"Mbzt","title":"P1050763 Louvre code Hammurabi face rwk","year":"2011","source":"Wikimedia Commons","license":"CC BY 3.0","url":"https://commons.wikimedia.org/wiki/File:P1050763_Louvre_code_Hammurabi_face_rwk.JPG"}]}]'::jsonb, 0, true
from public.topics where slug = 'mesopotamia'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: mundo-actual
insert into public.lessons (topic_id, title, body, position, published)
select id, 'El mundo desde 1991', '[{"type":"section","title":"El momento unipolar","text":"La década de los noventa empezó con una expectativa. Francis Fukuyama había publicado en 1989 un ensayo que sostenía que la democracia liberal y el mercado no tenían ya rival ideológico y que en ese sentido la historia había terminado. La tesis se caricaturizó mucho, porque no afirmaba que dejaran de ocurrir cosas, sino que no quedaban alternativas sistémicas con pretensión universal. Samuel Huntington respondió en 1993 que los conflictos futuros se librarían entre civilizaciones y no entre ideologías, una tesis igualmente discutida y todavía más citada.\n\nLa realidad de los noventa fue menos limpia que cualquiera de las dos. Hubo una expansión democrática real, con transiciones en América Latina, Europa oriental, Sudáfrica y parte de Asia, y una integración económica sin precedentes tras la creación de la Organización Mundial del Comercio en 1995. Pero también hubo guerras de desintegración estatal en Yugoslavia y en el Cáucaso, un genocidio en Ruanda que la comunidad internacional vio venir y no detuvo, y crisis financieras en México, Asia y Rusia que mostraron la fragilidad de los flujos de capital liberalizados.\n\nEl modelo económico dominante se resumió en lo que John Williamson llamó Consenso de Washington: disciplina fiscal, liberalización comercial y financiera, privatizaciones y desregulación. Se aplicó como condición de los préstamos del Fondo Monetario y del Banco Mundial y produjo resultados muy desiguales. En Europa oriental la terapia de choque provocó un hundimiento del producto y de la esperanza de vida en Rusia; en Asia oriental los países que crecieron lo hicieron con políticas industriales activas que el consenso desaconsejaba.\n\nEuropa siguió su propio camino. Maastricht convirtió en 1992 la Comunidad Económica en Unión Europea, con ciudadanía común y una moneda única que llegaría en 1999. Fue una apuesta política enorme: unificar la moneda sin unificar la política fiscal, con la idea de que la integración monetaria arrastraría al resto. La ampliación al este, entre 2004 y 2007, incorporó a diez países del antiguo bloque soviético y duplicó el número de miembros.\n\nEstados Unidos ejerció una hegemonía que sus propios estrategas describían como un momento unipolar, no como un estado permanente. Intervino en los Balcanes tarde y con eficacia, promovió la ampliación de la OTAN pese a las advertencias de Kennan y otros sobre la reacción rusa, y sostuvo un orden institucional que le beneficiaba y que a la vez le imponía límites. La discusión sobre si ese orden era liberal o simplemente estadounidense sigue abierta.","textEso":null,"textBachillerato":null,"callout":"Fukuyama no dijo que fueran a dejar de pasar cosas. Dijo que no quedaban alternativas sistémicas con pretensión universal. Treinta años después la primera afirmación es obviamente falsa y la segunda vuelve a discutirse."},{"type":"section","title":"El 11 de septiembre y las guerras del terror","text":"Los atentados del 11 de septiembre de 2001 mataron a casi tres mil personas y reorganizaron la política internacional. La respuesta inmediata, la invasión de Afganistán, contó con amplio apoyo y derribó al régimen talibán en semanas; la ocupación duró veinte años, costó cientos de miles de millones y terminó en 2021 con el regreso del mismo régimen. La invasión de Irak en 2003, en cambio, se hizo sin autorización del Consejo de Seguridad, sobre la base de unas armas de destrucción masiva que no existían, y frente a las mayores manifestaciones simultáneas de la historia.\n\nLas consecuencias fueron mayores que la guerra. Irak se desintegró en una guerra civil sectaria, la disolución del ejército iraquí dejó a cientos de miles de hombres armados sin trabajo, y de ese caos salió una organización que en 2014 proclamó un califato sobre parte de Irak y Siria. El informe Chilcot británico de 2016 concluyó que la acción militar no era el último recurso y que las bases de inteligencia se presentaron con una certeza que no estaba justificada.\n\nLa lucha antiterrorista transformó también el interior de las democracias. Legislación de excepción, vigilancia masiva de comunicaciones revelada en 2013 por documentos filtrados desde la propia inteligencia estadounidense, detenciones indefinidas sin juicio en Guantánamo y un programa de entregas y tortura que varios Estados europeos facilitaron. El debate sobre la compatibilidad entre seguridad y derechos dejó de ser teórico.\n\nEn el mundo árabe, las revueltas de 2011 mostraron el otro lado. Movilizaciones masivas derribaron a gobiernos en Túnez, Egipto, Libia y Yemen, con una organización horizontal en la que las redes sociales tuvieron un papel instrumental que después se exageró. El balance a medio plazo fue duro: consolidación democrática solo en Túnez y de forma frágil, restauración autoritaria en Egipto, y guerras prolongadas en Libia, Siria y Yemen que produjeron la mayor crisis de refugiados desde 1945.\n\nLa conclusión estratégica que muchos extrajeron fue la de los límites del poder militar. Dos décadas de intervenciones no produjeron ni Estados estables ni democracias, y sí un descrédito de la idea de intervención humanitaria que había ganado terreno en los noventa. La doctrina de la responsabilidad de proteger, aprobada por Naciones Unidas en 2005, quedó muy debilitada tras el uso que se hizo de ella en Libia en 2011.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"La crisis de 2008 y la política que produjo","text":"La crisis financiera de 2008 comenzó en el mercado hipotecario estadounidense, se propagó por un sistema bancario internacional cargado de productos estructurados cuyo riesgo nadie había medido bien, y se convirtió en la mayor contracción desde los años treinta tras la quiebra de Lehman Brothers en septiembre. Fue una crisis del núcleo del sistema, no de su periferia, y la respuesta requirió rescates públicos de una escala inédita.\n\nAdam Tooze ha mostrado que la crisis fue mucho más transatlántica de lo que se contó: los bancos europeos estaban entre los mayores compradores de activos estadounidenses y sobrevivieron gracias a líneas de dólares abiertas por la Reserva Federal. La eurozona, sin embargo, convirtió una crisis bancaria en una crisis de deuda soberana, porque sus Estados no emitían en una moneda que controlaran y no existía un prestamista de última instancia hasta que el Banco Central Europeo asumió ese papel en 2012.\n\nLa respuesta europea fue la austeridad. Recortes de gasto y reformas estructurales en Grecia, Portugal, Irlanda, España e Italia, con caídas del producto de dos dígitos en el caso griego, paro juvenil superior al cincuenta por ciento y una emigración de jóvenes cualificados. El debate técnico sobre si el ajuste era necesario, excesivo o mal secuenciado se cruzó con otro sobre quién había decidido: los programas los negociaban instituciones sin responsabilidad electoral ante las poblaciones afectadas.\n\nLas consecuencias políticas se vieron pronto. Aparecieron o crecieron partidos que impugnaban el consenso anterior, por la izquierda y sobre todo por la derecha, con una combinación de crítica a la globalización, a la inmigración y a las élites tecnocráticas. El Brexit en 2016 y la elección presidencial estadounidense del mismo año fueron los dos resultados que hicieron visible el cambio en los dos países que habían liderado el orden liberal.\n\nSobre por qué ocurrió hay dos grandes explicaciones. La económica, defendida entre otros por Dani Rodrik, sostiene que la deslocalización industrial, el estancamiento salarial y la crisis produjeron un electorado con motivos objetivos de agravio. La cultural, formulada por Pippa Norris y Ronald Inglehart, sostiene que lo decisivo es una reacción de valores frente al cambio social y generacional. Los datos electorales sostienen parcialmente ambas y no permiten cerrar la discusión.","textEso":null,"textBachillerato":null,"callout":"La crisis de la eurozona no fue solo un problema de deuda: fue el descubrimiento de que una moneda sin Estado carece de prestamista de última instancia hasta que alguien decide serlo."},{"type":"section","title":"China y el retorno de la geopolítica","text":"El acontecimiento económico más importante del período no ocurrió en Occidente. China creció a tasas de dos dígitos durante tres décadas, sacó de la pobreza extrema a más de setecientos millones de personas y pasó de representar menos del dos por ciento del producto mundial en 1980 a ser la primera economía en paridad de poder adquisitivo. Su ingreso en la Organización Mundial del Comercio en 2001 aceleró la integración de su industria en las cadenas globales de valor.\n\nLa apuesta occidental fue que la integración económica produciría convergencia política. No ocurrió. El sistema chino se consolidó como un Estado de partido único con economía mixta, capacidad de planificación a largo plazo y un aparato de vigilancia tecnológica sin precedentes. Desde 2013, la Iniciativa de la Franja y la Ruta ha financiado infraestructuras en decenas de países, con debate abierto sobre si genera desarrollo o dependencia financiera.\n\nLa reacción estadounidense pasó de la integración a la competencia estratégica, con aranceles desde 2018, restricciones a la exportación de semiconductores avanzados y una política de reindustrialización. El resultado no ha sido una desconexión completa sino una fragmentación selectiva de las cadenas de suministro, con costes crecientes y con terceros países intentando no elegir bando.\n\nRusia recorrió otro camino. La década de los noventa dejó allí un hundimiento económico, una privatización que creó una oligarquía y una humillación nacional que la política posterior explotó. Desde 2000 se consolidó un régimen personalista sostenido por los ingresos energéticos, y desde 2008 en Georgia, 2014 en Crimea y 2022 en Ucrania se recurrió a la fuerza para revisar fronteras. La guerra en Ucrania desde 2022 ha sido el conflicto interestatal más grande en Europa desde 1945 y ha reactivado la OTAN, con la incorporación de Finlandia y Suecia.\n\nEl resultado agregado es un sistema que no es unipolar ni bipolar. India, Brasil, Indonesia, Turquía, los Estados del Golfo y varios países africanos actúan con autonomía creciente y se niegan a alinearse automáticamente, en una actitud que recuerda al No Alineamiento sin su vocabulario. Los organismos multilaterales heredados de 1945 reflejan cada vez peor esa distribución de poder, y su reforma lleva décadas bloqueada.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"Digitalización y esfera pública","text":"La web se abrió al uso público en 1993 y en tres décadas ha reorganizado la economía, la política y la vida cotidiana. La primera fase, hasta la crisis de las puntocom en 2000, fue de expansión desordenada; la segunda, desde mediados de la década siguiente, se caracterizó por la concentración: un puñado de plataformas globales que intermedian la búsqueda, la comunicación, el comercio y la publicidad, con una capitalización superior al producto de muchos Estados.\n\nShoshana Zuboff ha descrito ese modelo como capitalismo de vigilancia: un negocio basado en extraer datos de comportamiento para predecir y orientar la conducta futura, con la publicidad como primer producto y con la atención humana como recurso extraído. Otros análisis subrayan más los efectos de red y la lógica de monopolio natural que la novedad del modelo, pero coinciden en el diagnóstico de concentración.\n\nEl efecto sobre la esfera pública ha sido profundo y no unívoco. Las plataformas han permitido organizar movilizaciones sin estructuras previas, dar voz a quien no la tenía y desintermediar el acceso a la información. También han fragmentado el espacio informativo común, premiado la indignación por su rendimiento en atención, abaratado hasta lo trivial la producción de desinformación y hundido el modelo económico del periodismo profesional, que era el principal productor de verificación.\n\nLa vigilancia es la otra cara. Las revelaciones de 2013 sobre los programas de captación masiva de comunicaciones mostraron capacidades estatales que ninguna legislación había autorizado explícitamente. En paralelo, sistemas de reconocimiento facial y de puntuación social han sido desplegados con distintos grados de intensidad, y la Unión Europea ha intentado responder con normativa sobre protección de datos y sobre inteligencia artificial, con efecto extraterritorial de hecho.\n\nLa irrupción de sistemas de inteligencia artificial generativa desde 2022 ha añadido una capa nueva, con efectos sobre el trabajo cualificado, la educación y la propia noción de autoría y de prueba documental. Es demasiado pronto para escribir su historia, y precisamente por eso conviene decirlo: un historiador que en 1995 hubiera pronosticado los efectos de internet se habría equivocado en casi todo.","textEso":null,"textBachillerato":null,"callout":"El hundimiento económico del periodismo profesional no es un daño colateral de la digitalización: es la retirada del principal actor que producía verificación de manera sistemática."},{"type":"section","title":"Clima, pandemia y balance provisional","text":"El cambio climático es el proceso de fondo del período y el que menos encaja en las periodizaciones políticas. La ciencia está establecida desde hace décadas: la concentración de gases de efecto invernadero ha subido por encima de cualquier nivel de los últimos ochocientos mil años y la temperatura media global ha aumentado más de un grado respecto de la era preindustrial. Los informes sucesivos del panel intergubernamental han ido reduciendo la incertidumbre y acortando los plazos.\n\nLa respuesta institucional ha sido lenta y desigual: del Protocolo de Kioto de 1997, con objetivos vinculantes y sin Estados Unidos, al Acuerdo de París de 2015, con participación casi universal y compromisos voluntarios. El coste de las renovables se ha hundido más rápido de lo que casi nadie preveía, lo que ha hecho viable una transición que hace veinte años parecía inasumible; el ritmo sigue siendo insuficiente respecto de los objetivos declarados. La discusión sobre justicia climática, es decir, sobre quién emitió históricamente y quién sufre las consecuencias, es a la vez científica y política.\n\nLa pandemia de covid-19, desde 2020, fue el primer acontecimiento verdaderamente global y simultáneo de la era digital. Provocó millones de muertes, confinamientos que afectaron a la mayor parte de la humanidad, una contracción económica seguida de una respuesta fiscal y monetaria sin precedentes, y un desarrollo de vacunas en un tiempo récord acompañado de un reparto muy desigual. Puso a prueba la capacidad estatal, la cooperación internacional y la confianza pública en la ciencia, con resultados distintos en cada país y sin una correlación simple con el tipo de régimen.\n\nSobre el balance de la globalización hay datos que apuntan en direcciones opuestas y hay que sostener los dos. La pobreza extrema mundial cayó de cerca del cuarenta por ciento de la población en 1990 a menos del diez antes de la pandemia, la mortalidad infantil se redujo a menos de la mitad y la escolarización se generalizó. Al mismo tiempo, la desigualdad interna creció en la mayoría de los países ricos y en varios emergentes, y la curva del elefante de Branko Milanovic muestra con claridad quién ganó y quién no: las clases medias asiáticas y el uno por ciento global, no los trabajadores industriales de Occidente.\n\nEscribir la historia de este período tiene dos dificultades específicas. La primera es documental: buena parte de las fuentes está clasificada, dispersa en servidores privados o en formatos que se degradan, y la abundancia de datos no equivale a disponibilidad. La segunda es de perspectiva: no sabemos qué acontecimiento de los últimos treinta años resultará decisivo. Es exactamente el problema que tenía en 1935 alguien que intentara explicar 1919, y la única defensa disponible es la misma: describir los procesos con precisión y desconfiar de las conclusiones redondas.","textEso":null,"textBachillerato":null,"callout":null},{"type":"concepts","items":[{"term":"Momento unipolar","definition":"Situación posterior a 1991 con una sola superpotencia. Sus propios teóricos la describieron como transitoria y no como un estado permanente del sistema."},{"term":"Consenso de Washington","definition":"Paquete de disciplina fiscal, liberalización, privatización y desregulación promovido por los organismos financieros internacionales desde los años noventa."},{"term":"Cadenas globales de valor","definition":"Fragmentación de la producción entre países según ventajas de coste y especialización. Base material de la globalización productiva."},{"term":"Fin de la historia","definition":"Tesis de Fukuyama de 1989: no quedan alternativas sistémicas con pretensión universal frente a la democracia liberal y el mercado."},{"term":"Choque de civilizaciones","definition":"Tesis de Huntington de 1993 según la cual los conflictos futuros seguirían líneas culturales y religiosas en vez de ideológicas."},{"term":"Responsabilidad de proteger","definition":"Principio aprobado por Naciones Unidas en 2005 que admite la intervención ante atrocidades masivas. Muy debilitado tras su uso en Libia en 2011."},{"term":"Vigilancia masiva","definition":"Captación indiscriminada de comunicaciones por servicios de inteligencia, documentada en 2013. Planteó el conflicto entre seguridad y derechos en términos concretos."},{"term":"Crisis de las subprime","definition":"Colapso iniciado en el mercado hipotecario estadounidense en 2007 y extendido por productos estructurados cuyo riesgo estaba mal medido."},{"term":"Austeridad","definition":"Política de recorte del gasto público aplicada en la eurozona tras 2010 para reducir deuda. Su necesidad y su secuencia siguen discutiéndose."},{"term":"Populismo","definition":"Estilo político que opone un pueblo homogéneo a una élite corrupta. Su auge desde 2008 admite explicaciones económicas y culturales que compiten entre sí."},{"term":"Capitalismo de vigilancia","definition":"Modelo descrito por Zuboff basado en extraer datos de comportamiento para predecir y orientar la conducta, con la atención como recurso principal."},{"term":"Franja y la Ruta","definition":"Programa chino de financiación de infraestructuras en decenas de países desde 2013, discutido entre motor de desarrollo y generador de dependencia."},{"term":"Acuerdo de París","definition":"Tratado climático de 2015 con participación casi universal y compromisos nacionales voluntarios, frente al modelo vinculante y parcial de Kioto."},{"term":"Curva del elefante","definition":"Representación de Milanovic del cambio de renta global entre 1988 y 2008: ganan las clases medias asiáticas y el uno por ciento, se estancan los trabajadores occidentales."}]},{"type":"debates","items":[{"question":"¿Cómo hay que interpretar el orden surgido en 1991?","positions":[{"school":"Fin de la historia (Fukuyama, 1989)","argument":"No quedan alternativas sistémicas con pretensión universal. Los conflictos seguirán, pero ya no entre modelos rivales de organización política y económica con vocación de sustituir al liberalismo."},{"school":"Choque de civilizaciones (Huntington, 1993)","argument":"La ideología deja paso a la cultura como línea de fractura. Los conflictos se producirán entre bloques civilizatorios y no dentro de un marco común de valores."},{"school":"Retorno del realismo (Mearsheimer; Kagan)","argument":"La unipolaridad era una anomalía transitoria. Con el ascenso de nuevos polos vuelve la competencia entre grandes potencias, que es la situación normal del sistema internacional."}],"state":"Los tres marcos se citan más de lo que se leen. El período ha desmentido las predicciones concretas de todos ellos y ha dado la razón parcialmente al diagnóstico realista sobre la transitoriedad de la unipolaridad."},{"question":"¿Ha sido positiva la globalización?","positions":[{"school":"Convergencia global (Milanovic)","argument":"La pobreza extrema cayó del cuarenta a menos del diez por ciento de la humanidad y la desigualdad entre países se redujo por primera vez desde la revolución industrial. Es la mayor mejora material de la historia."},{"school":"Coste interno y político (Rodrik; Piketty)","argument":"La desigualdad dentro de los países creció, la desindustrialización destruyó comunidades enteras en Occidente y la liberalización financiera transfirió a los Estados la factura de las crisis."}],"state":"Las dos series de datos son correctas y describen fenómenos distintos: la global y la nacional. La discusión útil se ha desplazado a qué tipo de globalización es compatible con la cohesión política interna."},{"question":"¿Qué explica el auge de los populismos desde 2008?","positions":[{"school":"Explicación económica (Rodrik)","argument":"La deslocalización, el estancamiento salarial, la austeridad y la percepción de que las crisis las pagan siempre los mismos crearon un electorado con motivos objetivos de agravio."},{"school":"Reacción cultural (Norris e Inglehart, 2019)","argument":"Lo decisivo es un rechazo generacional al cambio de valores en materia de género, inmigración y diversidad. El voto correlaciona mejor con actitudes culturales que con renta."},{"school":"Fallo institucional (Levitsky y Ziblatt, 2018)","argument":"El factor crítico es la erosión de las normas no escritas de la competencia democrática y la disposición de partidos establecidos a pactar con fuerzas que no aceptan las reglas."}],"state":"Los datos electorales sostienen parcialmente las tres. La investigación reciente tiende a combinarlas mediante mecanismos: el agravio económico activa marcos culturales preexistentes cuando las instituciones no canalizan el conflicto."}]},{"type":"timeline","items":[{"date":"1991","event":"Disolución de la URSS, primera guerra del Golfo e inicio de las guerras de Yugoslavia."},{"date":"1992–1993","event":"Tratado de Maastricht y nacimiento de la Unión Europea. Entra en vigor el mercado único."},{"date":"1994","event":"Genocidio de Ruanda, con unas ochocientas mil víctimas en cien días y una inacción internacional documentada."},{"date":"1995","event":"Creación de la Organización Mundial del Comercio y matanza de Srebrenica."},{"date":"1999","event":"Nace el euro como moneda de cuenta. Intervención de la OTAN en Kosovo sin mandato del Consejo de Seguridad."},{"date":"2001","event":"Atentados del 11 de septiembre, invasión de Afganistán e ingreso de China en la OMC."},{"date":"2003","event":"Invasión de Irak sin autorización de Naciones Unidas y sin que aparecieran las armas alegadas."},{"date":"2008","event":"Quiebra de Lehman Brothers y crisis financiera global. Recesión y rescates bancarios masivos."},{"date":"2010–2012","event":"Primaveras árabes, crisis de la deuda en la eurozona y políticas de austeridad."},{"date":"2014","event":"Anexión rusa de Crimea y guerra en el este de Ucrania. Fin del orden europeo posterior a 1991."},{"date":"2015","event":"Acuerdo de París sobre el clima y Objetivos de Desarrollo Sostenible de Naciones Unidas."},{"date":"2016","event":"Referéndum del Brexit y elección presidencial estadounidense: dos resultados que reordenan la política occidental."},{"date":"2020–2022","event":"Pandemia de covid-19, con millones de muertos, y guerra a gran escala en Ucrania desde febrero de 2022."}]},{"type":"sources","items":[{"author":"Francis Fukuyama","title":"El fin de la Historia y el último hombre","year":"1992","kind":"primaria","note":"Formulación completa de una tesis que se cita casi siempre en su versión caricaturizada."},{"author":"Samuel Huntington","title":"El choque de civilizaciones","year":"1996","kind":"primaria","note":"Marco alternativo al anterior, enormemente influyente en el debate posterior al 11 de septiembre."},{"author":"Estados miembros de la CE","title":"Tratado de Maastricht","year":"1992","kind":"primaria","note":"Crea la Unión Europea y el compromiso de moneda única. Base jurídica de la integración posterior."},{"author":"John Williamson","title":"What Washington Means by Policy Reform","year":"1990","kind":"primaria","note":"Texto que acuñó la expresión Consenso de Washington, después usada en un sentido más amplio que el original."},{"author":"Naciones Unidas","title":"Informe Carlsson sobre Ruanda","year":"1999","kind":"primaria","note":"Investigación oficial sobre la inacción internacional durante el genocidio de 1994."},{"author":"Comisión Nacional sobre los Ataques Terroristas","title":"Informe del 11-S","year":"2004","kind":"primaria","note":"Reconstrucción oficial de los atentados y de los fallos de coordinación previos."},{"author":"John Chilcot","title":"Informe de la investigación sobre Irak","year":"2016","kind":"primaria","note":"Concluye que la acción militar no fue el último recurso y que la inteligencia se presentó con certeza injustificada."},{"author":"Naciones Unidas","title":"Acuerdo de París","year":"2015","kind":"primaria","note":"Compromisos nacionales voluntarios con revisión periódica. Modelo opuesto al vinculante de Kioto."},{"author":"Grupo Intergubernamental de Expertos sobre el Cambio Climático","title":"Informes de evaluación","year":"1990–2023","kind":"primaria","note":"Síntesis periódica del estado de la ciencia climática, con incertidumbres explicitadas."},{"author":"Naciones Unidas","title":"Objetivos de Desarrollo Sostenible","year":"2015","kind":"primaria","note":"Agenda global para 2030 que sustituye a los Objetivos del Milenio y amplía su alcance."},{"author":"Eric Hobsbawm","title":"Historia del siglo XX","year":"1994","kind":"estudio","note":"Cierra el siglo corto en 1991 y plantea el problema de escribir historia sin distancia."},{"author":"Joseph Stiglitz","title":"El malestar en la globalización","year":"2002","kind":"estudio","note":"Crítica desde dentro de las instituciones financieras internacionales a la condicionalidad de los años noventa."},{"author":"Tony Judt","title":"Postguerra","year":"2005","kind":"estudio","note":"Historia de Europa hasta 2005 que conecta el período posterior a 1991 con la larga posguerra."},{"author":"Branko Milanovic","title":"Desigualdad mundial","year":"2016","kind":"estudio","note":"Origen de la curva del elefante y del análisis de la desigualdad global frente a la nacional."},{"author":"Thomas Piketty","title":"El capital en el siglo XXI","year":"2013","kind":"estudio","note":"Series históricas de largo plazo sobre concentración de renta y patrimonio en los países desarrollados."},{"author":"Dani Rodrik","title":"La paradoja de la globalización","year":"2011","kind":"estudio","note":"Formula el trilema entre hiperglobalización, soberanía nacional y democracia."},{"author":"Adam Tooze","title":"Crash","year":"2018","kind":"estudio","note":"Historia global de la crisis de 2008 que muestra su carácter transatlántico y el papel de la Reserva Federal."},{"author":"Shoshana Zuboff","title":"La era del capitalismo de la vigilancia","year":"2019","kind":"estudio","note":"Analiza el modelo de negocio basado en datos de comportamiento y su efecto sobre la autonomía individual."},{"author":"Steven Levitsky y Daniel Ziblatt","title":"Cómo mueren las democracias","year":"2018","kind":"estudio","note":"Estudio comparado sobre la erosión democrática desde dentro, sin golpes de Estado."},{"author":"Pippa Norris y Ronald Inglehart","title":"Cultural Backlash","year":"2019","kind":"estudio","note":"Defiende la explicación cultural y generacional del voto populista frente a la puramente económica."},{"author":"Peter Frankopan","title":"Las rutas de la seda","year":"2015","kind":"estudio","note":"Relectura de la historia mundial que descentra Europa y ayuda a situar el ascenso asiático actual."},{"author":"Mark Mazower","title":"Gobernar el mundo","year":"2012","kind":"estudio","note":"Historia de las instituciones internacionales y de las ideas de gobierno global desde 1815."}]},{"type":"images","items":[{"src":"/img/mundo-actual/portada.jpg","alt":"Representación gráfica de las conexiones de internet como una maraña radial de líneas de colores sobre fondo negro","width":1200,"height":1200,"role":"portada","caption":"Mapa parcial de internet trazado a partir de rutas de red. Ilustración de datos, no una fotografía.","author":"The Opte Project","title":"Internet map 1024","year":"2005","source":"Wikimedia Commons","license":"CC BY 2.5","url":"https://commons.wikimedia.org/wiki/File:Internet_map_1024.jpg"},{"src":"/img/mundo-actual/once-s.jpg","alt":"Fotografía aérea de una zona urbana con un enorme montón de escombros humeantes rodeado de edificios dañados","width":1200,"height":960,"role":"figura","section":1,"caption":"La Zona Cero de Nueva York, 16 de septiembre de 2001. La respuesta abrió dos guerras y un marco jurídico de excepción que duró décadas.","author":"Chief Photographer''s Mate Eric J. TIlford.","title":"World Trade Center collapsed following the Sept. 11 terrorist attack September 16 2001","year":"2001","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:World_Trade_Center_collapsed_following_the_Sept._11_terrorist_attack_September_16_2001.jpg"},{"src":"/img/mundo-actual/lehman.jpg","alt":"Fotografía del rótulo iluminado de un banco en la fachada de un rascacielos, visto desde la calle","width":1200,"height":1600,"role":"figura","section":2,"caption":"La sede de Lehman Brothers en Nueva York. Su quiebra, en septiembre de 2008, convirtió una crisis hipotecaria en una crisis financiera mundial.","author":"David Shankbone","title":"Lehman Brothers Times Square by David Shankbone","year":"2007","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Lehman_Brothers_Times_Square_by_David_Shankbone.jpg"},{"src":"/img/mundo-actual/pudong.jpg","alt":"Fotografía nocturna de una fila de rascacielos iluminados al otro lado de un río, con reflejos en el agua","width":1200,"height":680,"role":"figura","section":3,"caption":"Pudong, en Shanghái. En 1990 era campo y almacenes; treinta años después, uno de los centros financieros del mundo.","author":"Wechselberger","title":"Shanghai-pudong night","year":"2008","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Shanghai-pudong_night.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'mundo-actual'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: plena-edad-media
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Ciudades, comercio y universidades', '[{"type":"section","title":"El despegue del año mil","text":"Todo lo demás depende de esto: entre el siglo X y el XIV la población europea pasó de unos treinta y cinco o cuarenta millones a unos setenta u ochenta. Las cifras son estimaciones construidas sobre censos fiscales parciales y registros señoriales, con márgenes amplios, pero la dirección no se discute. Ese crecimiento exigió más alimento, y el alimento salió de roturar y de producir mejor.\n\nLa roturación fue el motor menos vistoso y más decisivo: se talaron bosques, se desecaron marismas, se ganó tierra al mar en Flandes y se colonizó hacia el este del Elba. En paralelo se difundieron un conjunto de técnicas que no eran nuevas pero que ahora se combinaron: el arado pesado de vertedera, capaz de voltear los suelos húmedos y arcillosos del norte, la collera rígida que permite tirar del caballo sin ahogarlo, la herradura, el enganche en fila y la rotación trienal, que deja en barbecho un tercio de la tierra en lugar de la mitad y añade una siembra de primavera de leguminosas, con el efecto adicional de fijar nitrógeno y mejorar la dieta.\n\nLa energía hidráulica se generalizó. El Domesday Book de 1086 registra en Inglaterra más de cinco mil quinientos molinos de agua para una población en torno a uno o dos millones de habitantes: un molino por cada pocos centenares de personas. Los molinos no solo molían grano; se aplicaron al batán de los paños, a la sierra, al martillo de forja y al fuelle.\n\nLynn White Jr. defendió en 1962 que estas innovaciones técnicas explican por sí solas la transformación social de Europa. La crítica posterior ha corregido su cronología —el arado pesado y el estribo aparecen antes y se difunden más despacio de lo que él suponía— y ha desconfiado del determinismo: la técnica estaba disponible mucho antes de que se generalizara, así que hay que explicar por qué se adoptó cuando se adoptó. La respuesta apunta a la demanda, a la relativa estabilidad tras el fin de las incursiones vikingas, magiares y sarracenas, y a señores interesados en un excedente comercializable.\n\nSuele añadirse un factor climático, el llamado óptimo medieval de los siglos X a XIII. Conviene manejarlo con cuidado: las reconstrucciones globales muestran que no hubo un calentamiento sincrónico en todo el planeta, sino anomalías regionales, y que en Europa occidental el efecto fue real pero moderado. Es un factor favorable, no una explicación.","textEso":"Entre los siglos XI y XIII Europa creció como no lo había hecho en mil años. La causa no fue una sola: mejoró el clima, se extendieron el arado pesado, el molino de agua y la rotación de tres hojas, que dejaba menos tierra en barbecho, y se roturaron bosques y pantanos. Con más comida, la población casi se dobló. Y con más gente y más excedente, las ciudades volvieron a llenarse después de siglos de decadencia.","textBachillerato":"El crecimiento de los siglos XI a XIII es el mayor de la Europa premoderna y tiene causas concurrentes. El llamado óptimo climático medieval elevó las temperaturas medias y alargó los ciclos agrícolas. Se difundieron innovaciones técnicas acumuladas antes: arado pesado de vertedera, capaz de trabajar los suelos húmedos del norte; collera rígida, que multiplicaba la fuerza de tiro del caballo; herradura; molino hidráulico y, más tarde, de viento.\n\nLa rotación trienal fue quizá lo más importante, porque reducía el barbecho de la mitad a un tercio y aumentaba la superficie cultivada sin roturar más. A ello se sumó una expansión del espacio agrario mediante tala de bosques y desecación de marismas. El resultado fue un crecimiento demográfico que pudo duplicar la población europea. Ese excedente sostenido es la condición material de todo lo demás: ciudades, comercio, catedrales y universidades.","callout":"La rotación trienal no solo aumenta la superficie sembrada de la mitad a dos tercios: la siembra de primavera introduce leguminosas, que fijan nitrógeno y aportan proteína. Un cambio de calendario agrícola es también un cambio de dieta."},{"type":"section","title":"La ciudad: un estatuto jurídico antes que un tamaño","text":"En la Edad Media una ciudad no se define por el número de habitantes sino por el derecho. Lo que separa a la villa del campo es una carta —fuero, carta de franquicia, privilegio— que sustituye las obligaciones señoriales por un censo fijo en dinero, reconoce un tribunal propio, una milicia, un mercado y, a menudo, la libertad personal de quien reside en ella un tiempo. La fórmula alemana que resume la práctica, «el aire de la ciudad hace libre al cabo de un año y un día», es una formulación tardía de una costumbre real: el siervo huido que no era reclamado en ese plazo quedaba libre.\n\nLa forma más ambiciosa fue la comuna: una asociación jurada de vecinos que se compromete mutuamente y negocia, compra o arranca por la fuerza el gobierno de la ciudad a su señor u obispo. Aparece en el norte de Italia a finales del siglo XI y se extiende por Flandes, Renania y el norte de Francia. En Italia derivó en repúblicas urbanas con cónsules y después con *podestà*, un magistrado forastero contratado por un año precisamente para que no tuviera clientela local.\n\nDentro de la ciudad, la vida económica se organizó en gremios. Su función declarada era garantizar la calidad, formar aprendices y sostener a viudas y enfermos; su función efectiva incluía fijar precios, limitar la competencia y controlar quién podía ejercer un oficio. Fueron a la vez escuela técnica, seguro social y monopolio, y sus tensiones internas —maestros contra oficiales, oficios mayores contra menores— alimentaron los conflictos urbanos del siglo XIV.\n\nLas magnitudes conviene tenerlas presentes para no exagerar. Hacia 1300 París pudo rondar los doscientos mil habitantes, y Milán, Venecia y Florencia el entorno de los cien mil; pero la inmensa mayoría de las localidades con estatuto urbano tenían entre dos mil y diez mil, y más del ochenta por ciento de la población europea seguía viviendo en el campo. La ciudad fue decisiva por lo que concentraba —capital, derecho, escritura, información—, no por su peso demográfico.\n\nLa explicación clásica del renacimiento urbano la dio Henri Pirenne: las ciudades habrían nacido del comercio de larga distancia, alrededor de mercaderes ambulantes que se asentaban junto a fortalezas y monasterios. La investigación posterior ha invertido buena parte del argumento. Muchas ciudades crecieron sobre sedes episcopales que nunca desaparecieron del todo, el motor inicial fue el excedente agrario y el mercado comarcal, y el comercio internacional llegó a menudo después. La aportación de Pirenne que sí resiste es haber puesto el foco en la ciudad como sujeto histórico con dinámica propia, y no como apéndice del mundo señorial.","textEso":"Una ciudad medieval no se define por su tamaño, sino por su derecho. Sus habitantes conseguían del rey o del señor una carta que les daba privilegios: comerciar libremente, tener sus propios tribunales, gobernarse. De ahí el dicho alemán de que el aire de la ciudad hace libre, porque un siervo que vivía un año y un día en una ciudad dejaba de serlo. Dentro, los artesanos se organizaban en gremios que controlaban precios, calidad y quién podía ejercer cada oficio.","textBachillerato":"La ciudad medieval se define jurídicamente antes que demográficamente. Lo que la constituye es una carta de franquicia arrancada al rey o al señor: libertad personal de sus vecinos, tribunal propio, derecho a regular mercados y, en muchos casos, gobierno mediante concejo. La fórmula alemana Stadtluft macht frei recoge una norma real: el siervo que residía un año y un día en la ciudad quedaba libre.\n\nSu organización interna giraba en torno a los gremios, que regulaban acceso al oficio, calidad, precios y jornada, y funcionaban también como sociedades de socorro mutuo y cofradías religiosas. Se han valorado de dos maneras: como mecanismo de protección y estabilidad, y como freno a la innovación y a la competencia. Ambas cosas son ciertas según el momento. El dato político relevante es que la ciudad introduce en el mapa feudal un poder colectivo que no encaja en el esquema señorial ni en el de los tres órdenes.","callout":null},{"type":"section","title":"Comercio: rutas, crédito e instrumentos","text":"El eje del comercio europeo unió dos polos manufactureros: Flandes, que tejía paños con lana inglesa, e Italia, que los acababa, teñía y redistribuía, y que controlaba el acceso a las especias, la seda y el alumbre del Mediterráneo oriental. Entre ambos se situaron las ferias de Champaña, un ciclo de seis ferias anuales encadenadas en cuatro localidades que funcionó durante casi dos siglos como cámara de compensación de Europa: allí no solo se compraban mercancías, se saldaban deudas y se cambiaban monedas bajo la protección de los condes.\n\nEn el norte, la Hansa articuló el Báltico y el mar del Norte desde Lübeck, con factorías permanentes en Nóvgorod, Bergen, Brujas y Londres, y un comercio de productos de volumen: cereal, madera, pescado salado, cera, pieles. En el sur, Venecia y Génova compitieron por las rutas del Levante y por colonias en el mar Negro; la cuarta cruzada, desviada en 1204 contra Constantinopla, se explica bastante mejor como operación comercial veneciana que como empresa religiosa.\n\nLo que hizo posible ese volumen fue una batería de instrumentos jurídicos y contables. La *commenda* asociaba a quien ponía el capital con quien viajaba y trabajaba, repartiendo el beneficio —habitualmente tres cuartas partes para el capital— y limitando la pérdida al capital aportado: es el antepasado directo de la sociedad en comandita. La letra de cambio permitió pagar en una plaza y cobrar en otra, en otra moneda, sin mover metal. La contabilidad por partida doble aparece en los libros italianos a comienzos del siglo XIV, mucho antes de que Luca Pacioli la codificara en 1494. Y en el siglo XIV se documenta ya el seguro marítimo como contrato autónomo.\n\nTodo esto chocaba con la prohibición canónica de la usura, entendida como cobrar cualquier cosa por encima del principal. La respuesta no fue ignorar la norma sino rodearla con técnica jurídica: el interés se escondía en el diferencial de cambio entre dos monedas y dos plazas, en el reparto del riesgo o en penalizaciones por demora pactadas de antemano. Los teólogos afinaron las excepciones —*damnum emergens*, *lucrum cessans*— y la práctica mercantil avanzó por ese hueco. A los judíos, excluidos de gremios y de la propiedad de la tierra en muchos territorios, se les asignó el papel de prestamistas y después se les reprochó ejercerlo.\n\nEl síntoma más claro del cambio de escala es monetario. Europa llevaba siglos sin acuñar oro de manera regular; en 1252 Génova y Florencia emitieron el genovino y el florín, y Venecia el ducado en 1284. El florín se convirtió en moneda de referencia internacional durante dos siglos.\n\nRobert Lopez llamó a este conjunto «revolución comercial», y la etiqueta ha hecho fortuna. Tiene un problema de perspectiva: los documentos de la Gueniza de El Cairo estudiados por Shelomo Goitein muestran que el mundo islámico usaba mucho antes instrumentos equivalentes —la *suftaya*, comparable a la letra de cambio, y el *qirad*, muy próximo a la *commenda*—, y Abraham Udovitch defendió que la transmisión fue directa. Europa no inventó tanto como difundió, sistematizó y llevó a escala.","textEso":"El comercio volvió a unir Europa. En el norte, la Hansa dominaba el Báltico con madera, cereal, pescado y pieles; en el sur, Venecia y Génova traían especias y seda de Oriente. Se encontraban en las ferias de Champaña, en Francia. Como transportar monedas era peligroso, se inventaron instrumentos financieros: la letra de cambio permitía pagar en una ciudad y cobrar en otra, y aparecieron los primeros bancos y la contabilidad por partida doble.","textBachillerato":"El comercio de larga distancia se rearticula en dos grandes ejes. En el norte, la Hansa agrupa a decenas de ciudades del Báltico y el mar del Norte en torno al comercio de cereal, madera, pescado salado, cera y pieles, con capacidad para negociar como potencia e incluso hacer la guerra. En el sur, Venecia y Génova controlan la conexión con el Mediterráneo oriental: especias, seda, alumbre.\n\nLas ferias de Champaña funcionaron durante más de un siglo como punto de encuentro de ambos circuitos, con protección del conde y jurisdicción mercantil propia. La necesidad de mover valor sin transportar metal impulsó una innovación financiera notable: letra de cambio, seguro marítimo, sociedades de comercio con responsabilidad limitada, contabilidad por partida doble y bancos como los de las grandes familias florentinas. La prohibición canónica de la usura se sorteó con figuras contractuales que enmascaraban el interés, lo que muestra hasta qué punto la práctica iba por delante de la norma.","callout":"La *commenda* limita la pérdida del inversor al capital aportado y reparte el beneficio con quien viaja. Responsabilidad limitada y separación entre capital y gestión: dos rasgos de la empresa moderna, documentados en Venecia en el siglo XI."},{"type":"section","title":"La universidad: una corporación con privilegios","text":"*Universitas* no significaba universidad sino corporación: el conjunto de personas asociadas para un fin, con personalidad jurídica, estatutos y jurisdicción. La universidad medieval es, literalmente, un gremio de la enseñanza, y ese origen explica casi todo lo demás.\n\nNacieron con dos modelos opuestos. En Bolonia la corporación era de estudiantes: contrataban a los profesores, les fijaban el programa y los multaban si se saltaban una lección o no terminaban el temario. En París la corporación era de maestros, agrupados por facultades y naciones, con el canciller de la catedral como contrapeso. De ahí derivan las dos familias europeas de gobierno universitario. La fecha de 1088 para Bolonia no procede de ningún documento: se fijó en 1888, cuando la ciudad organizó su octavo centenario.\n\nEl instrumento decisivo fueron los privilegios. La *Authentica Habita* de Federico I, en 1155, protegió a los estudiantes en viaje y les permitió ser juzgados por su maestro o por el obispo, no por el tribunal local. Los papas concedieron después la *licentia ubique docendi*, la licencia para enseñar en cualquier lugar de la cristiandad, que es el origen del reconocimiento internacional de títulos. Y las corporaciones descubrieron pronto su arma: la huelga y la dispersión. Tras la revuelta y la represión de 1229, los maestros de París suspendieron las clases y se marcharon dos años; en 1231 Gregorio IX cedió con *Parens scientiarum*, que reconoció a la universidad el derecho a darse estatutos propios y a suspender la docencia.\n\nEl método era tan característico como el contenido. La *lectio* comentaba un texto autorizado; la *quaestio* extraía de él un problema; la *disputatio* enfrentaba en público argumentos y contraargumentos ante un maestro que después determinaba. Abelardo había fijado el procedimiento en *Sic et non*, alineando ciento cincuenta y ocho cuestiones con autoridades contradictorias sobre cada una y dejando al lector la tarea de resolverlas. Pensar consistía en organizar el desacuerdo, no en evitarlo.\n\nEl combustible llegó de fuera. Entre los siglos XII y XIII se tradujo al latín, sobre todo desde el árabe en Toledo y desde el griego en Sicilia, el corpus completo de Aristóteles junto con los comentarios de Avicena y Averroes y la medicina y matemática griegas y árabes. La incorporación fue conflictiva: la enseñanza de la física y la metafísica aristotélicas se prohibió en París en 1210, y las condenas de 1270 y 1277 —esta última con doscientas diecinueve proposiciones— muestran hasta qué punto la institución estaba discutiendo consigo misma sobre los límites entre razón y fe.\n\nConviene no idealizarla. Se estudiaba en latín, se accedía por vía clerical, costaba dinero y las mujeres quedaban excluidas por completo. Fue una institución de una minoría muy pequeña. Su importancia está en otro sitio: creó un cuerpo profesional de intelectuales urbanos asalariados —Jacques Le Goff los llamó los intelectuales de la Edad Media— y una forma corporativa autónoma que ha sobrevivido ocho siglos.","textEso":"La universidad nació en esta época y era algo nuevo: una corporación de estudiantes y maestros con privilegios propios, tribunales aparte y el derecho de dejar de dar clases si se les presionaba. Bolonia, París, Oxford, Salamanca. Se estudiaba en latín, lo que permitía moverse de una a otra, y las materias eran artes, derecho, medicina y teología. Buena parte de lo que se enseñaba llegó traducido del árabe, y esa recuperación de Aristóteles obligó a repensarlo todo.","textBachillerato":"La universidad es una creación medieval sin precedente antiguo. No es una escuela, sino una universitas: una corporación jurídica de maestros o de estudiantes, con personalidad propia, privilegios reconocidos por papa o rey, jurisdicción interna y el derecho de huelga y de traslado, que usó con eficacia frente a las autoridades locales.\n\nBolonia se organiza en torno a los estudiantes y se especializa en derecho; París, en torno a los maestros, y destaca en teología. El latín como lengua común y la homologación de los grados crean un espacio académico europeo con movilidad real. El plan de estudios parte de las artes liberales y culmina en derecho, medicina o teología. Su motor intelectual fue la recepción de Aristóteles traducido del árabe y del griego, que obligó a articular razón y fe; la escolástica, con Tomás de Aquino, es la respuesta a ese problema y no el pensamiento inmóvil que la caricatura sugiere.","callout":"La huelga de París de 1229 duró dos años y terminó con el papa concediendo a la universidad estatutos propios. El derecho de autogobierno académico nació de un conflicto laboral."},{"type":"section","title":"Reforma, derecho y persecución","text":"La transformación institucional más profunda del periodo empezó dentro de la Iglesia. La reforma gregoriana quiso liberar al clero del control de los poderes laicos: prohibición de la simonía, celibato obligatorio, elección de los obispos sin injerencia. El *Dictatus papae* de 1075 llevó la pretensión hasta el extremo de afirmar la potestad papal para deponer emperadores, y la querella de las investiduras que siguió, con el episodio de Canossa en 1077, terminó en el compromiso de Worms de 1122: el emperador renuncia a la investidura con los símbolos espirituales y conserva la temporal.\n\nHarold Berman propuso leer ese conflicto como una «revolución papal» fundadora de la tradición jurídica occidental. Su argumento es que la separación entre dos jurisdicciones que se reconocen mutuamente competentes obligó a definir con precisión el ámbito de cada una, y de ahí salieron el derecho canónico como sistema, la recuperación del derecho romano y la idea, poco frecuente en la historia, de que el poder está sometido a un derecho que no fabrica él mismo.\n\nLos materiales acompañaron. Hacia 1140 Graciano compuso la *Concordia de los cánones discordantes*, que aplicó al derecho de la Iglesia el mismo método escolástico de armonizar autoridades enfrentadas. En Bolonia, los glosadores reconstruyeron el *Corpus iuris civilis* justinianeo y formaron a generaciones de juristas que las monarquías contrataron de inmediato: el jurista profesional es una figura de este periodo, y el crecimiento del Estado en los siglos siguientes se apoya en él.\n\nLa misma capacidad de organización se aplicó a definir y perseguir la disidencia. El IV Concilio de Letrán de 1215 impuso la confesión anual y la comunión pascual, definió la transustanciación y ordenó signos distintivos para judíos y musulmanes. Los cátaros del Languedoc fueron combatidos con una cruzada interna entre 1209 y 1229, y a partir de los años treinta del siglo XIII se generalizó la *inquisitio*, un procedimiento judicial en el que el tribunal investiga de oficio sin necesidad de acusador, con registro escrito y archivo: una innovación procesal de largo recorrido, adoptada después por la justicia civil europea.\n\nR. I. Moore sintetizó esta deriva en 1987 con una tesis discutida y muy productiva: entre 1000 y 1250 Europa se convirtió en una «sociedad persecutoria», que construyó categorías estables de excluidos —herejes, judíos, leprosos, sodomitas— y desarrolló instituciones permanentes para identificarlos y castigarlos. Su punto decisivo es que la persecución no fue el desbordamiento espontáneo del fanatismo popular, sino el producto de un poder cada vez más letrado y burocrático que necesitaba definir sus fronteras. La crítica le ha reprochado agrupar fenómenos heterogéneos y minusvalorar la hostilidad social preexistente; el marco, sin embargo, se ha impuesto. Inglaterra expulsó a sus judíos en 1290 y Francia en 1306.\n\nA la vez, la religiosidad urbana produjo respuestas que la Iglesia consiguió integrar. Franciscanos y dominicos, fundados entre 1209 y 1216, predicaban en las ciudades, vivían de la limosna y ocuparon con rapidez las cátedras universitarias. Tomás de Aquino y Buenaventura fueron frailes mendicantes y profesores en París: la orden nacida para predicar a los pobres acabó administrando la alta cultura.","textEso":"La Iglesia se reformó para librarse del control de reyes y señores, y en ese pulso llegó a excomulgar a un emperador. También recuperó el derecho romano, que se estudiaba en Bolonia y sirvió para reforzar el poder de los reyes. Pero la misma sociedad que se organizaba mejor se volvió menos tolerante: se persiguió a los herejes cátaros con una cruzada, se creó la Inquisición y se impusieron a los judíos señales distintivas y expulsiones.","textBachillerato":"La reforma gregoriana buscó liberar a la Iglesia del control laico: prohibición de la investidura de obispos por reyes y señores, celibato obligatorio y afirmación de la supremacía pontificia. El enfrentamiento con el Imperio, con la humillación de Canossa como episodio simbólico, terminó en un compromiso, pero dejó establecida la idea de una autoridad espiritual independiente y superior.\n\nEn paralelo, la recuperación del derecho romano en Bolonia proporcionó a los monarcas un instrumento intelectual para fundamentar un poder público por encima de los vínculos feudales. Y la misma sociedad que se ordena mejor desarrolla mecanismos de exclusión: cruzada contra los cátaros, creación de la Inquisición pontificia, imposición de signos distintivos a judíos y musulmanes en el IV Concilio de Letrán, expulsiones. Es un proceso simultáneo, no contradictorio: el aumento de la capacidad de organizar va acompañado del aumento de la capacidad de perseguir.","callout":null},{"type":"section","title":"Los límites del crecimiento","text":"Hacia 1270 el modelo empezó a agotarse. La roturación había llegado a tierras marginales de rendimiento bajo, las herencias fragmentaban las explotaciones, la relación entre población y superficie cultivable se deterioraba y el precio del grano subía en términos reales. La gran hambruna del norte de Europa de 1315-1317, provocada por varios años de lluvias catastróficas, encontró a una población ya en el límite. La peste negra de 1348 llegaría después sobre ese terreno.\n\nConviene además situar el episodio en su escala real. Mientras Europa redescubría la moneda de oro, la China de los Song tenía ciudades de más de un millón de habitantes, imprenta de tipos móviles desde el siglo XI y papel moneda emitido por el Estado; el mundo islámico manejaba desde antes los instrumentos de crédito que Italia adoptó; y el comercio del océano Índico movía volúmenes que el Mediterráneo no alcanzaba. Lo que distingue a la Europa de estos siglos no es una superioridad técnica ni económica, sino una forma jurídica peculiar: la proliferación de corporaciones autónomas con personalidad propia —comunas, gremios, universidades, órdenes— capaces de contratar, litigar y perdurar más allá de sus miembros. Es un argumento institucional, no una jerarquía de civilizaciones.\n\nTambién quedaron fuera del reparto los de siempre. La condición campesina mejoró en libertad jurídica pero no necesariamente en nivel de vida; las mujeres trabajaban en los oficios urbanos y en algunos casos formaban gremios propios, como los de la seda en París, pero quedaron excluidas de la universidad, de las magistraturas y de la mayoría de los maestrazgos; y las minorías religiosas pasaron de tolerancia interesada a expulsión en poco más de un siglo.\n\nEl balance, sin embargo, es el de una transformación de fondo. En el año mil Europa era un mundo rural, de intercambio local y cultura monástica; en 1300 tenía ciudades con derecho propio, una red mercantil que unía Nóvgorod con Alejandría, instrumentos de crédito reutilizables, un cuerpo de juristas profesionales y una veintena de universidades. Ninguna de esas cosas desapareció con la crisis del siglo XIV: fue el marco dentro del cual se afrontó.","textEso":"A finales del siglo XIII el crecimiento se paró. Se había roturado ya la tierra mala, que rendía poco; las cosechas dejaron de aumentar mientras la población seguía creciendo, y el clima empeoró. En 1315 llegó una gran hambruna que mató a millones. Europa estaba superpoblada y desnutrida justo antes de que apareciera la peste negra, y eso explica en parte por qué fue tan devastadora.","textBachillerato":"Hacia finales del siglo XIII el modelo de crecimiento se agota. La expansión agraria había llegado a tierras marginales de bajo rendimiento, y la productividad por hectárea dejó de aumentar mientras la población seguía creciendo. Las parcelas se fragmentaban por herencia hasta dejar de ser viables, y aumentó el número de campesinos sin tierra suficiente.\n\nA eso se sumó un deterioro climático, el inicio de la Pequeña Edad de Hielo, con veranos fríos y lluviosos. La Gran Hambruna de 1315-1317 mató a millones en el norte de Europa. La lectura maltusiana clásica interpreta todo esto como un techo demográfico alcanzado; otras lecturas subrayan el peso de la extracción señorial, que impedía al campesinado capitalizar mejoras. En cualquier caso, cuando la peste negra llega en 1347 encuentra una población numerosa, mal alimentada y ya debilitada, lo que ayuda a explicar su letalidad.","callout":null},{"type":"concepts","items":[{"term":"Roturación","definition":"Puesta en cultivo de bosques, marismas y eriales. Principal fuente de alimento adicional entre los siglos XI y XIII."},{"term":"Rotación trienal","definition":"Ciclo que deja en barbecho un tercio de la tierra en vez de la mitad e introduce una siembra de primavera de leguminosas."},{"term":"Carruca","definition":"Arado pesado de vertedera con ruedas, capaz de voltear los suelos húmedos y arcillosos del norte de Europa."},{"term":"Carta de franquicia","definition":"Documento que concede a una localidad libertades, tribunal y mercado a cambio de un censo fijo. Define jurídicamente la ciudad."},{"term":"Comuna","definition":"Asociación jurada de vecinos que arranca o negocia el gobierno de la ciudad a su señor. Origen de las repúblicas urbanas italianas."},{"term":"Podestà","definition":"Magistrado forastero contratado por un año en las ciudades italianas, precisamente para que no tuviera clientela local."},{"term":"Gremio","definition":"Corporación de oficio. Escuela técnica, seguro social y monopolio a la vez: controlaba calidad, formación, precios y acceso."},{"term":"Ferias de Champaña","definition":"Ciclo de seis ferias anuales que funcionó como cámara de compensación entre Flandes e Italia durante casi dos siglos."},{"term":"Commenda","definition":"Contrato que asocia capital y trabajo viajero, reparte el beneficio y limita la pérdida al capital aportado."},{"term":"Letra de cambio","definition":"Instrumento para pagar en una plaza y cobrar en otra, en otra moneda. Permitía además ocultar el interés en el tipo de cambio."},{"term":"Usura","definition":"Cobro de cualquier cantidad por encima del principal, prohibido por el derecho canónico. Se rodeó con técnica jurídica, no se suprimió."},{"term":"Universitas","definition":"Corporación con personalidad jurídica, estatutos y jurisdicción propias. La universidad es, literalmente, un gremio de la enseñanza."},{"term":"Licentia ubique docendi","definition":"Licencia papal para enseñar en cualquier lugar de la cristiandad. Origen del reconocimiento internacional de títulos."},{"term":"Disputatio","definition":"Ejercicio público de argumentos enfrentados ante un maestro que determina. El método escolástico organiza el desacuerdo en vez de evitarlo."},{"term":"Inquisitio","definition":"Procedimiento en el que el tribunal investiga de oficio, sin acusador, con registro escrito. Innovación procesal adoptada después por la justicia civil."}]},{"type":"debates","items":[{"question":"¿Qué explica el renacimiento urbano europeo?","positions":[{"school":"Comercio de larga distancia (Pirenne)","argument":"Las ciudades nacieron del comercio: mercaderes ambulantes que se asientan junto a fortalezas y monasterios y acaban formando un núcleo con derecho propio. La burguesía es un producto del intercambio internacional."},{"school":"Crecimiento agrario y mercado comarcal","argument":"Primero hubo excedente rural y mercados locales; el comercio internacional llegó después. Muchas ciudades crecieron sobre sedes episcopales que nunca desaparecieron del todo, de modo que la continuidad pesa más que la refundación."}],"state":"La secuencia de Pirenne está invertida por la investigación posterior: el motor inicial fue agrario y local. Lo que se conserva de su aportación es haber tratado la ciudad como sujeto histórico con lógica propia y no como apéndice del mundo señorial."},{"question":"¿Hubo una «revolución comercial» europea?","positions":[{"school":"Revolución comercial (Robert S. Lopez)","argument":"Entre los siglos XI y XIII Europa creó la sociedad mercantil, la letra de cambio, la contabilidad por partida doble, el seguro y la banca, y volvió a acuñar oro. Un cambio de naturaleza, no de grado."},{"school":"Difusión desde el Mediterráneo islámico (Goitein, Udovitch)","argument":"Los documentos de la Gueniza de El Cairo muestran instrumentos equivalentes en uso mucho antes: la *suftaya*, comparable a la letra de cambio, y el *qirad*, muy próximo a la *commenda*. Europa sistematizó y escaló lo que recibió."}],"state":"Se acepta la magnitud del cambio europeo y se rechaza la idea de invención desde cero. La discusión abierta es hasta qué punto la transmisión fue directa o hubo desarrollos paralelos a partir de un fondo mediterráneo común."},{"question":"¿Se convirtió Europa en una «sociedad persecutoria»?","positions":[{"school":"Persecución construida desde arriba (R. I. Moore, 1987)","argument":"Entre 1000 y 1250 se crearon categorías estables de excluidos —herejes, judíos, leprosos, sodomitas— e instituciones permanentes para identificarlos. El motor fue un poder letrado y burocrático que necesitaba definir sus fronteras, no el fanatismo espontáneo."},{"school":"Crítica","argument":"La tesis agrupa fenómenos muy distintos bajo una sola etiqueta e infravalora la hostilidad social previa y los conflictos locales concretos que precipitaron cada episodio."}],"state":"El marco de Moore se ha impuesto como punto de partida, con matices: hoy se estudia la interacción entre la iniciativa institucional y las tensiones locales, en vez de atribuir la persecución a una sola de las dos."}]},{"type":"timeline","items":[{"date":"1075","event":"*Dictatus papae* de Gregorio VII: comienza la querella de las investiduras."},{"date":"1077","event":"Enrique IV ante Gregorio VII en Canossa."},{"date":"1086","event":"Domesday Book: el censo inglés registra más de cinco mil quinientos molinos de agua."},{"date":"c. 1088","event":"Fecha convencional de la escuela de derecho de Bolonia, fijada en 1888."},{"date":"1122","event":"Concordato de Worms: se separan jurisdicción espiritual y temporal."},{"date":"c. 1140","event":"Graciano compone el *Decreto*, base del derecho canónico clásico."},{"date":"1155","event":"*Authentica Habita*: Federico I protege a los estudiantes en camino."},{"date":"Siglos XII–XIII","event":"Ciclo de las ferias de Champaña, bisagra entre Flandes e Italia."},{"date":"1209–1216","event":"Nacen franciscanos y dominicos, órdenes de predicación urbana."},{"date":"1209–1229","event":"Cruzada albigense contra los cátaros del Languedoc."},{"date":"1215","event":"IV Concilio de Letrán: confesión anual, transustanciación y signos distintivos para judíos y musulmanes."},{"date":"1231","event":"*Parens scientiarum*: Gregorio IX consagra los privilegios de la Universidad de París."},{"date":"1252","event":"Génova y Florencia acuñan de nuevo moneda de oro; Venecia lo hará en 1284."},{"date":"1277","event":"El obispo Tempier condena 219 proposiciones enseñadas en París."},{"date":"1290","event":"Expulsión de los judíos de Inglaterra; Francia hará lo propio en 1306."}]},{"type":"sources","items":[{"author":"Gregorio VII","title":"Dictatus papae","year":"1075","kind":"primaria","note":"Veintisiete proposiciones sobre la potestad papal, incluida la de deponer emperadores."},{"author":"Administración de Guillermo I","title":"Domesday Book","year":"1086","kind":"primaria","note":"Censo fiscal de Inglaterra. Base cuantitativa para la economía rural y los molinos."},{"author":"Pedro Abelardo","title":"Sic et non","year":"c. 1120","kind":"primaria","note":"Ciento cincuenta y ocho cuestiones con autoridades contradictorias. Fija el método de la disputa escolástica."},{"author":"Graciano","title":"Concordia discordantium canonum (Decreto)","year":"c. 1140","kind":"primaria","note":"Aplica el método escolástico al derecho de la Iglesia. Base del derecho canónico clásico."},{"author":"Federico I","title":"Authentica Habita","year":"1155","kind":"primaria","note":"Protege a los estudiantes en viaje y los sustrae al tribunal local."},{"author":"Luis VII","title":"Carta de franquicia de Lorris","year":"c. 1155","kind":"primaria","note":"Modelo de fuero urbano copiado por centenares de localidades francesas."},{"author":"IV Concilio de Letrán","title":"Cánones","year":"1215","kind":"primaria","note":"Confesión anual, transustanciación y signos distintivos para judíos y musulmanes."},{"author":"Gregorio IX","title":"Parens scientiarum","year":"1231","kind":"primaria","note":"Reconoce a la Universidad de París estatutos propios tras dos años de huelga."},{"author":"Esteban Tempier","title":"Condena de 219 proposiciones","year":"1277","kind":"primaria","note":"Muestra el conflicto interno de la universidad sobre los límites entre razón y fe."},{"author":"Documentos de la Gueniza de El Cairo","title":"Correspondencia y contratos mercantiles","year":"s. XI–XIII","kind":"primaria","note":"Archivo accidental de una comunidad judía. Fuente central sobre el comercio mediterráneo islámico."},{"author":"Francesco Balducci Pegolotti","title":"La pratica della mercatura","year":"c. 1340","kind":"primaria","note":"Manual de un factor de los Bardi: pesos, monedas, aranceles y rutas hasta China."},{"author":"Henri Pirenne","title":"Las ciudades de la Edad Media","year":"1927","kind":"estudio","note":"Sitúa el origen urbano en el comercio de larga distancia. Secuencia hoy invertida, enfoque conservado."},{"author":"Lynn White Jr.","title":"Medieval Technology and Social Change","year":"1962","kind":"estudio","note":"Atribuye la transformación social a la técnica. Criticado por su cronología y su determinismo."},{"author":"Jacques Le Goff","title":"Los intelectuales en la Edad Media","year":"1957","kind":"estudio","note":"El maestro universitario como trabajador urbano y profesional del pensamiento."},{"author":"S. D. Goitein","title":"A Mediterranean Society","year":"1967-1993","kind":"estudio","note":"Reconstrucción del mundo mercantil islámico y judío a partir de la Gueniza."},{"author":"Robert S. Lopez","title":"The Commercial Revolution of the Middle Ages","year":"1971","kind":"estudio","note":"Formula la idea de revolución comercial entre los siglos X y XIII."},{"author":"Georges Duby","title":"Guerreros y campesinos","year":"1973","kind":"estudio","note":"El despegue agrario como base material de todo el proceso."},{"author":"Harold J. Berman","title":"Law and Revolution","year":"1983","kind":"estudio","note":"La querella de las investiduras como origen de la tradición jurídica occidental."},{"author":"R. I. Moore","title":"The Formation of a Persecuting Society","year":"1987","kind":"estudio","note":"La persecución sistemática como producto de un poder letrado y burocrático."}]},{"type":"images","items":[{"src":"/img/plena-edad-media/portada.jpg","alt":"Miniatura de una clase universitaria medieval: un maestro lee desde una cátedra elevada ante alumnos sentados en bancos","width":1200,"height":969,"role":"portada","caption":"Clase en la Universidad de Bolonia, miniatura de Laurentius de Voltolina, siglo XIV.","author":"Laurentius de Voltolina","title":"Liber ethicorum des Henricus de Alemannia , single sheet. Scena: Henricus de Alemannia con i suoi studenti","year":"571","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Laurentius_de_Voltolina_001.jpg"},{"src":"/img/plena-edad-media/holstentor.jpg","alt":"Puerta urbana de ladrillo con dos torres cilíndricas gemelas y frontón escalonado entre ellas","width":1200,"height":800,"role":"figura","section":1,"caption":"La Holstentor de Lübeck, cabeza de la Hansa. La puerta la paga la ciudad, no un señor: el estatuto jurídico es lo que define a la ciudad medieval.","author":"Dietmar Rabich","title":"Lübeck, Holstentor -- 2017 -- 0301","year":"2017","source":"Wikimedia Commons","license":"CC BY-SA 4.0","url":"https://commons.wikimedia.org/wiki/File:L%C3%BCbeck%2C_Holstentor_--_2017_--_0301.jpg"},{"src":"/img/plena-edad-media/marco-polo.jpg","alt":"Miniatura medieval de una caravana de jinetes y camellos avanzando por un paisaje esquemático","width":1200,"height":752,"role":"figura","section":2,"caption":"La caravana de Marco Polo en un manuscrito del Libro de las maravillas, hacia 1400. La ruta terrestre a Asia estuvo abierta mientras duró la paz mongola.","author":"Unknown author Unknown author","title":"Marco Polo traveling","year":"1324","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Marco_Polo_traveling.JPG"},{"src":"/img/plena-edad-media/chartres.jpg","alt":"Fachada de catedral gótica con dos torres desiguales, un gran rosetón central y tres portadas con estatuas columna","width":1200,"height":1400,"role":"figura","section":4,"caption":"Fachada occidental de Chartres. La catedral gótica es una obra de varias generaciones financiada por el cabildo, la ciudad y las peregrinaciones.","author":"Dcconsta","title":"Chartres cathedral (West façade)","year":"2013","source":"Wikimedia Commons","license":"CC BY-SA 3.0","url":"https://commons.wikimedia.org/wiki/File:Chartres_cathedral_(West_fa%C3%A7ade).jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'plena-edad-media'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: prehistoria
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Prehistoria y neolitización', '[{"type":"section","title":"Qué es la prehistoria y con qué se estudia","text":"La prehistoria es el periodo anterior a la escritura, y por tanto una categoría relativa: termina en momentos distintos según la región. Mesopotamia sale de ella hacia 3300 a. C.; buena parte del África subsahariana o de Oceanía, milenios después. Esa relatividad ha sido criticada porque hace del alfabetismo el criterio de entrada en la historia, con una carga eurocéntrica evidente. Muchos autores prefieren hoy hablar de «sociedades sin escritura» o usar directamente las secuencias arqueológicas.\n\nLa disciplina se apoya en fuentes materiales y en técnicas de laboratorio. La datación por radiocarbono, desarrollada por Willard Libby en 1949, permitió por primera vez fechar en términos absolutos hasta unos 50.000 años; la termoluminiscencia, el uranio-torio y el potasio-argón cubren horizontes más antiguos. La paleoecología reconstruye climas mediante polen, isótopos de oxígeno y sondeos de hielo.\n\nLa transformación más importante de las últimas dos décadas ha sido la paleogenética. Desde que Svante Pääbo secuenció el genoma neandertal en 2010, el ADN antiguo ha reescrito la historia de las migraciones humanas: ha demostrado el mestizaje entre sapiens y neandertales, ha identificado a los denisovanos a partir de un fragmento de falange, y ha revelado que la Europa actual resulta de al menos tres oleadas superpuestas —cazadores-recolectores locales, agricultores anatolios y pastores esteparios.\n\nConviene una advertencia metodológica: la conservación diferencial sesga lo que vemos. La piedra y el hueso perduran; la madera, la fibra, la piel y el discurso, no. Cualquier reconstrucción de la vida prehistórica trabaja sobre un registro incompleto y sistemáticamente inclinado hacia lo duradero.","textEso":"La prehistoria es todo el tiempo anterior a la escritura, y es casi toda la historia de la humanidad: más del 99 % del tiempo que llevamos en la Tierra. Como no hay textos, se estudia con lo que quedó enterrado: huesos, herramientas de piedra, semillas, restos de hogueras. El carbono 14 permite fechar restos orgánicos de los últimos 50.000 años, y desde hace poco el ADN antiguo cuenta además de dónde venía cada población y con quién se mezcló.","textBachillerato":"La prehistoria es el periodo anterior a la escritura, y por eso es una categoría relativa: no termina a la vez en todas partes. Mesopotamia sale de ella hacia 3300 a. C., y otras regiones milenios después. Esa definición se ha criticado porque convierte el saber escribir en la puerta de entrada a la historia, con una carga eurocéntrica clara; de ahí que hoy se prefiera hablar de sociedades sin escritura.\n\nSin textos, todo depende de las fuentes materiales y del laboratorio. El radiocarbono, desarrollado en 1949, permitió por primera vez dar fechas absolutas hasta unos 50.000 años; para horizontes más antiguos se usan el potasio-argón o el uranio-torio. El polen y los isótopos de los sondeos de hielo reconstruyen el clima. Y la paleogenética, desde que en 2010 se secuenció el genoma neandertal, ha reescrito el mapa de las migraciones humanas.","callout":"La calibración del radiocarbono corrige la variación del C-14 atmosférico. Por eso las fechas se expresan «cal BP» o «cal a. C.»: una fecha sin calibrar y otra calibrada no son comparables."},{"type":"section","title":"Evolución humana: un arbusto, no una escalera","text":"La imagen popular de una progresión lineal de simio a humano es incorrecta. La evidencia fósil dibuja un arbusto ramificado en el que varias especies de homínidos coexistieron durante largos periodos: australopitecos, parántropos, Homo habilis, Homo erectus, Homo naledi, Homo floresiensis, neandertales, denisovanos y sapiens.\n\nLos rasgos que asociamos a lo humano no aparecieron a la vez. El bipedismo es muy antiguo —las huellas de Laetoli tienen 3,6 millones de años—, mientras que el gran encefalización llegó mucho después. Las herramientas de Lomekwi, de 3,3 millones de años, son anteriores al género Homo, lo que rompe la ecuación entre fabricar útiles y ser humano.\n\nEl control del fuego fue decisivo. Richard Wrangham ha defendido en *Catching Fire* (2009) que la cocción, al externalizar parte de la digestión, permitió reducir el aparato digestivo y sostener un cerebro metabólicamente caro. La cronología exacta se discute: hay indicios en Wonderwerk hacia 1 millón de años, pero el uso sistemático solo está bien documentado desde hace unos 400.000.\n\nEl yacimiento de Atapuerca ha sido central en este debate. La Sima de los Huesos ha entregado más de 6.500 fósiles de al menos 28 individuos, un conjunto sin equivalente, y su análisis genético los sitúa en el linaje neandertal. La Gran Dolina aportó los restos de *Homo antecessor*, con marcas de corte que documentan canibalismo, probablemente de tipo nutricional.\n\nSobre los neandertales, la revisión ha sido drástica. Enterraban a sus muertos, cuidaban de individuos con lesiones incapacitantes, usaban pigmentos, fabricaban adhesivos de brea —un proceso que exige control térmico en ausencia de oxígeno— y construyeron estructuras de espeleotemas en la cueva de Bruniquel hace 176.000 años. Su desaparición como población diferenciada no fue una extinción total: entre el 1 % y el 2 % del genoma de los humanos no africanos actuales es neandertal.","textEso":"Durante mucho tiempo la evolución humana se dibujó como una fila de figuras cada vez más erguidas. Hoy sabemos que no fue una escalera, sino un arbusto con muchas ramas que convivieron. Lucy, una Australopithecus de hace 3,2 millones de años, ya caminaba de pie: primero llegó la postura erguida y mucho después el cerebro grande. Neandertales y sapiens compartieron Europa miles de años y se cruzaron: casi todos los europeos de hoy llevan un pequeño porcentaje de ADN neandertal.","textBachillerato":"La imagen de la evolución humana como una progresión lineal es falsa. Lo que muestra el registro fósil es un arbusto de especies que coexistieron: en un mismo momento podían convivir varios homínidos distintos. El bipedismo llegó primero, y Lucy lo demuestra hace 3,2 millones de años; el aumento del cerebro vino mucho más tarde y no fue constante.\n\nLos neandertales no fueron una rama torpe ni fracasada. Enterraban a sus muertos, cuidaban heridos, fabricaban adhesivos y usaban pigmentos. Convivieron con los sapiens en Europa durante milenios y hubo mestizaje, algo que solo se demostró con ADN antiguo. Por qué desaparecieron como población diferenciada sigue discutiéndose: se apunta a la competencia por recursos, al clima y a una demografía siempre al límite, probablemente a las tres cosas combinadas.","callout":null},{"type":"section","title":"Sociedades cazadoras-recolectoras del Paleolítico","text":"Durante casi toda la prehistoria, los humanos vivieron en grupos móviles de tamaño reducido que explotaban recursos estacionales. Esa movilidad no implica precariedad permanente. Los estudios etnográficos de sociedades cazadoras-recolectoras recientes, sintetizados en el influyente simposio *Man the Hunter* (1968), estimaron dedicaciones de subsistencia de entre tres y cinco horas diarias, lo que llevó a Marshall Sahlins a hablar de «la sociedad opulenta original».\n\nEsa formulación se ha matizado mucho: las poblaciones estudiadas en el siglo XX ocupaban ambientes marginales y no son análogos directos de las paleolíticas. Aun así, la evidencia paleopatológica apunta en la misma dirección: los primeros agricultores presentan, respecto a los cazadores-recolectores previos, menor estatura, más caries, más anemia y más marcadores de estrés nutricional.\n\nLa organización social era probablemente igualitaria en lo económico, con fuertes mecanismos de reparto y de nivelación. Pero el registro funerario muestra excepciones llamativas: los enterramientos de Sunguir (Rusia, c. 34.000 a. C.) incluyen individuos cubiertos con miles de cuentas de marfil que representan miles de horas de trabajo. La desigualdad no espera a la agricultura.\n\nLa división sexual del trabajo tampoco fue tan rígida como se asumió. Los análisis de restos de Wilamaya Patjxa (Perú) y las revisiones de ajuares de caza en las Américas han identificado mujeres enterradas con equipo cinegético, y el estudio de marcadores óseos de actividad muestra patrones menos dicotómicos de lo esperado.","textEso":"Durante cientos de miles de años vivimos de cazar, pescar y recolectar, en grupos pequeños que se movían siguiendo a los animales y a las estaciones. No era una vida de hambre permanente: en poblaciones parecidas estudiadas en el siglo XX, conseguir comida ocupaba menos horas al día que una jornada laboral actual. Lo que no había era manera de acumular, así que el grupo no podía crecer mucho ni quedarse quieto en un sitio.","textBachillerato":"Las sociedades del Paleolítico vivían de la caza, la pesca y la recolección, en grupos móviles de pocas decenas de personas. La movilidad no era una carencia, era la estrategia: seguir los recursos evitaba agotarlos. Los estudios sobre poblaciones cazadoras-recolectoras actuales obligaron a abandonar la idea de una vida de miseria permanente, aunque extrapolar de ellas al Paleolítico tiene límites evidentes.\n\nLa consecuencia decisiva es que sin acumulación de excedente no hay desigualdad estable ni poder heredado. El grupo se regula por reciprocidad y parentesco, y su tamaño queda limitado por lo que el territorio da cada estación. Todo lo que cambia en el Neolítico arranca de ahí: en el momento en que se puede almacenar, se puede también controlar quién reparte.","callout":"La recolección aportaba probablemente la mayor parte de las calorías en muchos entornos. La etiqueta «cazadores-recolectores» invierte, en ese sentido, el peso real de cada actividad."},{"type":"section","title":"Arte, símbolo y pensamiento","text":"El arte paleolítico europeo —Chauvet, Lascaux, Altamira, El Castillo, Tito Bustillo— constituye el corpus simbólico más antiguo conservado a gran escala. Sus temas dominantes son animales, signos geométricos y manos en negativo; las figuras humanas son escasas y a menudo esquemáticas.\n\nLas interpretaciones han cambiado con las modas teóricas. La «magia de caza» de Breuil, que veía en las pinturas un ritual propiciatorio, fue sustituida por el estructuralismo de Leroi-Gourhan, que buscaba oposiciones binarias en la distribución de las figuras, y después por lecturas chamánicas como la de David Lewis-Williams en *La mente en la caverna* (2002), basadas en la neuropsicología de los estados alterados de conciencia. Ninguna se impone hoy de forma concluyente.\n\nLa datación por uranio-torio de costras calcáreas ha alterado el marco cronológico: algunas manifestaciones de La Pasiega, Maltravieso y Ardales superarían los 64.000 años, lo que las situaría antes de la llegada de sapiens a Europa y las atribuiría a neandertales. La propuesta sigue siendo discutida metodológicamente, pero, de confirmarse, elimina el último rasgo que se reservaba en exclusiva a nuestra especie.\n\nFuera de Europa el registro es igual de antiguo: las figuras de Sulawesi y Borneo superan los 40.000 años, y en Blombos (Sudáfrica) hay grabados geométricos en ocre de hace 73.000 años. El foco europeo de los manuales refleja la historia de la investigación, no la distribución real del fenómeno.","textEso":"Hacia 40.000 años aparece el arte: bisontes y caballos en cuevas como Altamira o Chauvet, figuras talladas como la Venus de Willendorf, collares hechos con conchas traídas de muy lejos. No sabemos qué significaban, pero sí lo que demuestran: pensamiento simbólico, técnicas que se enseñaban de una generación a otra y redes de intercambio de cientos de kilómetros.","textBachillerato":"Hacia 40.000 años el registro se llena de objetos que no sirven para comer ni para cazar: pinturas en cuevas, figuras femeninas talladas, cuentas de collar, instrumentos musicales de hueso. Lo que señalan no es un despertar súbito de la inteligencia, porque hay indicios simbólicos muy anteriores, sino una intensificación: el símbolo pasa a organizar la vida social.\n\nLas interpretaciones del arte paleolítico han ido cambiando con la moda teórica: magia propiciatoria para la caza, tótems de grupo, trance chamánico, marcadores de territorio. Ninguna se puede demostrar. Lo que sí es comprobable es otra cosa, y es más útil: las conchas y los pigmentos viajaban cientos de kilómetros, así que existían redes de intercambio estables entre grupos que no se veían a diario.","callout":null},{"type":"section","title":"La neolitización: cómo y por qué","text":"Hacia el final del Pleistoceno, varias poblaciones del suroeste asiático empezaron a cultivar y a domesticar animales. El proceso fue lento —siglos de manipulación previa a la domesticación morfológica— e independiente en al menos siete focos mundiales: Creciente Fértil, China (mijo y arroz), Mesoamérica (maíz), Andes (patata, quinoa), Nueva Guinea (taro), África occidental (sorgo) y este de Norteamérica.\n\nSobre las causas se han propuesto tres grandes familias de explicación. Gordon Childe defendió en los años treinta la «hipótesis del oasis»: la desecación posglacial habría concentrado a humanos, plantas y animales en torno a los puntos de agua. Lewis Binford y Kent Flannery reformularon el problema en clave demográfica: la presión de población en zonas marginales habría obligado a intensificar la producción. Una tercera línea, de Jacques Cauvin en *Naissance des divinités, naissance de l''agriculture* (1994), invierte la causalidad y sitúa primero un cambio simbólico y religioso.\n\nGöbekli Tepe, excavado por Klaus Schmidt desde 1995, es la pieza que más ha forzado la revisión. Sus recintos con pilares en T de hasta cinco metros y relieves de animales datan de c. 9500 a. C. y fueron levantados por poblaciones que aún no practicaban agricultura plena. La construcción monumental precede, aquí, a la economía agrícola, y no al revés.\n\nLas consecuencias de la neolitización fueron ambivalentes. Aumentó la capacidad de carga demográfica y permitió el excedente, el almacenamiento y, con el tiempo, la desigualdad institucionalizada y el Estado. Al mismo tiempo empeoró la dieta media, aumentó la carga de trabajo, favoreció las zoonosis por convivencia con el ganado y aumentó la vulnerabilidad a las malas cosechas. Jared Diamond la llamó provocativamente «el peor error de la historia de la especie humana».\n\nEn Europa el proceso fue sobre todo migratorio, no de difusión de ideas. La paleogenética muestra que los agricultores anatolios se expandieron físicamente por el continente entre 7000 y 5500 a. C., mezclándose en proporciones variables con los cazadores-recolectores locales, y que un tercer componente —los pastores de la estepa póntica asociados a la cultura Yamnaya— llegó hacia 3000 a. C. y transformó de nuevo el paisaje genético y probablemente lingüístico de Europa.","textEso":"Hacia 8500 a. C., en el Creciente Fértil, varias poblaciones empiezan a sembrar trigo y cebada y a criar ovejas y cabras. No fue un invento afortunado y sin más: los primeros agricultores trabajaban más horas, comían una dieta más pobre y enfermaban más que los cazadores. A cambio, de la misma tierra salía más comida, así que podía vivir más gente junta. De ahí salen los poblados permanentes, la propiedad, las diferencias de riqueza y, al final, las ciudades.","textBachillerato":"La neolitización es la adopción de la agricultura y la ganadería, y ocurrió de forma independiente en al menos siete focos del mundo. En el Creciente Fértil empieza hacia 8500 a. C. con trigo, cebada, oveja y cabra. No fue un descubrimiento repentino, sino siglos de manejo cada vez más intenso de plantas y animales que ya se usaban.\n\nPor qué se dio el paso es la pregunta difícil, porque a corto plazo se vivía peor: los esqueletos de los primeros agricultores muestran más caries, más anemia, menos estatura y más enfermedades infecciosas por vivir junto a animales y en poblados densos. La explicación más sólida combina el clima estable del Holoceno, la presión demográfica y el hecho de que la agricultura da más calorías por hectárea aunque cueste más trabajo por caloría. Lo que siguió fue irreversible: excedente almacenable, propiedad, jerarquía.","callout":"La domesticación deja huellas morfológicas: espigas que no se disgregan solas, semillas más grandes, cuernos reducidos. Esos cambios tardan siglos en fijarse, así que la frontera entre recolectar y cultivar es un gradiente, no una línea."},{"type":"section","title":"Megalitismo, metalurgia y el umbral de la historia","text":"Entre el V y el III milenio a. C., la fachada atlántica europea levantó dólmenes, menhires, alineamientos y grandes tumbas de corredor. Newgrange, Stonehenge y el conjunto de Antequera implican planificación, movilización de trabajo y conocimientos astronómicos aplicados: varios monumentos están orientados a los solsticios.\n\nLa datación por radiocarbono desmontó la explicación difusionista clásica, que hacía derivar el megalitismo europeo del Mediterráneo oriental. Colin Renfrew mostró en *Before Civilization* (1973) que los megalitos atlánticos son anteriores a las pirámides egipcias, lo que obligó a reconocer desarrollos autónomos y a abandonar el modelo de una civilización que irradia hacia periferias pasivas.\n\nLa metalurgia introdujo un factor nuevo. El cobre primero y el bronce después —aleación con estaño, escaso y de distribución muy desigual— exigieron redes de intercambio de larga distancia y favorecieron a las élites que las controlaban. El ajuar del llamado «arquero de Amesbury», con origen isotópico centroeuropeo y enterrado cerca de Stonehenge, ilustra esa movilidad.\n\nEl final convencional de la prehistoria llega con la escritura, hacia 3300 a. C. en Uruk. Es un corte útil pero arbitrario: no cambia nada en la vida de la mayoría de la población, y a menudo separa artificialmente procesos continuos. Conviene tratarlo como una frontera documental, no como un salto civilizatorio.","textEso":"Con la agricultura llegan las primeras obras colectivas enormes: los dólmenes y los círculos de piedra del Atlántico, Stonehenge entre ellos, que exigían organizar a cientos de personas durante generaciones. Después se aprende a fundir metal, primero cobre y luego bronce, más duro y mejor para armas y herramientas. Cuando hacia 3300 a. C. aparecen la escritura y el bronce en Mesopotamia, se cierra por convención la prehistoria.","textBachillerato":"El Neolítico europeo deja monumentos que no se explican por necesidad práctica: dólmenes, túmulos y círculos de piedra desde Portugal hasta Escandinavia. Stonehenge se construyó en fases a lo largo de más de mil años y mover sus bloques exigía coordinar a cientos de personas. Construir así supone autoridad capaz de movilizar trabajo, y una memoria colectiva que mantiene el proyecto durante generaciones.\n\nLa metalurgia llega después: primero cobre, blando y más de prestigio que de uso, y luego bronce, una aleación con estaño que sí mejora armas y herramientas. El estaño escaseaba y eso creó rutas comerciales de largo alcance y élites que las controlaban. Cuando hacia 3300 a. C. coinciden bronce y escritura en Mesopotamia se cierra la prehistoria, pero conviene recordar que ese límite es una convención administrativa, no un cambio en la vida de la gente.","callout":null},{"type":"concepts","items":[{"term":"Homínido","definition":"Miembro de la familia Hominidae. En uso corriente, los ancestros y parientes extintos del linaje humano."},{"term":"Industria lítica","definition":"Conjunto de útiles de piedra tallada característico de una tradición técnica (olduvayense, achelense, musteriense)."},{"term":"Calibración","definition":"Corrección de las fechas de radiocarbono según la variación del C-14 atmosférico. Fechas «cal BP» o «cal a. C.»."},{"term":"Paleogenética","definition":"Estudio del ADN antiguo. Ha reescrito la historia de las migraciones y demostrado el mestizaje entre especies humanas."},{"term":"Neolitización","definition":"Proceso de adopción de agricultura, ganadería, cerámica y sedentarismo. Gradual y con focos independientes."},{"term":"Domesticación","definition":"Modificación genética y morfológica de especies por selección humana sostenida durante generaciones."},{"term":"Creciente Fértil","definition":"Arco entre el Levante, Anatolia y Mesopotamia donde se documenta el primer foco de domesticación."},{"term":"Megalitismo","definition":"Tradición constructiva con grandes bloques de piedra en la Europa atlántica del V–III milenio a. C."},{"term":"Yamnaya","definition":"Cultura pastoril de la estepa póntica cuya expansión hacia 3000 a. C. transformó la genética y probablemente la lengua de Europa."},{"term":"Zoonosis","definition":"Enfermedad transmitida de animales a humanos. Su frecuencia aumentó con la convivencia ganadera del Neolítico."}]},{"type":"debates","items":[{"question":"¿Por qué se adoptó la agricultura si empeoró la salud de quienes la practicaban?","positions":[{"school":"Explicación climática (Childe, años 1930)","argument":"La desecación posglacial habría concentrado a humanos, plantas y animales en torno a oasis, forzando una convivencia que desembocó en domesticación. La agricultura sería una respuesta adaptativa a la escasez."},{"school":"Explicación demográfica (Binford, Flannery)","argument":"El crecimiento de población en zonas marginales, tras la ocupación de los mejores territorios, obligó a intensificar la obtención de alimento. La agricultura sería una salida forzada, no una mejora elegida."},{"school":"Explicación simbólica (Cauvin, 1994)","argument":"Un cambio previo en la mentalidad y en las prácticas rituales habría creado las condiciones sociales del sedentarismo. Göbekli Tepe, monumental y preagrícola, apoyaría esta secuencia."}],"state":"No hay una explicación única aceptada. La investigación actual tiende a modelos multicausales y regionales: el peso del clima, la demografía y la religión varía según el foco de domesticación, y el proceso se reconoce mucho más lento y reversible de lo que se creía."},{"question":"¿Se difundió la agricultura en Europa por migración o por adopción de ideas?","positions":[{"school":"Difusión cultural","argument":"Las poblaciones europeas de cazadores-recolectores habrían adoptado técnicas agrícolas por contacto e imitación, sin sustitución poblacional significativa."},{"school":"Difusión démica (Ammerman y Cavalli-Sforza; paleogenética)","argument":"La expansión fue de personas: agricultores procedentes de Anatolia se desplazaron por el continente entre 7000 y 5500 a. C. El ADN antiguo muestra un reemplazo poblacional sustancial, con mezcla variable según regiones."}],"state":"La paleogenética ha resuelto el debate mayoritariamente a favor de la migración, aunque con matices regionales importantes: en el Báltico y en zonas atlánticas la continuidad de los cazadores-recolectores locales fue mayor."},{"question":"¿Produjeron los neandertales arte simbólico?","positions":[{"school":"Atribución neandertal (Hoffmann et al., 2018)","argument":"Las dataciones por uranio-torio de costras sobre pinturas de La Pasiega, Maltravieso y Ardales superan los 64.000 años, antes de la llegada de sapiens a Europa. Sumadas a los pigmentos, adornos y estructuras de Bruniquel, indicarían capacidad simbólica plena."},{"school":"Escepticismo metodológico (White et al., 2020)","argument":"La datación de costras calcáreas puede sobrestimar la edad por contaminación y por sistemas abiertos al agua. Las fechas no datan el pigmento, sino el carbonato depositado sobre él."}],"state":"La discusión sigue abierta y es sobre todo técnica. La tendencia general de la disciplina, sin embargo, ha sido reducir la lista de capacidades exclusivamente sapiens: el debate ya no es si los neandertales eran simbólicos, sino en qué grado y con qué cronología."}]},{"type":"timeline","items":[{"date":"c. 3,3 M a. C.","event":"Herramientas líticas de Lomekwi (Kenia), anteriores al género Homo."},{"date":"c. 1,9 M a. C.","event":"Homo erectus: mayor capacidad craneal, bifaces achelenses y primeras salidas de África."},{"date":"c. 400.000 a. C.","event":"Uso controlado del fuego bien documentado; Sima de los Huesos (Atapuerca)."},{"date":"c. 300.000 a. C.","event":"Restos de Homo sapiens en Jebel Irhoud (Marruecos)."},{"date":"c. 45.000 a. C.","event":"Sapiens en Europa; coexistencia con neandertales durante milenios."},{"date":"c. 40.000 a. C.","event":"Arte figurativo en Chauvet, El Castillo y Sulawesi."},{"date":"c. 40.000 a. C.","event":"Extinción de los neandertales como población diferenciada."},{"date":"c. 11.600 a. C.","event":"Fin del Younger Dryas: comienza el Holoceno, cálido y estable."},{"date":"c. 9500 a. C.","event":"Göbekli Tepe: santuarios monumentales de sociedades aún no agrícolas."},{"date":"c. 8500 a. C.","event":"Domesticación de trigo, cebada, oveja y cabra en el Creciente Fértil."},{"date":"c. 7000 a. C.","event":"Çatalhöyük: gran poblado agrícola en Anatolia."},{"date":"c. 5600 a. C.","event":"La agricultura alcanza la península ibérica por vía mediterránea."},{"date":"c. 4500–2500 a. C.","event":"Megalitismo atlántico europeo: Stonehenge, Newgrange, Antequera."},{"date":"c. 3300 a. C.","event":"Metalurgia del bronce y primeras escrituras: fin convencional de la prehistoria."}]},{"type":"sources","items":[{"author":"V. Gordon Childe","title":"Man Makes Himself","year":"1936","kind":"estudio","note":"Formula la «revolución neolítica» y la hipótesis del oasis. Referencia histórica del debate."},{"author":"Richard B. Lee e Irven DeVore (eds.)","title":"Man the Hunter","year":"1968","kind":"estudio","note":"Simposio que reformuló la imagen de las sociedades cazadoras-recolectoras."},{"author":"Colin Renfrew","title":"Before Civilization: The Radiocarbon Revolution and Prehistoric Europe","year":"1973","kind":"estudio","note":"Demuestra la anterioridad del megalitismo atlántico y liquida el difusionismo clásico."},{"author":"Jacques Cauvin","title":"Naissance des divinités, naissance de l''agriculture","year":"1994","kind":"estudio","note":"Defiende la primacía del cambio simbólico sobre el económico."},{"author":"David Lewis-Williams","title":"The Mind in the Cave","year":"2002","kind":"estudio","note":"Interpretación neuropsicológica y chamánica del arte paleolítico."},{"author":"Richard Wrangham","title":"Catching Fire: How Cooking Made Us Human","year":"2009","kind":"estudio","note":"La cocción como motor de la encefalización."},{"author":"Svante Pääbo","title":"Neanderthal Man: In Search of Lost Genomes","year":"2014","kind":"estudio","note":"Relato de primera mano de la secuenciación del genoma neandertal."},{"author":"David Reich","title":"Who We Are and How We Got Here","year":"2018","kind":"estudio","note":"Síntesis del impacto del ADN antiguo sobre la historia de las migraciones."},{"author":"James C. Scott","title":"Against the Grain: A Deep History of the Earliest States","year":"2017","kind":"estudio","note":"Cuestiona el relato progresista de la neolitización y del Estado temprano."},{"author":"Klaus Schmidt","title":"Sie bauten die ersten Tempel","year":"2006","kind":"estudio","note":"Excavación e interpretación de Göbekli Tepe por su director."}]},{"type":"images","items":[{"src":"/img/prehistoria/portada.jpg","alt":"Pintura rupestre de Lascaux con caballos y bóvidos trazados en ocre y negro sobre la roca","width":1200,"height":787,"role":"portada","caption":"Las pinturas de Lascaux, en la Dordoña, tienen unos 17.000 años.","author":"EU","title":"Lascaux painting","year":"2006","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Lascaux_painting.jpg"},{"src":"/img/prehistoria/lucy.jpg","alt":"Esqueleto fosil parcial de un homínido bípedo montado sobre fondo negro, con pelvis y fémur completos","width":1200,"height":2896,"role":"figura","section":1,"caption":"Reconstrucción del esqueleto de Lucy, Australopithecus afarensis de hace 3,2 millones de años. La pelvis demuestra que caminaba erguida mucho antes de que el cerebro creciera.","author":"120","title":"Lucy blackbg","year":"2007","source":"Wikimedia Commons","license":"CC BY 2.5","url":"https://commons.wikimedia.org/wiki/File:Lucy_blackbg.jpg"},{"src":"/img/prehistoria/altamira.jpg","alt":"Bisonte pintado en ocre rojo y negro sobre la roca, con el cuerpo replegado y aprovechando el relieve natural","width":1200,"height":759,"role":"figura","section":3,"caption":"Bisonte del techo de Altamira, en Cantabria. El pintor usó los bultos de la roca como volumen del animal.","author":"unknown prehistoric artist","title":"Altamira, bison","year":"2009","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Altamira%2C_bison.jpg"},{"src":"/img/prehistoria/stonehenge.jpg","alt":"Círculo de grandes bloques verticales de piedra con dinteles horizontales encima, sobre una llanura de hierba","width":1200,"height":900,"role":"figura","section":5,"caption":"Stonehenge, levantado en varias fases entre 3000 y 1600 a. C. Mover los bloques exigía coordinar a cientos de personas durante generaciones.","author":"garethwiscombe","title":"Stonehenge2007 07 30","year":"2007","source":"Wikimedia Commons","license":"CC BY 2.0","url":"https://commons.wikimedia.org/wiki/File:Stonehenge2007_07_30.jpg"}]}]'::jsonb, 0, true
from public.topics where slug = 'prehistoria'
on conflict (topic_id, position) do update set
  title = excluded.title, body = excluded.body, published = excluded.published;

-- Lección: reforma
insert into public.lessons (topic_id, title, body, position, published)
select id, 'Reforma, Contrarreforma y guerras de religión', '[{"type":"section","title":"Qué pedía Lutero y qué no","text":"El detonante fue una operación financiera. Alberto de Brandeburgo quería acumular el arzobispado de Maguncia con otras sedes, lo que exigía una dispensa cara; se endeudó con la banca Fugger y obtuvo del papa el derecho a predicar en sus territorios una indulgencia para la basílica de San Pedro, con la mitad de lo recaudado destinada a saldar su deuda. El dominico Johann Tetzel la predicó con métodos comerciales agresivos. Lutero, profesor de teología en Wittenberg, reaccionó contra esa predicación.\n\nEl 31 de octubre de 1517 envió las noventa y cinco tesis al propio Alberto en una carta que se conserva. La escena de las tesis clavadas en la puerta de la iglesia del castillo no aparece en ningún texto de Lutero: la cuenta Melanchthon en 1546, después de su muerte. Puede haber ocurrido —era la forma habitual de convocar una disputa universitaria— pero no está documentada, y el gesto fundacional de la Reforma es, con toda probabilidad, un recuerdo posterior.\n\nEl contenido inicial es moderado. Las tesis no niegan el purgatorio ni la autoridad papal: sostienen que la indulgencia no puede sustituir al arrepentimiento interior y que vender la remisión de penas engaña a los fieles. Lutero pedía una discusión académica, y en su carta al arzobispo daba por supuesto que este ignoraba los abusos de sus predicadores.\n\nLa radicalización llegó por el propio proceso. En la disputa de Leipzig de 1519, presionado por Johann Eck, Lutero admitió que también los concilios podían errar, lo que dejaba a la Escritura como única autoridad final. En 1520 publicó tres tratados que sí eran revolucionarios: *A la nobleza cristiana de la nación alemana* apelaba a los príncipes para reformar la Iglesia y negaba la distinción entre estado clerical y laico; *La cautividad babilónica* reducía los sacramentos y negaba la transustanciación; *La libertad del cristiano* formulaba la justificación por la fe. Ese mismo año llegó la bula *Exsurge Domine*, y en 1521, la excomunión y la comparecencia ante Carlos V en la dieta de Worms.\n\nLas tres fórmulas que resumen su teología —solo la fe, solo la Escritura, solo la gracia— tienen consecuencias institucionales inmediatas. Si la salvación no depende de las obras ni de la mediación sacramental, sobra buena parte del aparato eclesiástico; si la Escritura es la única autoridad, hace falta que la gente pueda leerla, y de ahí la traducción alemana que Lutero emprendió refugiado en Wartburgo y que fijó de paso la lengua literaria alemana.","textEso":null,"textBachillerato":null,"callout":"La escena de las tesis clavadas en la puerta la relata Melanchthon en 1546, después de la muerte de Lutero. Lo documentado es la carta al arzobispo de Maguncia. El gesto fundacional de la Reforma es probablemente un recuerdo posterior."},{"type":"section","title":"Por qué prendió: imprenta, príncipes y agravios","text":"Wyclif y Hus habían sostenido tesis comparables un siglo antes, y el segundo terminó en la hoguera. La diferencia decisiva es de comunicación. Lutero escribió en alemán, breve y polémico, en opúsculos de pocas hojas y precio bajo, ilustrados con grabados para quien no sabía leer. Andrew Pettegree ha calculado que cerca de un tercio de todos los libros impresos en alemán entre 1518 y 1525 salieron de su pluma: es el primer autor superventas de la historia europea y el primer movimiento político que se organiza mediante un mercado editorial.\n\nLa segunda condición fue política. El Imperio no era una monarquía centralizada sino un mosaico de príncipes, ciudades libres y obispados con intereses propios. Federico el Sabio de Sajonia protegió a Lutero sin compartir del todo sus tesis, porque un profesor famoso daba prestigio a su universidad y porque las apelaciones a Roma erosionaban su jurisdicción. Muchos príncipes tenían agravios acumulados contra la fiscalidad pontificia, y la Reforma ofrecía además un incentivo material inmediato: secularizar los bienes eclesiásticos de sus territorios. Carlos V, que sí quería reprimirla, estuvo ocupado durante décadas con Francia, con el Mediterráneo otomano y con el avance turco sobre Hungría y Viena.\n\nLa tercera fue urbana. Bernd Moeller mostró que la Reforma triunfó primero en las ciudades libres del Imperio, donde encajaba con una tradición de autogobierno comunal: la elección del predicador por la comunidad, la administración local de la caridad y el control ciudadano sobre el clero eran demandas anteriores a Lutero que su teología legitimaba. Peter Blickle amplió el argumento al campo y habló de una «reforma comunal», protagonizada por comunidades campesinas y urbanas que leyeron el evangelio como fundamento de sus derechos.\n\nConviene por eso desconfiar del relato del monje solitario. La Reforma prendió porque conectó una crítica teológica con agravios fiscales, con ambiciones territoriales, con una tradición de autogobierno local y con una tecnología de difusión que ninguno de sus predecesores había tenido.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"1525: el límite social de la Reforma","text":"La reforma comunal se puso a prueba en 1524-1525. Decenas de miles de campesinos del sur y el centro de Alemania se levantaron contra las cargas señoriales, y su programa más difundido, los Doce Artículos de Memmingen, argumentaba con citas bíblicas: reclamaba elegir al párroco, suprimir el diezmo menor, abolir la servidumbre porque Cristo redimió a todos por igual, y recuperar el uso de bosques y aguas comunales. Fue uno de los primeros textos europeos que formula derechos colectivos y se imprimió en unas veinticinco ediciones en dos meses.\n\nLutero respondió primero con una exhortación a la paz que repartía culpas y después, cuando la revuelta se extendió, con un panfleto de una violencia extrema, *Contra las hordas asesinas y ladronas de campesinos*, en el que llamaba a los príncipes a matar sin misericordia. La represión causó entre setenta mil y cien mil muertos.\n\nLas consecuencias fueron decisivas y de largo alcance. La Reforma dejó de ser un movimiento comunal y pasó a ser un asunto de príncipes y magistrados: la llamada reforma magisterial, en la que la autoridad civil organiza la iglesia territorial, nombra a los pastores y disciplina a los fieles. El campesinado alemán quedó desmovilizado durante siglos. Y quienes mantuvieron la lectura radical del evangelio —bautismo solo de adultos, comunidad de bienes, separación de la iglesia respecto del Estado, a menudo negativa a jurar y a portar armas— quedaron fuera de la ley para católicos y protestantes por igual.\n\nEsos radicales, agrupados bajo la etiqueta genérica de anabaptistas, se dieron en 1527 una confesión propia en Schleitheim que optaba por la separación pacífica del mundo. El episodio que marcó su imagen fue el opuesto: en 1534-1535 un grupo milenarista tomó Münster, proclamó la nueva Jerusalén, impuso la comunidad de bienes y la poligamia y resistió un asedio hasta ser aniquilado. Münster sirvió durante siglos como argumento para justificar la persecución de todo el movimiento, incluidas sus ramas pacifistas, de las que descienden menonitas, huteritas y amish.","textEso":null,"textBachillerato":null,"callout":"Los Doce Artículos de Memmingen piden abolir la servidumbre porque Cristo redimió a todos por igual. La Reforma dio a los campesinos un lenguaje para formular derechos; Lutero se alineó con quienes los aplastaron."},{"type":"section","title":"Las otras reformas","text":"El protestantismo se fragmentó desde el principio, y no por accidente: si la Escritura es la única autoridad, no hay instancia que zanje las lecturas divergentes. En Zúrich, Ulrico Zuinglio impulsó desde 1519 una reforma más radical en materia de imágenes y de culto, sostenida por el consejo municipal. El coloquio de Marburgo de 1529 reunió a Lutero y a Zuinglio para unificar posiciones ante la amenaza imperial: acordaron catorce de los quince artículos y se rompieron en el decimoquinto, la presencia real de Cristo en la eucaristía. La Reforma nació incapaz de unificarse.\n\nJuan Calvino dio al movimiento su forma más exportable. La *Institución de la religión cristiana*, publicada en 1536 y ampliada hasta 1559, ofrecía un sistema teológico completo y ordenado, con la predestinación como consecuencia lógica de la soberanía absoluta de Dios: la salvación no depende en absoluto del mérito humano. En Ginebra organizó desde 1541 una iglesia con pastores, doctores, ancianos y diáconos y un consistorio que vigilaba la conducta de los ciudadanos. La ejecución de Miguel Servet en 1553 por negar la Trinidad mostró que la tolerancia no formaba parte del programa de ninguno de los bandos.\n\nEl calvinismo se difundió por Francia, Escocia, los Países Bajos, partes de Alemania y Hungría, y con él una estructura eclesiástica de sínodos y consistorios que podía funcionar sin apoyo del príncipe e incluso contra él. Esa autonomía organizativa explica su papel en las guerras civiles francesas y en la revuelta neerlandesa.\n\nInglaterra siguió un camino distinto. La ruptura de Enrique VIII en 1534 fue dinástica y jurisdiccional antes que teológica: el Acta de Supremacía lo hizo cabeza de la Iglesia de Inglaterra para resolver su sucesión, y la disolución de los monasterios entre 1536 y 1541 transfirió a la corona y a la nobleza un patrimonio inmenso, creando un grupo social con interés material en que la ruptura no se revirtiera. El contenido doctrinal llegó después, con Eduardo VI, se revirtió con María I y se estabilizó en 1559 en una fórmula deliberadamente ambigua que dejó dentro a sensibilidades muy distintas y fuera a católicos y a puritanos.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"¿Contrarreforma o Reforma católica?","text":"El término «Contrarreforma» lo acuñó la historiografía protestante del siglo XIX y describe la respuesta católica como pura reacción. Hubert Jedin propuso en 1946 distinguir dos procesos: una reforma católica de impulso interno, con raíces anteriores a 1517 —la observancia en las órdenes religiosas, el humanismo cristiano, la reforma española de Cisneros, los oratorios italianos—, y una contrarreforma propiamente dicha, de combate contra el protestantismo. La distinción se ha impuesto, con la advertencia de que ambos procesos se entrelazan tanto que separarlos es un ejercicio analítico y no cronológico.\n\nEl Concilio de Trento, reunido en tres periodos entre 1545 y 1563, hizo dos cosas. En doctrina cerró toda posibilidad de acuerdo: reafirmó la justificación por fe y obras, los siete sacramentos, la transustanciación, el purgatorio, el culto a los santos, la tradición junto a la Escritura como fuente de revelación y la Vulgata como texto oficial. En disciplina fue mucho más innovador de lo que suele recordarse: obligó a los obispos a residir en sus diócesis, creó los seminarios para formar al clero, impuso el registro sistemático de bautismos y matrimonios y reguló la predicación y la catequesis.\n\nEse aparato disciplinar necesitaba instrumentos. La Inquisición romana se reorganizó en 1542, el primer Índice de libros prohibidos se publicó en 1559 y la censura previa se generalizó en los territorios católicos. La Compañía de Jesús, aprobada en 1540, aportó una orden móvil, sin coro ni hábito propio, con cuarto voto de obediencia al papa, especializada en educación y en misión: sus colegios formaron a las élites católicas europeas durante dos siglos, y sus misioneros llegaron a la India, Japón, China y América.\n\nLa cultura fue también instrumento. El decreto tridentino sobre las imágenes de 1563 reafirmó su valor didáctico frente al iconoclasmo protestante y exigió decoro y claridad; de ahí arranca buena parte de la estética barroca, concebida para conmover y persuadir a un público amplio. Es un uso deliberadamente propagandístico del arte, y funciona.\n\nJunto a la disciplina hubo renovación espiritual genuina: Teresa de Ávila y Juan de la Cruz, los capuchinos, las ursulinas dedicadas a la educación de niñas, la extensión de la confesión individual y de la dirección espiritual. Reducir todo el catolicismo del periodo a represión es tan parcial como reducir la Reforma a Lutero.","textEso":null,"textBachillerato":null,"callout":null},{"type":"section","title":"Guerras, paces y confesionalización","text":"La primera solución fue territorial. La paz de Augsburgo de 1555 estableció que cada príncipe del Imperio fijaba la confesión de su territorio y que los súbditos disconformes podían emigrar; el principio se resumiría después en la fórmula *cuius regio, eius religio*. Reconocía solo el catolicismo y la confesión luterana de Augsburgo, dejando fuera al calvinismo, que crecía. Fue una tregua con fecha de caducidad incorporada.\n\nFrancia se desangró en ocho guerras civiles entre 1562 y 1598, con la matanza de San Bartolomé de 1572 —varios miles de hugonotes asesinados en París y en provincias— como episodio más conocido. El conflicto terminó cuando Enrique de Navarra se convirtió al catolicismo para acceder al trono y promulgó en 1598 el Edicto de Nantes, que concedía a los protestantes libertad de conciencia, culto restringido y plazas de seguridad. Fue tolerancia por agotamiento, no por principio, y sería revocada en 1685.\n\nEn los Países Bajos, la revuelta contra Felipe II combinó desde 1568 defensa de privilegios locales, fiscalidad y calvinismo, y terminó ochenta años después con la independencia de las siete provincias del norte. Y la guerra de los Treinta Años, iniciada en 1618 en Bohemia como conflicto confesional, acabó siendo una guerra europea de hegemonía en la que la Francia católica financió y después combatió junto a los príncipes protestantes contra los Habsburgo. El coste demográfico en el Imperio fue devastador: se estima una pérdida en torno al veinte por ciento de la población total, con regiones enteras por encima del cincuenta por ciento.\n\nLa paz de Westfalia de 1648 añadió el calvinismo a las confesiones reconocidas, fijó 1624 como año normativo para las posesiones eclesiásticas y consagró la práctica de resolver los conflictos europeos en congresos multilaterales. Conviene, eso sí, desconfiar del relato que la presenta como acta de nacimiento de la soberanía estatal moderna: Andreas Osiander mostró en 2001 que esa lectura es una construcción del siglo XIX proyectada hacia atrás, y que los tratados no contienen nada parecido a una doctrina general de soberanía ni de no injerencia.\n\nEl efecto de fondo lo describe la tesis de la confesionalización, formulada por Wolfgang Reinhard y Heinz Schilling: la construcción de identidades confesionales nítidas y la construcción del Estado moderno fueron el mismo proceso. Catequesis obligatoria, escuelas, registros parroquiales, visitas de inspección, control de la moral y del matrimonio, expulsión de los disidentes: católicos, luteranos y calvinistas hicieron lo mismo con instrumentos casi idénticos, y en todos los casos el resultado fue una población más alfabetizada, más vigilada y más encuadrada.\n\nDe ahí arranca la discusión económica más famosa del periodo. Max Weber propuso en 1904-1905 que la ética del calvinismo —vocación profesional, ascetismo intramundano, inquietud ante la incertidumbre de la salvación— favoreció la acumulación capitalista. La objeción moderna más eficaz es de Sascha Becker y Ludger Woessmann, que en 2009 midieron con datos de la Prusia del siglo XIX la distancia de cada comarca a Wittenberg y concluyeron que la ventaja económica protestante se explica por la alfabetización derivada de la obligación de leer la Biblia, no por una ética específica. La conexión entre religión y economía se mantiene; el mecanismo propuesto cambia.","textEso":null,"textBachillerato":null,"callout":"Westfalia no inventó la soberanía estatal. Esa lectura es una retroproyección del siglo XIX: los tratados no contienen doctrina alguna de soberanía ni de no injerencia."},{"type":"concepts","items":[{"term":"Indulgencia","definition":"Remisión de la pena temporal por el pecado. Su predicación comercial en 1517 fue el detonante de la protesta de Lutero."},{"term":"Sola scriptura","definition":"Principio según el cual la Escritura es la única autoridad final en materia de fe. Al no haber árbitro, hace inevitable la fragmentación."},{"term":"Justificación por la fe","definition":"La salvación se recibe por gracia mediante la fe, no por las obras. Priva de fundamento a buena parte de la mediación sacramental."},{"term":"Flugschrift","definition":"Opúsculo impreso, breve y barato, a menudo ilustrado. Instrumento de difusión que convirtió a Lutero en el primer autor superventas."},{"term":"Reforma comunal","definition":"Lectura de Blickle: la Reforma como movimiento de comunidades urbanas y campesinas que reclaman autogobierno, derrotado en 1525."},{"term":"Reforma magisterial","definition":"Modelo posterior a 1525 en el que la autoridad civil organiza la iglesia territorial, nombra pastores y disciplina a los fieles."},{"term":"Anabaptismo","definition":"Corriente radical partidaria del bautismo de adultos y de la separación entre iglesia y Estado. Perseguida por católicos y protestantes."},{"term":"Predestinación","definition":"Doctrina calvinista: la salvación depende únicamente del decreto divino, no del mérito humano. Consecuencia de la soberanía absoluta de Dios."},{"term":"Consistorio","definition":"Órgano ginebrino de pastores y ancianos encargado de vigilar la conducta de los ciudadanos. Modelo de disciplina eclesiástica calvinista."},{"term":"Acta de Supremacía","definition":"Ley de 1534 que hace al rey de Inglaterra cabeza de su iglesia. Ruptura jurisdiccional y dinástica antes que teológica."},{"term":"Concilio de Trento","definition":"Asamblea de 1545-1563. Cierra la doctrina frente al protestantismo y crea seminarios, residencia episcopal y registros parroquiales."},{"term":"Cuius regio, eius religio","definition":"Principio de Augsburgo (1555): el príncipe fija la confesión de su territorio. Dejaba fuera al calvinismo, que seguía creciendo."},{"term":"Confesionalización","definition":"Tesis de Reinhard y Schilling: construir identidad confesional y construir Estado moderno fueron un mismo proceso disciplinar."},{"term":"Año normativo","definition":"Fecha de referencia fijada en Westfalia —1624— para determinar la titularidad de los bienes eclesiásticos en el Imperio."}]},{"type":"debates","items":[{"question":"¿Contrarreforma o Reforma católica?","positions":[{"school":"Contrarreforma (historiografía protestante del siglo XIX)","argument":"La respuesta católica fue esencialmente reacción: Trento, Inquisición romana, Índice y Compañía de Jesús se explican como maquinaria de combate contra el protestantismo."},{"school":"Dos procesos (Hubert Jedin, 1946)","argument":"Existía una reforma católica de impulso interno anterior a 1517 —observancia religiosa, humanismo cristiano, reforma española, oratorios italianos— sobre la que después se superpuso la reacción antiprotestante."}],"state":"La distinción de Jedin es hoy la norma, con la advertencia de que los dos procesos se entrelazan tanto que separarlos es un recurso analítico y no una secuencia cronológica limpia."},{"question":"¿Fue la Reforma un movimiento de príncipes o de comunidades?","positions":[{"school":"Reforma comunal (Moeller, Blickle)","argument":"Triunfó primero en ciudades libres y comunidades rurales con tradición de autogobierno, que reclamaban elegir a su predicador y administrar la caridad. Los Doce Artículos de 1525 son su programa."},{"school":"Reforma de príncipes","argument":"Sin la protección de Federico el Sabio y sin el interés de los príncipes en secularizar bienes eclesiásticos y recortar la jurisdicción romana, el movimiento habría terminado como el de Hus."}],"state":"Se acepta que ambas dimensiones existieron y que 1525 fue la bisagra: aplastada la revuelta campesina, la Reforma quedó en manos de príncipes y magistrados y la vía comunal desapareció como opción."},{"question":"¿Explica la ética protestante la ventaja económica del norte de Europa?","positions":[{"school":"Ética protestante (Max Weber, 1904-1905)","argument":"La vocación profesional, el ascetismo intramundano y la inquietud ante la incertidumbre de la salvación generaron una disposición al ahorro, al trabajo metódico y a la reinversión que favoreció la acumulación capitalista."},{"school":"Capital humano (Becker y Woessmann, 2009)","argument":"Midiendo la distancia de cada comarca prusiana a Wittenberg, la ventaja económica protestante desaparece al controlar por alfabetización: lo decisivo fue la obligación de leer la Biblia, no una ética específica."}],"state":"La correlación entre confesión y desarrollo se mantiene; el mecanismo propuesto por Weber está muy discutido. Hoy se explica sobre todo por educación y capital humano, y se subraya que la tesis original describía afinidades, no causalidad simple."}]},{"type":"timeline","items":[{"date":"1517","event":"Lutero envía sus 95 tesis al arzobispo de Maguncia."},{"date":"1520–1521","event":"Excomunión y Dieta de Worms: «no puedo ni quiero retractarme»."},{"date":"1522–1534","event":"Traducción de la Biblia al alemán, del Nuevo Testamento a la obra completa."},{"date":"1524–1525","event":"Guerra de los campesinos: Doce Artículos de Memmingen y represión con decenas de miles de muertos."},{"date":"1529","event":"Coloquio de Marburgo: Lutero y Zuinglio no logran acordar la eucaristía."},{"date":"1534","event":"Acta de Supremacía en Inglaterra; reino anabaptista de Münster."},{"date":"1536–1541","event":"Calvino publica la *Institución* y organiza Ginebra."},{"date":"1540","event":"Aprobación de la Compañía de Jesús."},{"date":"1545–1563","event":"Concilio de Trento en tres periodos."},{"date":"1555","event":"Paz de Augsburgo: cada príncipe fija la confesión de su territorio."},{"date":"1562–1598","event":"Guerras de religión en Francia; matanza de San Bartolomé en 1572."},{"date":"1568–1648","event":"Revuelta de los Países Bajos contra la monarquía hispánica."},{"date":"1598","event":"Edicto de Nantes: tolerancia limitada para los hugonotes."},{"date":"1618–1648","event":"Guerra de los Treinta Años."},{"date":"1648","event":"Paz de Westfalia: se reconoce también el calvinismo."}]},{"type":"sources","items":[{"author":"Martín Lutero","title":"Noventa y cinco tesis y carta a Alberto de Maguncia","year":"1517","kind":"primaria","note":"La carta está documentada; el clavado en la puerta lo relata Melanchthon en 1546."},{"author":"Martín Lutero","title":"A la nobleza cristiana de la nación alemana","year":"1520","kind":"primaria","note":"Apela a los príncipes para reformar la Iglesia y niega la distinción entre clérigos y laicos."},{"author":"Comunidades campesinas de Suabia","title":"Doce Artículos de Memmingen","year":"1525","kind":"primaria","note":"Programa de derechos colectivos fundado en citas bíblicas. Veinticinco ediciones en dos meses."},{"author":"Martín Lutero","title":"Contra las hordas asesinas y ladronas de campesinos","year":"1525","kind":"primaria","note":"Llama a los príncipes a reprimir sin misericordia. Documento clave del giro magisterial."},{"author":"Hermandad de Schleitheim","title":"Confesión de Schleitheim","year":"1527","kind":"primaria","note":"Programa anabaptista de separación pacífica del mundo, anterior al episodio de Münster."},{"author":"Felipe Melanchthon","title":"Confesión de Augsburgo","year":"1530","kind":"primaria","note":"Exposición oficial de la doctrina luterana presentada ante Carlos V."},{"author":"Parlamento inglés","title":"Acta de Supremacía","year":"1534","kind":"primaria","note":"Convierte al rey en cabeza de la Iglesia de Inglaterra por razones sucesorias y jurisdiccionales."},{"author":"Juan Calvino","title":"Institución de la religión cristiana","year":"1536-1559","kind":"primaria","note":"Sistema teológico completo y exportable. Base organizativa del calvinismo internacional."},{"author":"Concilio de Trento","title":"Decretos y cánones","year":"1545-1563","kind":"primaria","note":"Doctrina cerrada frente al protestantismo y reforma disciplinar del clero y de la parroquia."},{"author":"Enrique IV de Francia","title":"Edicto de Nantes","year":"1598","kind":"primaria","note":"Tolerancia limitada por agotamiento tras ocho guerras civiles. Revocado en 1685."},{"author":"Plenipotenciarios europeos","title":"Tratados de Osnabrück y Münster","year":"1648","kind":"primaria","note":"Reconocen el calvinismo y fijan 1624 como año normativo. No contienen doctrina de soberanía."},{"author":"Max Weber","title":"La ética protestante y el espíritu del capitalismo","year":"1904-1905","kind":"estudio","note":"Propone una afinidad entre ascetismo calvinista y acumulación capitalista."},{"author":"Hubert Jedin","title":"Katholische Reformation oder Gegenreformation?","year":"1946","kind":"estudio","note":"Distingue reforma católica interna y contrarreforma antiprotestante."},{"author":"Peter Blickle","title":"La revolución del hombre común","year":"1975","kind":"estudio","note":"La reforma comunal y la guerra campesina de 1525 como movimiento con programa propio."},{"author":"Diarmaid MacCulloch","title":"Reformation: Europe s House Divided","year":"2003","kind":"estudio","note":"Síntesis general del periodo, atenta a las periferias y a la Reforma radical."},{"author":"Andreas Osiander","title":"Sovereignty, International Relations and the Westphalian Myth","year":"2001","kind":"estudio","note":"Desmonta la lectura de 1648 como acta de nacimiento de la soberanía estatal."},{"author":"Sascha Becker y Ludger Woessmann","title":"Was Weber Wrong?","year":"2009","kind":"estudio","note":"Atribuye la ventaja económica protestante a la alfabetización y no a la ética."},{"author":"Andrew Pettegree","title":"Brand Luther","year":"2015","kind":"estudio","note":"La Reforma como fenómeno editorial y Wittenberg como centro de impresión."}]},{"type":"images","items":[{"src":"/img/reforma/portada.jpg","alt":"Retrato de medio cuerpo de Martín Lutero con hábito oscuro sobre fondo azul","width":1200,"height":1286,"role":"portada","caption":"Martín Lutero retratado por Lucas Cranach el Viejo en 1529.","author":"Lucas Cranach the Elder","title":"Martin Luther","year":"1529","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Martin_Luther%2C_1529.jpg"},{"src":"/img/reforma/tesis.jpg","alt":"Impreso antiguo a dos columnas en latín con las noventa y cinco tesis numeradas","width":1200,"height":675,"role":"figura","section":0,"caption":"Impresión temprana de las noventa y cinco tesis. La difusión por imprenta es lo que convirtió una disputa académica en un conflicto europeo.","author":"Ferdinand Pauwels","title":"Luther95theses","year":"1872","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Luther95theses.jpg"},{"src":"/img/reforma/calvino.jpg","alt":"Retrato de un hombre joven de rostro enjuto, con gorro y toga negra, sosteniendo un libro cerrado","width":1200,"height":1479,"role":"figura","section":3,"caption":"Juan Calvino. Su Ginebra fue el modelo que exportaron hugonotes, presbiterianos y puritanos: la Reforma no fue solo luterana.","author":"Flemish school (Unknown Unknown )","title":"John Calvin - Young","year":"571","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:John_Calvin_-_Young.jpg"},{"src":"/img/reforma/trento.jpg","alt":"Pintura de una gran asamblea de clérigos sentados en gradas dentro de una iglesia, con una alegoría femenina en primer plano","width":1200,"height":1181,"role":"figura","section":4,"caption":"El concilio de Trento, según Pasquale Cati (1588). Duró dieciocho años en tres etapas y fijó doctrina y disciplina hasta el siglo XX.","author":"Pasquale Cati","title":"Council of Trent","year":"1588","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:Council_of_Trent_by_Pasquale_Cati.jpg"},{"src":"/img/reforma/san-bartolome.jpg","alt":"Pintura de una matanza en las calles de una ciudad: cuerpos apilados, gente arrojada por ventanas y grupos armados","width":1200,"height":728,"role":"figura","section":5,"caption":"La matanza de San Bartolomé, 1572, pintada por François Dubois, hugonote que huyó de Francia. La guerra de religión es guerra civil antes que exterior.","author":"François Dubois 1529-1584","title":"St. Bartholomew''s Day massacre","year":"1572","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:La_masacre_de_San_Bartolom%C3%A9%2C_por_Fran%C3%A7ois_Dubois.jpg"}]}]'::jsonb, 0, true
